insert or replace into EnglishText (Tag, Text) values
  ("LOC_HD_INDUSTRY_EFFECT_TEXT",                                            "Industry Effects: [NEWLINE]{1_Effect}"),
  ("LOC_HD_CORPORATION_EFFECT_TEXT",                                         "Corporation Effects: [NEWLINE]{1_Effect}"),
  ("LOC_SELECT_INDUSTRY_CATEGORY_TEXT",                                      "[COLOR:Civ6Red]Click this icon to select category of Industry.[ENDCOLOR]"),
  ("LOC_SELECT_CORPORATION_CATEGORY_TEXT",                                   "[COLOR:Civ6Red]Click this icon to select category of Corporation.[ENDCOLOR]"),
  ("LOC_NEED_ACTIVATE_SECOND_INDUSTRY_EFFECT_TEXT",                          "[COLOR:Civ6Red]Need Tier 3 building of Commercial Hub or Tier 2 building of Harbor to activate the bonus of {1_Category} Industry: [ENDCOLOR][NEWLINE]{2_Effect}"),
  ("LOC_NEED_ACTIVATE_SECOND_CORPORATION_EFFECT_TEXT",                       "[COLOR:Civ6Red]Need Tier 4 building of Commercial Hub or Tier 3 building of Harbor to activate the bonus of {1_Category} Corporation: [ENDCOLOR][NEWLINE]{2_Effect}"),

  ("LOC_HD_CUSTOMEVENT_SELECT_INDUSTRY_CATEGORY_NAME",                       "[ICON_GreatWork_Product] {1_City}: {2_Resource} Industry"),
  ("LOC_HD_CUSTOMEVENT_SELECT_INDUSTRY_CATEGORY_DESCRIPTION",                "Now we need to make a choice: which usage of this resource should we focus on to activate the corresponding Industry bonus?"),
  ("LOC_HD_CUSTOMEVENT_SELECT_CORPORATION_CATEGORY_NAME",                    "[ICON_GreatWork_Product] {1_City}: {2_Resource} Corporation"),
  ("LOC_HD_CUSTOMEVENT_SELECT_CORPORATION_CATEGORY_DESCRIPTION",             "Now we need to make a choice: which usage of this resource should we focus on to activate the corresponding Corporation bonus?"),

  ("LOC_HD_BUILD_RESOURCE_BANANAS_INDUSTRY_TEXT",                            "The resourceful working people of {1_CityName} have selectively bred various bananas from wild grasses. Now it is time to select the best strains and sow them."),
  ("LOC_HD_BUILD_RESOURCE_BANANAS_CORPORATION_TEXT",                         "The bananas produced in {1_CityName} are sweet but difficult to preserve. Food processing plants plan to use these materials to make beverages and foods that are easy to transport and sell."),
  ("LOC_HD_RESOURCE_BANANAS_CROPS_INDUSTRY_DESCRIPTION",                     "The inhabitants of the forests in {1_CityName} have long been accustomed to using plantains as their staple food. Large-scale cultivation of plantains in the local forests makes good use of the land."),
  ("LOC_HD_RESOURCE_BANANAS_CROPS_CORPORATION_DESCRIPTION",                  "Commercial plantain plantations have brought deep development to the forestlands of {1_CityName}."),
  ("LOC_HD_RESOURCE_BANANAS_FRUIT_INDUSTRY_DESCRIPTION",                     "The local officials of {1_CityName} have offered bananas to your court for making summer fruit platters."),
  ("LOC_HD_RESOURCE_BANANAS_FRUIT_CORPORATION_DESCRIPTION",                  "With the establishment of a mature transportation system, the sweet bananas produced in {1_CityName} will reach thousands of households across our civilization."),

  ("LOC_HD_BUILD_RESOURCE_CATTLE_INDUSTRY_TEXT",                             "For thousands of years, the quality pastures around {1_CityName} have attracted herders migrating with their cattle."),
  ("LOC_HD_BUILD_RESOURCE_CATTLE_CORPORATION_TEXT",                          "“{1_CityName} cattle” has always been synonymous with high-quality breeds in our civilization. The establishment of modern animal husbandry will further promote selective breeding, providing citizens with abundant beef and dairy products."),
  ("LOC_HD_RESOURCE_CATTLE_BEVERAGE_INDUSTRY_DESCRIPTION",                   "Drinking milk helps the people of {1_CityName} thrive. Ranches have also become a pillar of the local industry."),
  ("LOC_HD_RESOURCE_CATTLE_BEVERAGE_CORPORATION_DESCRIPTION",                "Every year, countless gallons of milk are bottled in {1_CityName} factories and sent to the national market."),
  ("LOC_HD_RESOURCE_CATTLE_LEATHER_INDUSTRY_DESCRIPTION",                    "The leather craftsmen of {1_CityName} have established a powerful guild that dominates the local leather market."),
  ("LOC_HD_RESOURCE_CATTLE_LEATHER_CORPORATION_DESCRIPTION",                 "Leather garments and shoes produced in {1_CityName} adorn the citizens of our civilization."),

  ("LOC_HD_BUILD_RESOURCE_COPPER_INDUSTRY_TEXT",                             "The exposed emerald-green copper veins among the hills of {1_CityName} attracted the first miners to gather here."),
  ("LOC_HD_BUILD_RESOURCE_COPPER_CORPORATION_TEXT",                          "As geological exploration deepened, a modern metallurgical complex rose from the ground in {1_CityName}, integrating mining and smelting."),
  ("LOC_HD_RESOURCE_COPPER_METALLURGY_INDUSTRY_DESCRIPTION",                 "The copper smelting workshops in {1_CityName} operate day and night, turning ore into reddish copper ingots."),
  ("LOC_HD_RESOURCE_COPPER_METALLURGY_CORPORATION_DESCRIPTION",              "The standardized supply of copper materials keeps the industrial gears of our civilization running smoothly."),
  ("LOC_HD_RESOURCE_COPPER_MINTING_INDUSTRY_DESCRIPTION",                    "Copper from {1_CityName} is cast into holed coins, facilitating cross-regional trade."),
  ("LOC_HD_RESOURCE_COPPER_MINTING_CORPORATION_DESCRIPTION",                 "Copper coins from the Royal Mint of {1_CityName} are consistent in quality, becoming a trusted currency in the hearts of our people."),

  ("LOC_HD_BUILD_RESOURCE_CRABS_INDUSTRY_TEXT",                              "Every low tide, crabs can be seen foraging everywhere on the mudflats outside {1_CityName}, and villagers pick them up with buckets."),
  ("LOC_HD_BUILD_RESOURCE_CRABS_CORPORATION_TEXT",                           "The crab fishing fleet of {1_CityName} is equipped with the latest refrigeration technology, sending the fresh seafood to distant places."),
  ("LOC_HD_RESOURCE_CRABS_CUISINE_INDUSTRY_DESCRIPTION",                     "Chefs in {1_CityName} have meticulously developed various methods of cooking crab, attracting food lovers from all directions."),
  ("LOC_HD_RESOURCE_CRABS_CUISINE_CORPORATION_DESCRIPTION",                  "The crab-themed restaurant chain named after {1_CityName} blossoms everywhere across our civilization, with tantalizing aromas wafting through the streets."),
  ("LOC_HD_RESOURCE_CRABS_SEAFOOD_INDUSTRY_DESCRIPTION",                     "When the fishing boats of {1_CityName} return, their holds are full of plump crabs, bringing vitality to the port."),
  ("LOC_HD_RESOURCE_CRABS_SEAFOOD_CORPORATION_DESCRIPTION",                  "Canned crab meat and frozen crab legs set off from {1_CityName}, becoming delicious seafood dishes on our tables."),

  ("LOC_HD_BUILD_RESOURCE_DEER_INDUSTRY_TEXT",                               "In the lush green forests surrounding {1_CityName}, graceful deer, like forest spirits, have always been revered by hunters."),
  ("LOC_HD_BUILD_RESOURCE_DEER_CORPORATION_TEXT",                            "To protect wild deer populations while meeting market demand, a dedicated deer ranch has been established in {1_CityName}."),
  ("LOC_HD_RESOURCE_DEER_BEAST_INDUSTRY_DESCRIPTION",                        "In the royal hunting park of {1_CityName}, rare and exotic deer breeds from various regions are carefully nurtured for public viewing."),
  ("LOC_HD_RESOURCE_DEER_BEAST_CORPORATION_DESCRIPTION",                     "The well-preserved deer park makes {1_CityName} one of the most popular nature tourism destinations in our civilization."),
  ("LOC_HD_RESOURCE_DEER_LEATHER_INDUSTRY_DESCRIPTION",                      "Tanners in {1_CityName} are skilled at turning deerskin into extremely supple leather for making high-quality gloves."),
  ("LOC_HD_RESOURCE_DEER_LEATHER_CORPORATION_DESCRIPTION",                   "The “Fairy Deer” brand leather products of {1_CityName}, with their delicate texture, are highly favored by the upper class of our civilization."),

  ("LOC_HD_BUILD_RESOURCE_FISH_INDUSTRY_TEXT",                               "Every spring, schools of silvery Spanish mackerel migrate back to the coastal waters of {1_CityName}, and fishermen have long prepared their nets for this annual harvest."),
  ("LOC_HD_BUILD_RESOURCE_FISH_CORPORATION_TEXT",                            "Deep-sea fishing companies and cold-chain processing plants have settled in {1_CityName}, quick-freezing and slicing the mackerel, sending them continuously to inland markets."),
  ("LOC_HD_RESOURCE_FISH_CUISINE_INDUSTRY_DESCRIPTION",                      "Chefs in {1_CityName} mince the mackerel into a paste, then squeeze it into white, translucent fish noodles—so fresh it`s beyond belief."),
  ("LOC_HD_RESOURCE_FISH_CUISINE_CORPORATION_DESCRIPTION",                   "{1_CityName} Spanish mackerel wontons and fish dumplings, with their uniquely springy texture, stand out in our civilization`s frozen food sector."),
  ("LOC_HD_RESOURCE_FISH_SEAFOOD_INDUSTRY_DESCRIPTION",                      "At the morning market of {1_CityName}`s port, fresh Spanish mackerel glisten on crushed ice, and discerning customers come early to buy."),
  ("LOC_HD_RESOURCE_FISH_SEAFOOD_CORPORATION_DESCRIPTION",                   "{1_CityName}-produced mackerel fillets and fish balls are springy and delicious, becoming popular ingredients for hot pot and home cooking in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_RICE_INDUSTRY_TEXT",                               "The ancestors of {1_CityName} dug canals, turning swamps into mirror-like rice paddies. Since then, rice meals and fish dishes have become daily fare."),
  ("LOC_HD_BUILD_RESOURCE_RICE_CORPORATION_TEXT",                            "Rice mills and grain companies in {1_CityName} have introduced precision milling technology, making the rice grains crystal clear."),
  ("LOC_HD_RESOURCE_RICE_BREWING_INDUSTRY_DESCRIPTION",                      "Brewers in {1_CityName} discovered that fermenting and saccharifying rice yields clear, sweet rice wine."),
  ("LOC_HD_RESOURCE_RICE_BREWING_CORPORATION_DESCRIPTION",                   "{1_CityName} sake, with its elegant taste, has become a fine choice for banquets in our civilization."),
  ("LOC_HD_RESOURCE_RICE_CROPS_INDUSTRY_DESCRIPTION",                        "On the plains of {1_CityName}, waves of rice plants sway; the heavy ears of rice are the farmer`s greatest comfort."),
  ("LOC_HD_RESOURCE_RICE_CROPS_CORPORATION_DESCRIPTION",                     "As one of our civilization`s granaries, {1_CityName}`s stable rice production ensures the food supply for hundreds of millions."),

  ("LOC_HD_BUILD_RESOURCE_SHEEP_INDUSTRY_TEXT",                              "Shepherds on the high plateaus of {1_CityName} spend all year chasing water and grass with their flocks of sheep, like white clouds."),
  ("LOC_HD_BUILD_RESOURCE_SHEEP_CORPORATION_TEXT",                           "Textile industrialists, eyeing the high-quality wool of {1_CityName}, have established large-scale woolen mills here."),
  ("LOC_HD_RESOURCE_SHEEP_CLOTH_INDUSTRY_DESCRIPTION",                       "The looms of {1_CityName} creak and hum, turning fluffy wool into warm woolen fabric."),
  ("LOC_HD_RESOURCE_SHEEP_CLOTH_CORPORATION_DESCRIPTION",                    "“Warm Cloud” wool sweaters shipped from {1_CityName} warm countless cold winters in our civilization."),
  ("LOC_HD_RESOURCE_SHEEP_STATIONERY_INDUSTRY_DESCRIPTION",                  "Scrolls copied by scribes in {1_CityName} using locally sourced sheepskin still have clear writing after a thousand years."),
  ("LOC_HD_RESOURCE_SHEEP_STATIONERY_CORPORATION_DESCRIPTION",               "The {1_CityName} parchment factory provides durable writing materials for our civilization`s archives and important documents."),

  ("LOC_HD_BUILD_RESOURCE_STONE_INDUSTRY_TEXT",                              "On the edge of {1_CityName} stand large deposits of andesite, hard and excellent building stone."),
  ("LOC_HD_BUILD_RESOURCE_STONE_CORPORATION_TEXT",                           "Quarrying companies use mechanical cutting and rail transport to dramatically increase the stone output of {1_CityName}."),
  ("LOC_HD_RESOURCE_STONE_CONSTRUCTION_INDUSTRY_DESCRIPTION",                "Most buildings in {1_CityName} use locally sourced materials, with walls built from solid and imposing andesite."),
  ("LOC_HD_RESOURCE_STONE_CONSTRUCTION_CORPORATION_DESCRIPTION",             "Standard stone materials produced in {1_CityName} are widely used in various large-scale public works across our civilization."),
  ("LOC_HD_RESOURCE_STONE_STATIONERY_INDUSTRY_DESCRIPTION",                  "Stonemasons in {1_CityName} polish andesite slabs smooth for students to practice writing and arithmetic."),
  ("LOC_HD_RESOURCE_STONE_STATIONERY_CORPORATION_DESCRIPTION",               "Slate and chalk produced in {1_CityName} accompany generation after generation of schoolchildren in their early education."),

  ("LOC_HD_BUILD_RESOURCE_WHEAT_INDUSTRY_TEXT",                              "On the vast plains of {1_CityName}, golden wheat waves meet the blue sky, an intoxicating aura of abundance."),
  ("LOC_HD_BUILD_RESOURCE_WHEAT_CORPORATION_TEXT",                           "A large flour group has set up a storage and milling center in {1_CityName}, with the sound of mills never ceasing day or night."),
  ("LOC_HD_RESOURCE_WHEAT_BREWING_INDUSTRY_DESCRIPTION",                     "Monasteries in {1_CityName} carefully ferment surplus wheat to brew thirst-quenching ale."),
  ("LOC_HD_RESOURCE_WHEAT_BREWING_CORPORATION_DESCRIPTION",                  "The “Golden Ear” brewery in {1_CityName} innovatively uses hops, making craft beers that are all the rage in our civilization."),
  ("LOC_HD_RESOURCE_WHEAT_CROPS_INDUSTRY_DESCRIPTION",                       "At harvest time, farmers in {1_CityName} mobilize the whole family to wield sickles, ensuring every grain is brought home."),
  ("LOC_HD_RESOURCE_WHEAT_CROPS_CORPORATION_DESCRIPTION",                    "The aroma of the {1_CityName} bakery fills the entire block, as soft bread makes its way into thousands of homes."),

  ("LOC_HD_BUILD_RESOURCE_CITRUS_INDUSTRY_TEXT",                             "On the gentle, humid slopes of {1_CityName}, citrus trees with green leaves and golden fruits are planted."),
  ("LOC_HD_BUILD_RESOURCE_CITRUS_CORPORATION_TEXT",                          "{1_CityName} has become a hub for cold chain logistics, rapidly distributing perishable citrus fruits."),
  ("LOC_HD_RESOURCE_CITRUS_CUISINE_INDUSTRY_DESCRIPTION",                    "Housewives in {1_CityName} excel at making citrus peel into preserves and dried aged peel, turning freshness into depth."),
  ("LOC_HD_RESOURCE_CITRUS_CUISINE_CORPORATION_DESCRIPTION",                 "{1_CityName} citrus jam and marmalade are exported across our civilization, becoming the perfect companion for breakfast toast."),
  ("LOC_HD_RESOURCE_CITRUS_FRUIT_INDUSTRY_DESCRIPTION",                      "The bending branches heavy with honeyed tangerines are the taste of autumn in {1_CityName}; peel the thin skin, and your hands are filled with fragrance."),
  ("LOC_HD_RESOURCE_CITRUS_FRUIT_CORPORATION_DESCRIPTION",                   "The “Sweet Sun” citrus brand from {1_CityName} represents high-quality fresh sweetness in our civilization`s fruit market."),

  ("LOC_HD_BUILD_RESOURCE_COCOA_INDUSTRY_TEXT",                              "Under the shade of the tropical rainforests of {1_CityName}, cacao trees bear colorful, olive-ball-shaped fruits."),
  ("LOC_HD_BUILD_RESOURCE_COCOA_CORPORATION_TEXT",                           "Fermentation and drying bases have been established around the cacao plantations of {1_CityName}, controlling the initial processing of cacao beans."),
  ("LOC_HD_RESOURCE_COCOA_BEVERAGE_INDUSTRY_DESCRIPTION",                    "Nobles in {1_CityName} grind cacao beans into powder, add boiling water, mix in spices, and froth it up to drink the “drink of the gods.”"),
  ("LOC_HD_RESOURCE_COCOA_BEVERAGE_CORPORATION_DESCRIPTION",                 "The {1_CityName} cocoa powder company brings steaming, sweet cocoa to the children of our civilization."),
  ("LOC_HD_RESOURCE_COCOA_MINTING_INDUSTRY_DESCRIPTION",                     "In the markets of {1_CityName}, cacao beans in small sacks can be directly traded for jade, salt, and cloth."),
  ("LOC_HD_RESOURCE_COCOA_MINTING_CORPORATION_DESCRIPTION",                  "Cacao beans once served as small change throughout the long history of {1_CityName} and remain a symbol of wealth to this day."),

  ("LOC_HD_BUILD_RESOURCE_COFFEE_INDUSTRY_TEXT",                             "On the highlands of {1_CityName}, ruby-like coffee cherries hang from the branches and must be picked immediately when ripe."),
  ("LOC_HD_BUILD_RESOURCE_COFFEE_CORPORATION_TEXT",                          "Coffee chain giants have signed direct-purchase agreements with farms in {1_CityName} to create single-origin specialty coffee."),
  ("LOC_HD_RESOURCE_COFFEE_ART_INDUSTRY_DESCRIPTION",                        "In the cafes of {1_CityName}, poets and painters often gather to talk and find inspiration."),
  ("LOC_HD_RESOURCE_COFFEE_ART_CORPORATION_DESCRIPTION",                     "The annual {1_CityName} Coffee Culture Festival attracts artists from across our civilization to stay, giving birth to countless great works."),
  ("LOC_HD_RESOURCE_COFFEE_BEVERAGE_INDUSTRY_DESCRIPTION",                   "Mornings in {1_CityName} begin with a cup of strong black coffee, its invigorating aroma filling the streets and alleys."),
  ("LOC_HD_RESOURCE_COFFEE_BEVERAGE_CORPORATION_DESCRIPTION",                "{1_CityName} roasted coffee beans, with their balanced flavor, are revered as the daily essential by white-collar workers in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_COTTON_INDUSTRY_TEXT",                             "The sunshine of {1_CityName} bursts the cotton fields into white clouds; the cotton pickers` bags are stuffed full."),
  ("LOC_HD_BUILD_RESOURCE_COTTON_CORPORATION_TEXT",                          "The giant cotton ginning and spinning workshops in {1_CityName} produce cotton cloth that is sold to almost every corner of the earth."),
  ("LOC_HD_RESOURCE_COTTON_CLOTH_INDUSTRY_DESCRIPTION",                      "Cotton cloth woven in {1_CityName} is breathable and comfortable, allowing commoners to wear soft, close-fitting garments."),
  ("LOC_HD_RESOURCE_COTTON_CLOTH_CORPORATION_DESCRIPTION",                   "{1_CityName} pure cotton clothing, with its affordability and comfort, occupies half of the basic ready-to-wear market in our civilization."),
  ("LOC_HD_RESOURCE_COTTON_OIL_INDUSTRY_DESCRIPTION",                        "Oil pressers in {1_CityName} collect the cottonseed left over from ginning, pressing out cottonseed oil for use in lamps and soap."),
  ("LOC_HD_RESOURCE_COTTON_OIL_CORPORATION_DESCRIPTION",                     "The {1_CityName} cottonseed oil refinery turns by-products into treasure, supporting our civilization`s oleochemical and edible blend oil industries."),

  ("LOC_HD_BUILD_RESOURCE_DIAMONDS_INDUSTRY_TEXT",                           "In the ancient kimberlite pipes of {1_CityName}, gem-quality rough diamonds with brilliant fire lie hidden."),
  ("LOC_HD_BUILD_RESOURCE_DIAMONDS_CORPORATION_TEXT",                        "Standardized diamond mining has greatly increased production and reduced the bloody conflicts over resources in the {1_CityName} region."),
  ("LOC_HD_RESOURCE_DIAMONDS_ART_INDUSTRY_DESCRIPTION",                      "Crystal carvings using diamond-tipped tools, and artworks inspired by diamonds, are born in {1_CityName}."),
  ("LOC_HD_RESOURCE_DIAMONDS_ART_CORPORATION_DESCRIPTION",                   "The {1_CityName} De Beers style art diamond museum attracts wealthy collectors and artists from across our civilization to exchange ideas."),
  ("LOC_HD_RESOURCE_DIAMONDS_DECORATION_INDUSTRY_DESCRIPTION",               "Jewelers in {1_CityName} set diamonds into crowns and scepters, symbolizing supreme power and constancy."),
  ("LOC_HD_RESOURCE_DIAMONDS_DECORATION_CORPORATION_DESCRIPTION",            "Diamond engagement rings from the {1_CityName} cutting center illuminate the promises of countless lovers in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_DYES_INDUSTRY_TEXT",                               "Artisans in {1_CityName} have tried extracting precious dyes from all sorts of things, from seashells to mountain flowers, leaving no stone unturned."),
  ("LOC_HD_BUILD_RESOURCE_DYES_CORPORATION_TEXT",                            "The traditional method of extracting dyes from organisms struggles to meet market demand; chemists in {1_CityName} are working to solve this problem."),
  ("LOC_HD_RESOURCE_DYES_CLOTH_INDUSTRY_DESCRIPTION",                        "Dye houses in {1_CityName} dye white cloth into rainbow-like brilliant colors, making the entire city come alive."),
  ("LOC_HD_RESOURCE_DYES_CLOTH_CORPORATION_DESCRIPTION",                     "The fashion center provides cutting-edge color customization services for our civilization`s clothing brands."),
  ("LOC_HD_RESOURCE_DYES_MARINE_PRODUCTS_INDUSTRY_DESCRIPTION",              "Divers in {1_CityName} collect murex shells and seaweed, boiling them into priceless purple and indigo cloth."),
  ("LOC_HD_RESOURCE_DYES_MARINE_PRODUCTS_CORPORATION_DESCRIPTION",           "Natural pigments extracted from {1_CityName} marine products remain beloved for haute couture and art restoration."),

  ("LOC_HD_BUILD_RESOURCE_FURS_INDUSTRY_TEXT",                               "The harsh winter of {1_CityName} causes minks, foxes and other animals to grow thick fur, on which hunters depend for their livelihood."),
  ("LOC_HD_BUILD_RESOURCE_FURS_CORPORATION_TEXT",                            "A fur fashion group has set up shop in {1_CityName}, purchasing large quantities of fur to produce garments."),
  ("LOC_HD_RESOURCE_FURS_CLOTH_INDUSTRY_DESCRIPTION",                        "Designers in {1_CityName} use high-quality fur as an accent to create avant-garde fur fashion."),
  ("LOC_HD_RESOURCE_FURS_CLOTH_CORPORATION_DESCRIPTION",                     "{1_CityName} fur accessory brands have won multiple awards at our civilization`s autumn/winter fashion weeks."),
  ("LOC_HD_RESOURCE_FURS_LEATHER_INDUSTRY_DESCRIPTION",                      "The fur tanned by tanners in {1_CityName} is soft and splendid, making excellent fabric for winter clothing."),
  ("LOC_HD_RESOURCE_FURS_LEATHER_CORPORATION_DESCRIPTION",                   "{1_CityName} fur coats have become a status symbol in the wardrobes of the wealthy in the northern metropolises of our civilization."),

  ("LOC_HD_BUILD_RESOURCE_GYPSUM_INDUSTRY_TEXT",                             "The great salt lakes of {1_CityName} have deposited thick layers of gypsum, like compacted snow."),
  ("LOC_HD_BUILD_RESOURCE_GYPSUM_CORPORATION_TEXT",                          "Mechanized gypsum mines in {1_CityName} support the building decoration and medical industries."),
  ("LOC_HD_RESOURCE_GYPSUM_ART_INDUSTRY_DESCRIPTION",                        "Sculptors in {1_CityName} use plaster to make molds, turning momentary inspiration into eternal white statues."),
  ("LOC_HD_RESOURCE_GYPSUM_ART_CORPORATION_DESCRIPTION",                     "The fine, sticky plaster powder produced in {1_CityName} is standard teaching material for art academies across our civilization."),
  ("LOC_HD_RESOURCE_GYPSUM_MEDICINE_INDUSTRY_DESCRIPTION",                   "Orthopedic doctors in {1_CityName} use plaster bandages to fix broken bones, allowing the injured to heal in peace."),
  ("LOC_HD_RESOURCE_GYPSUM_MEDICINE_CORPORATION_DESCRIPTION",                "The {1_CityName} medical plaster company provides high-quality, fast-setting bone-healing materials to hospitals in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_INCENSE_INDUSTRY_TEXT",                            "Priests in the temples of {1_CityName} collect resins and fragrant woods; the curling smoke carries people`s prayers up to the sky."),
  ("LOC_HD_BUILD_RESOURCE_INCENSE_CORPORATION_TEXT",                         "A fragrance company has taken over the commercial production of {1_CityName} incense, packaging the aroma of faith into beautiful boxes."),
  ("LOC_HD_RESOURCE_INCENSE_CELEBRATION_INDUSTRY_DESCRIPTION",               "No celebration in {1_CityName} is complete without incense, from weddings to triumphs—aroma always accompanies."),
  ("LOC_HD_RESOURCE_INCENSE_CELEBRATION_CORPORATION_DESCRIPTION",            "Specially-made {1_CityName} celebratory incense is an indispensable mood-setter for our civilization`s national ceremonies and festivals."),
  ("LOC_HD_RESOURCE_INCENSE_MEDICINE_INDUSTRY_DESCRIPTION",                  "Physicians in {1_CityName} believe that incense can calm the mind and ward off miasma; lighting a stick makes the sickroom less stuffy."),
  ("LOC_HD_RESOURCE_INCENSE_MEDICINE_CORPORATION_DESCRIPTION",               "Medicinal incense produced in {1_CityName}, using the concept of respiratory administration, is regaining attention from modern medicine in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_IVORY_INDUSTRY_TEXT",                              "On the vast savannahs of {1_CityName}, majestic herds of elephants roam, leaving precious ivory, regarded as sacred by locals."),
  ("LOC_HD_BUILD_RESOURCE_IVORY_CORPORATION_TEXT",                           "Elephant Protection {1_CityName} is established to regulate the use of ivory."),
  ("LOC_HD_RESOURCE_IVORY_BEAST_INDUSTRY_DESCRIPTION",                       "A nature reserve has been established in {1_CityName}; the massive elephant herds become the area`s most spectacular sight."),
  ("LOC_HD_RESOURCE_IVORY_BEAST_CORPORATION_DESCRIPTION",                    "Ecotourism in {1_CityName}, featuring wild elephant viewing, attracts countless tourists from our civilization."),
  ("LOC_HD_RESOURCE_IVORY_DECORATION_INDUSTRY_DESCRIPTION",                  "Ivory carving masters in {1_CityName} can carve entire epic stories on a single tusk—truly ingenious."),
  ("LOC_HD_RESOURCE_IVORY_DECORATION_CORPORATION_DESCRIPTION",               "Ancient {1_CityName} ivory carvings are treasured by major museums in our civilization, representing the pinnacle of ancient craftsmanship."),

  ("LOC_HD_BUILD_RESOURCE_JADE_INDUSTRY_TEXT",                               "The riverbeds and mountain veins of {1_CityName} contain warm, delicate, fine jade."),
  ("LOC_HD_BUILD_RESOURCE_JADE_CORPORATION_TEXT",                            "A company has integrated traditional workshops in {1_CityName} and established a modern jade carving production line."),
  ("LOC_HD_RESOURCE_JADE_ART_INDUSTRY_DESCRIPTION",                          "Jade carving masters in {1_CityName} can skillfully use the colors of the jade to create lifelike landscapes and figures."),
  ("LOC_HD_RESOURCE_JADE_ART_CORPORATION_DESCRIPTION",                       "{1_CityName} jade carvings are eagerly collected by our civilization`s national museums and private collectors."),
  ("LOC_HD_RESOURCE_JADE_DECORATION_INDUSTRY_DESCRIPTION",                   "People in {1_CityName} believe jade protects the body; wearing jade pendants and bracelets is a common custom among men, women, young and old."),
  ("LOC_HD_RESOURCE_JADE_DECORATION_CORPORATION_DESCRIPTION",                "The safety buckles and jade plaques crafted by the {1_CityName} jade industry carry the prayers and nostalgia of our people."),

  ("LOC_HD_BUILD_RESOURCE_MARBLE_INDUSTRY_TEXT",                             "Quarries in {1_CityName} have sliced open mountains, revealing the white, warm, beautifully veined marble core."),
  ("LOC_HD_BUILD_RESOURCE_MARBLE_CORPORATION_TEXT",                          "A stone group has invested heavily in machinery to extract world-class building and sculpting stone from {1_CityName}."),
  ("LOC_HD_RESOURCE_MARBLE_ART_INDUSTRY_DESCRIPTION",                        "Great artistic geniuses have selected marble in {1_CityName}, freeing angels imprisoned in the stone."),
  ("LOC_HD_RESOURCE_MARBLE_ART_CORPORATION_DESCRIPTION",                     "{1_CityName} Carrara-grade marble statues adorn our civilization`s most renowned opera houses and plazas."),
  ("LOC_HD_RESOURCE_MARBLE_CONSTRUCTION_INDUSTRY_DESCRIPTION",               "Marble slabs from {1_CityName} are used to pave temple steps and palace walls, glossy and everlasting."),
  ("LOC_HD_RESOURCE_MARBLE_CONSTRUCTION_CORPORATION_DESCRIPTION",            "{1_CityName} marble curtain walls make our civilization`s skyscrapers shine with classical elegance."),

  ("LOC_HD_BUILD_RESOURCE_MERCURY_INDUSTRY_TEXT",                            "The cinnabar mines of {1_CityName} release mysterious silver liquid beads—mercury—upon roasting, fascinating alchemists."),
  ("LOC_HD_BUILD_RESOURCE_MERCURY_CORPORATION_TEXT",                         "Refineries have adopted new airtight processes to safely meet the industrial demand for mercury in {1_CityName}."),
  ("LOC_HD_RESOURCE_MERCURY_ART_INDUSTRY_DESCRIPTION",                       "The fluid form of mercury has inspired kinetic sculptors in {1_CityName} to create incredible works."),
  ("LOC_HD_RESOURCE_MERCURY_ART_CORPORATION_DESCRIPTION",                    "{1_CityName} mercury switch devices were once symbols of avant-garde art and precision instruments in our civilization."),
  ("LOC_HD_RESOURCE_MERCURY_CONSTRUCTION_INDUSTRY_DESCRIPTION",              "Craftsmen in {1_CityName} mix mercury with tin foil to coat statues and domes, forming a golden amalgam layer, resplendent and magnificent."),
  ("LOC_HD_RESOURCE_MERCURY_CONSTRUCTION_CORPORATION_DESCRIPTION",           "Mercury from {1_CityName} is used in large-scale gold mining`s amalgamation process, an unsung hero behind our civilization`s gold production."),

  ("LOC_HD_BUILD_RESOURCE_PEARLS_INDUSTRY_TEXT",                             "Divers in {1_CityName} hold their breath and descend, bringing back pearl oysters from the seafloor that hold miracles."),
  ("LOC_HD_BUILD_RESOURCE_PEARLS_CORPORATION_TEXT",                          "Seawater pearl farms in {1_CityName} bays have popularized nucleus implantation, making pearls round and controllable."),
  ("LOC_HD_RESOURCE_PEARLS_DECORATION_INDUSTRY_DESCRIPTION",                 "Artisans in {1_CityName} string pearls with silk thread to make crowns and necklaces, accentuating noble elegance."),
  ("LOC_HD_RESOURCE_PEARLS_DECORATION_CORPORATION_DESCRIPTION",              "{1_CityName} South Sea golden pearls and black pearls are essential collections in our civilization`s jewelry boxes."),
  ("LOC_HD_RESOURCE_PEARLS_MARINE_PRODUCTS_INDUSTRY_DESCRIPTION",            "Sea pearls produced in {1_CityName} carry the luster of their mother shells, the most precious gift for loved ones."),
  ("LOC_HD_RESOURCE_PEARLS_MARINE_PRODUCTS_CORPORATION_DESCRIPTION",         "{1_CityName} pearl powder, known for its beautifying effects, has a long history in our civilization`s herbal cosmetics."),

  ("LOC_HD_BUILD_RESOURCE_SALT_INDUSTRY_TEXT",                               "The salt pans of {1_CityName} are like mirrors to the sky, evaporating seawater and leaving behind snow-white salt crystals."),
  ("LOC_HD_BUILD_RESOURCE_SALT_CORPORATION_TEXT",                            "Industrialized salt wells in {1_CityName} are continuously supplying table salt to our civilization."),
  ("LOC_HD_RESOURCE_SALT_CHEMISTRY_INDUSTRY_DESCRIPTION",                    "The salt pans of {1_CityName} are not only a source of food but also raw materials for making soda ash and hydrochloric acid."),
  ("LOC_HD_RESOURCE_SALT_CHEMISTRY_CORPORATION_DESCRIPTION",                 "The {1_CityName} salt chemical base provides over half of our civilization`s chlor-alkali and plastic raw materials."),
  ("LOC_HD_RESOURCE_SALT_SEASONING_INDUSTRY_DESCRIPTION",                    "Chefs in {1_CityName} follow the ancient saying “no salt, no flavor,” using sea salt to bring out the natural taste of ingredients."),
  ("LOC_HD_RESOURCE_SALT_SEASONING_CORPORATION_DESCRIPTION",                 "{1_CityName} rose salt and flavored salts occupy a spot on the spice racks of our civilization`s gourmet enthusiasts."),

  ("LOC_HD_BUILD_RESOURCE_SILK_INDUSTRY_TEXT",                               "Silkworms rustle as they munch on mulberry leaves, spinning the most delicate threads—treasures of {1_CityName}."),
  ("LOC_HD_BUILD_RESOURCE_SILK_CORPORATION_TEXT",                            "Improved reeling and weaving machinery at {1_CityName} textile mills have brought silk, once only for nobles, to commoners as well."),
  ("LOC_HD_RESOURCE_SILK_CLOTH_INDUSTRY_DESCRIPTION",                        "Weavers in {1_CityName} use smooth silk threads to create gauze-like satin, shimmering with color."),
  ("LOC_HD_RESOURCE_SILK_CLOTH_CORPORATION_DESCRIPTION",                     "{1_CityName} silk evening gowns are the confident choice of our civilization`s movie stars on the red carpet."),
  ("LOC_HD_RESOURCE_SILK_MINTING_INDUSTRY_DESCRIPTION",                      "Bolts of plain {1_CityName} silk on the trade routes were as good as hard currency, exchangeable for distant horses and gems."),
  ("LOC_HD_RESOURCE_SILK_MINTING_CORPORATION_DESCRIPTION",                   "During economic crises, raw silk from {1_CityName} once even played the role of foreign exchange reserves."),

  ("LOC_HD_BUILD_RESOURCE_SILVER_INDUSTRY_TEXT",                             "Silver veins in the mountains of {1_CityName} gleam pale in the moonlight, attracting the earliest colonizers."),
  ("LOC_HD_BUILD_RESOURCE_SILVER_CORPORATION_TEXT",                          "Although silver`s role in modern currency has declined, scientists and engineers in {1_CityName} have discovered various industrial uses for silver."),
  ("LOC_HD_RESOURCE_SILVER_METALLURGY_INDUSTRY_DESCRIPTION",                 "Craftsmen in {1_CityName} discovered that silver has excellent ductility and conductivity, using it in jewelry and alloys."),
  ("LOC_HD_RESOURCE_SILVER_METALLURGY_CORPORATION_DESCRIPTION",              "{1_CityName} silver contacts and solders are key materials for high-end electronics and precision manufacturing in our civilization."),
  ("LOC_HD_RESOURCE_SILVER_MINTING_INDUSTRY_DESCRIPTION",                    "Hammers at the {1_CityName} mint fall continuously, producing silver coins bearing the city emblem, circulating far and wide."),
  ("LOC_HD_RESOURCE_SILVER_MINTING_CORPORATION_DESCRIPTION",                 "{1_CityName} silver bars were once the cornerstone of our civilization`s treasury, maintaining the credit of legal tender."),

  ("LOC_HD_BUILD_RESOURCE_SPICES_INDUSTRY_TEXT",                             "In the warm, humid valleys of {1_CityName}, cardamom bears clusters of fragrant flowers, hiding pungent seeds."),
  ("LOC_HD_BUILD_RESOURCE_SPICES_CORPORATION_TEXT",                          "A condiment company has turned cardamom from {1_CityName} into various spice powders and essential oils, sweeping the market."),
  ("LOC_HD_RESOURCE_SPICES_CELEBRATION_INDUSTRY_DESCRIPTION",                "During grand festivals in {1_CityName}, every household adds generous amounts of cardamom to their cooked meats for extra fragrance."),
  ("LOC_HD_RESOURCE_SPICES_CELEBRATION_CORPORATION_DESCRIPTION",             "{1_CityName} cardamom is used in high-end desserts and festive cakes in our civilization, symbolizing happiness and abundance."),
  ("LOC_HD_RESOURCE_SPICES_SEASONING_INDUSTRY_DESCRIPTION",                  "Chefs in {1_CityName} only need to add a little cardamom to curries and drinks to instantly transform ordinary ingredients into something magical."),
  ("LOC_HD_RESOURCE_SPICES_SEASONING_CORPORATION_DESCRIPTION",               "The “Green Fairy” cardamom spice produced in {1_CityName} is a secret weapon in home kitchens across our civilization."),

  ("LOC_HD_BUILD_RESOURCE_SUGAR_INDUSTRY_TEXT",                              "On the vast alluvial plains of {1_CityName}, sugarcane stands like a forest, forming a sweet green curtain."),
  ("LOC_HD_BUILD_RESOURCE_SUGAR_CORPORATION_TEXT",                           "Sugar mills along the railways of {1_CityName} have set up factories, turning fresh sugarcane into sparkling white sugar."),
  ("LOC_HD_RESOURCE_SUGAR_FRUIT_INDUSTRY_DESCRIPTION",                       "Street vendors in {1_CityName} skillfully peel the purple skin off sugarcane, offering customers a sweet chewing experience."),
  ("LOC_HD_RESOURCE_SUGAR_FRUIT_CORPORATION_DESCRIPTION",                    "Fresh-cut sugarcane fruit cups add a unique chewy snack to {1_CityName} cinemas and supermarkets."),
  ("LOC_HD_RESOURCE_SUGAR_SEASONING_INDUSTRY_DESCRIPTION",                   "Unrefined sugar and molasses from {1_CityName} are the secret to the rich, sweet aftertaste in local stews and sauces."),
  ("LOC_HD_RESOURCE_SUGAR_SEASONING_CORPORATION_DESCRIPTION",                "High-quality brown sugar from {1_CityName}, with its unique caramel aroma, is an excellent companion for health teas in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_TEA_INDUSTRY_TEXT",                                "On the misty tea mountains of {1_CityName}, the fingertips of tea-picking girls gently pinch the tender buds, harvesting the whole spring."),
  ("LOC_HD_BUILD_RESOURCE_TEA_CORPORATION_TEXT",                             "A trading company has consolidated tea gardens in {1_CityName} and modernized processes to stabilize tea yield and flavor."),
  ("LOC_HD_RESOURCE_TEA_BEVERAGE_INDUSTRY_DESCRIPTION",                      "In the teahouses of {1_CityName}, boiling water unfurls the leaves, releasing a fresh fragrance; a cup of tea speaks volumes about life."),
  ("LOC_HD_RESOURCE_TEA_BEVERAGE_CORPORATION_DESCRIPTION",                   "{1_CityName} tea bag brands allow busy modern people in our civilization to enjoy a good cup of tea anytime."),
  ("LOC_HD_RESOURCE_TEA_OIL_INDUSTRY_DESCRIPTION",                           "People in {1_CityName} collect tea seeds and use ancient wooden presses to extract camellia oil, used for cooking and hair care."),
  ("LOC_HD_RESOURCE_TEA_OIL_CORPORATION_DESCRIPTION",                        "{1_CityName} tea seed oil, with its high smoke point and delicate aroma, has become the standard oil in high-end kitchens across our civilization."),

  ("LOC_HD_BUILD_RESOURCE_TOBACCO_INDUSTRY_TEXT",                            "Tobacco leaves grown in the red soil of {1_CityName} are broad and thick, used by indigenous people in rituals to honor gods and treat illnesses."),
  ("LOC_HD_BUILD_RESOURCE_TOBACCO_CORPORATION_TEXT",                         "Tobacco companies have replaced traditional loose-leaf tobacco workshops in {1_CityName} with modern facilities; packaged cigarettes have taken the place of loose tobacco."),
  ("LOC_HD_RESOURCE_TOBACCO_CELEBRATION_INDUSTRY_DESCRIPTION",               "At tribal meetings in {1_CityName}, participants pass around a pipe, sharing the smoke, symbolizing peace and friendship."),
  ("LOC_HD_RESOURCE_TOBACCO_CELEBRATION_CORPORATION_DESCRIPTION",            "Premium {1_CityName} cigars have become classic props for celebrating business deals in our civilization."),
  ("LOC_HD_RESOURCE_TOBACCO_MEDICINE_INDUSTRY_DESCRIPTION",                  "Shamans in {1_CityName} apply tobacco leaves to wounds, believing it drives away pain and evil."),
  ("LOC_HD_RESOURCE_TOBACCO_MEDICINE_CORPORATION_DESCRIPTION",               "Nicotine extracted from {1_CityName} tobacco leaves is made into auxiliary agents for smoking cessation therapy in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_TRUFFLES_INDUSTRY_TEXT",                           "Under the oak forests of {1_CityName}, trained pigs and dogs can sniff out the unique aroma of truffles beneath the soil."),
  ("LOC_HD_BUILD_RESOURCE_TRUFFLES_CORPORATION_TEXT",                        "A trading group is responsible for organizing the harvest of truffles in {1_CityName} and quickly transporting this delicate delicacy via cold chain."),
  ("LOC_HD_RESOURCE_TRUFFLES_CUISINE_INDUSTRY_DESCRIPTION",                  "The white truffle season in {1_CityName} attracts gourmands from around the world, with sky-high bids at auctions."),
  ("LOC_HD_RESOURCE_TRUFFLES_CUISINE_CORPORATION_DESCRIPTION",               "{1_CityName} truffle risotto is all the rage in high-end restaurants in our civilization; experiencing it once is a taste peak."),
  ("LOC_HD_RESOURCE_TRUFFLES_SEASONING_INDUSTRY_DESCRIPTION",                "Chefs in {1_CityName} only need to shave a few thin truffle slices to turn a simple scrambled egg into something incredibly luxurious."),
  ("LOC_HD_RESOURCE_TRUFFLES_SEASONING_CORPORATION_DESCRIPTION",             "{1_CityName} truffle oil and truffle salt allow home cooks in our civilization to easily create Michelin-starred dishes."),

  ("LOC_HD_BUILD_RESOURCE_WHALES_INDUSTRY_TEXT",                             "The deep trenches off the coast of {1_CityName} are hunting grounds for sperm whales, leaving legends of their battles with giant squids."),
  ("LOC_HD_BUILD_RESOURCE_WHALES_CORPORATION_TEXT",                          "Deep-sea whaling and processing fleets depart from {1_CityName} to extract precious whale oil."),
  ("LOC_HD_RESOURCE_WHALES_MARINE_PRODUCTS_INDUSTRY_DESCRIPTION",            "The harbor of {1_CityName} is filled with the sweet smell of boiling whale blubber; street lamps burn unusually brightly at night."),
  ("LOC_HD_RESOURCE_WHALES_MARINE_PRODUCTS_CORPORATION_DESCRIPTION",         "{1_CityName} sperm whale oil once lit up the metropolises of our civilization, serving as the power foundation during the industrial revolution."),
  ("LOC_HD_RESOURCE_WHALES_SEA_BEAST_INDUSTRY_DESCRIPTION",                  "People in {1_CityName} revere the deep-sea giants; the giant sperm whale skeleton in the museum awes every visitor."),
  ("LOC_HD_RESOURCE_WHALES_SEA_BEAST_CORPORATION_DESCRIPTION",               "The {1_CityName} sperm whale-themed marine science exhibition tours our civilization, calling for a better understanding of marine ecology."),

  ("LOC_HD_BUILD_RESOURCE_WINE_INDUSTRY_TEXT",                               "The sunny, gravelly slopes of {1_CityName} are paradise for wine grapes, where ancient vines twist and grow."),
  ("LOC_HD_BUILD_RESOURCE_WINE_CORPORATION_TEXT",                            "Wineries have built magnificent castles and underground cellars in {1_CityName}, taking the wine business to the extreme."),
  ("LOC_HD_RESOURCE_WINE_BREWING_INDUSTRY_DESCRIPTION",                      "In the cellars of {1_CityName}, grape juice ferments in oak barrels, transforming into deep red wine over time."),
  ("LOC_HD_RESOURCE_WINE_BREWING_CORPORATION_DESCRIPTION",                   "{1_CityName} Cabernet Sauvignon dry red has won numerous gold awards at our civilization`s wine tasting competitions, commanding a high price."),
  ("LOC_HD_RESOURCE_WINE_FRUIT_INDUSTRY_DESCRIPTION",                        "The vineyards of {1_CityName} also produce thin-skinned, juicy table grapes, allowing people to enjoy the sweetness of summer directly."),
  ("LOC_HD_RESOURCE_WINE_FRUIT_CORPORATION_DESCRIPTION",                     "The {1_CityName} table grape brand “Purple Moonlight” is delivered via cold chain, maintaining its freshly-picked freshness in our civilization`s supermarkets."),

  ("LOC_HD_BUILD_RESOURCE_ALUMINUM_INDUSTRY_TEXT",                           "Beneath the red earth of {1_CityName} lie clay deposits rich in aluminum, ushering in the dawn of a modern metal."),
  ("LOC_HD_BUILD_RESOURCE_ALUMINUM_CORPORATION_TEXT",                        "An electrolytic aluminum smelter has risen in {1_CityName}, using abundant electricity to turn clay into silvery white aluminum."),
  ("LOC_HD_RESOURCE_ALUMINUM_CHEMISTRY_INDUSTRY_DESCRIPTION",                "Chemistry labs in {1_CityName} use aluminum as a reducing agent and a raw material for making water purifying flocculants."),
  ("LOC_HD_RESOURCE_ALUMINUM_CHEMISTRY_CORPORATION_DESCRIPTION",             "{1_CityName} alumina and aluminum salt products are key upstream materials for our civilization`s water treatment and cosmetics industries."),
  ("LOC_HD_RESOURCE_ALUMINUM_CONSTRUCTION_INDUSTRY_DESCRIPTION",             "{1_CityName} uses lightweight, strong aluminum alloys for airship frames and the curtain wall frames of skyscrapers."),
  ("LOC_HD_RESOURCE_ALUMINUM_CONSTRUCTION_CORPORATION_DESCRIPTION",          "The {1_CityName} aluminum base provides lightweight bodies for our civilization`s aerospace and high-speed rail industries."),

  ("LOC_HD_BUILD_RESOURCE_COAL_INDUSTRY_TEXT",                               "The layer of shiny, black coal in the strata of {1_CityName} is nature`s compressed solar energy."),
  ("LOC_HD_BUILD_RESOURCE_COAL_CORPORATION_TEXT",                            "A coal conglomerate has sunk deep shafts in {1_CityName}, using massive amounts of fossil fuel to power electrical equipment."),
  ("LOC_HD_RESOURCE_COAL_CHEMISTRY_INDUSTRY_DESCRIPTION",                    "Coking plants in {1_CityName} turn coal into gas and coke, extracting coal tar as a byproduct."),
  ("LOC_HD_RESOURCE_COAL_CHEMISTRY_CORPORATION_DESCRIPTION",                 "The {1_CityName} coal chemical complex supplies thousands of chemicals, from dyes to plastics and explosives, to our civilization."),
  ("LOC_HD_RESOURCE_COAL_FUEL_INDUSTRY_DESCRIPTION",                         "Locomotives in {1_CityName} burn local coal, pulling long carriages across mountains and rivers, puffing smoke and steam."),
  ("LOC_HD_RESOURCE_COAL_FUEL_CORPORATION_DESCRIPTION",                      "{1_CityName} anthracite is the most reliable guarantee for winter central heating in our civilization, warming thousands of homes."),

  ("LOC_HD_BUILD_RESOURCE_HORSES_INDUSTRY_TEXT",                             "On the fine pastures of {1_CityName}, horses gallop like the wind, the most loyal companions of warriors and travelers."),
  ("LOC_HD_BUILD_RESOURCE_HORSES_CORPORATION_TEXT",                          "A military horse farm and modern equine company are breeding fine horse breeds in {1_CityName}."),
  ("LOC_HD_RESOURCE_HORSES_LEATHER_INDUSTRY_DESCRIPTION",                    "{1_CityName} produces strong, durable horse leather for making boots, reins, and cavalry armor."),
  ("LOC_HD_RESOURCE_HORSES_LEATHER_CORPORATION_DESCRIPTION",                 "{1_CityName} horse rump hide, with its dense fibers, is a rare raw material for bespoke high-end shoes and bags in our civilization."),
  ("LOC_HD_RESOURCE_HORSES_TRANSIT_INDUSTRY_DESCRIPTION",                    "At the post station network of {1_CityName}, couriers changed horses but not riders, delivering urgent documents day and night."),
  ("LOC_HD_RESOURCE_HORSES_TRANSIT_CORPORATION_DESCRIPTION",                 "{1_CityName} competitive horse racing and carriage sightseeing inject a classical and elegant soul into our civilization`s tourism industry."),

  ("LOC_HD_BUILD_RESOURCE_IRON_INDUSTRY_TEXT",                               "The mountains of {1_CityName} contain red iron ore; ancient iron furnaces blaze bright."),
  ("LOC_HD_BUILD_RESOURCE_IRON_CORPORATION_TEXT",                            "An iron and steel complex has erected giant blast furnaces in {1_CityName}; the flowing molten iron lights up half the sky."),
  ("LOC_HD_RESOURCE_IRON_CONSTRUCTION_INDUSTRY_DESCRIPTION",                 "The blacksmith shops of {1_CityName} clang incessantly, forging cast iron into steel a hundred times over, creating durable tools and steel beams."),
  ("LOC_HD_RESOURCE_IRON_CONSTRUCTION_CORPORATION_DESCRIPTION",              "{1_CityName} H-beams and rebar form the steel skeleton of our civilization`s urbanization."),
  ("LOC_HD_RESOURCE_IRON_METALLURGY_INDUSTRY_DESCRIPTION",                   "Craftsmen in {1_CityName} know how to add different stones and charcoal to iron, turning it into sharper swords or more resilient springs."),
  ("LOC_HD_RESOURCE_IRON_METALLURGY_CORPORATION_DESCRIPTION",                "{1_CityName} specialty steel mills provide countless grades of alloy steel for our civilization`s precision manufacturing."),

  ("LOC_HD_BUILD_RESOURCE_NITER_INDUSTRY_TEXT",                              "On the dry soil surface of {1_CityName}, a layer of white saltpeter crystals has precipitated."),
  ("LOC_HD_BUILD_RESOURCE_NITER_CORPORATION_TEXT",                           "Saltpeter resources once triggered wars. Now, truffle enterprises in {1_CityName} are researching methods to synthesize saltpeter."),
  ("LOC_HD_RESOURCE_NITER_AGRICULTURE_INDUSTRY_DESCRIPTION",                 "Farmers in {1_CityName} discovered that sprinkling saltpeter powder into the soil makes crops grow exceptionally lush and green."),
  ("LOC_HD_RESOURCE_NITER_AGRICULTURE_CORPORATION_DESCRIPTION",              "The {1_CityName} nitrogen fertilizer industry, starting with saltpeter, sparked the first green revolution in our civilization."),
  ("LOC_HD_RESOURCE_NITER_HOUSEHOLD_INDUSTRY_DESCRIPTION",                   "Ancestors in {1_CityName} used saltpeter to make ice, preserving food and creating cold drinks in the era before electricity."),
  ("LOC_HD_RESOURCE_NITER_HOUSEHOLD_CORPORATION_DESCRIPTION",                "Companies in {1_CityName} have designed portable ice packs using the principle of nitrate refrigeration, making them an essential tool for outdoor medical care and camping."),

  ("LOC_HD_BUILD_RESOURCE_OIL_INDUSTRY_TEXT",                                "Beneath the deserts of {1_CityName} lies black gold formed from ancient remains; oil seeps to the surface and ignites when exposed to fire."),
  ("LOC_HD_BUILD_RESOURCE_OIL_CORPORATION_TEXT",                             "A state-owned oil company has erected derricks in {1_CityName}, drilling through rock layers and releasing gushing oil dragons."),
  ("LOC_HD_RESOURCE_OIL_CHEMISTRY_INDUSTRY_DESCRIPTION",                     "Cracking units in {1_CityName} extract ethylene and propylene from petroleum, building a synthetic world."),
  ("LOC_HD_RESOURCE_OIL_CHEMISTRY_CORPORATION_DESCRIPTION",                  "The {1_CityName} ethylene and plastics base supplies everything from packaging bags to artificial organs for our civilization."),
  ("LOC_HD_RESOURCE_OIL_FUEL_INDUSTRY_DESCRIPTION",                          "Refineries in {1_CityName} separate crude oil into gasoline and diesel, powering countless cars and generators."),
  ("LOC_HD_RESOURCE_OIL_FUEL_CORPORATION_DESCRIPTION",                       "The various petroleum products produced by {1_CityName} have always been the lifeblood of industry."),

  ("LOC_HD_BUILD_RESOURCE_URANIUM_INDUSTRY_TEXT",                            "Scientists have extracted uranium from the asphaltite in the rock layers of {1_CityName}, the key to unlocking the energy of the microscopic world."),
  ("LOC_HD_BUILD_RESOURCE_URANIUM_CORPORATION_TEXT",                         "our civilization`s nuclear industry secretly produces enriched uranium in {1_CityName} for national strategy and clean energy."),
  ("LOC_HD_RESOURCE_URANIUM_CONSTRUCTION_INDUSTRY_DESCRIPTION",              "The process of refining radioisotopes generates large amounts of waste; engineers in {1_CityName} use this waste to produce ceramics."),
  ("LOC_HD_RESOURCE_URANIUM_CONSTRUCTION_CORPORATION_DESCRIPTION",           "Though uranium sounds mysterious, uranium-containing ceramics produced in {1_CityName} have become part of the daily life of our people."),
  ("LOC_HD_RESOURCE_URANIUM_FUEL_INDUSTRY_DESCRIPTION",                      "Fuel rods in the {1_CityName} nuclear power plant silently release heat in the reactor core, lighting up the brilliant lights of thousands of homes."),
  ("LOC_HD_RESOURCE_URANIUM_FUEL_CORPORATION_DESCRIPTION",                   "{1_CityName} enriched uranium provides powerful and long-lasting hearts for our civilization`s aircraft carrier fleets and deep space probes."),

  ("LOC_HD_BUILD_RESOURCE_AMBER_INDUSTRY_TEXT",                              "Amber has been known to the people of {1_CityName} for hundreds of years, as these crystalline treasures can be seen from the bottom of the shallows to the hills."),
  ("LOC_HD_BUILD_RESOURCE_AMBER_CORPORATION_TEXT",                           "Amber jewelry and art companies systematically collect raw amber from {1_CityName} for cutting and design."),
  ("LOC_HD_RESOURCE_AMBER_ART_INDUSTRY_DESCRIPTION",                         "In the amber room of {1_CityName}, thousands of amber pieces are inlaid into golden-red walls, magnificently unmatched."),
  ("LOC_HD_RESOURCE_AMBER_ART_CORPORATION_DESCRIPTION",                      "{1_CityName} amber paintings and jewelry designers bring an aesthetic of frozen time to our civilization`s collectors."),
  ("LOC_HD_RESOURCE_AMBER_MARINE_PRODUCTS_INDUSTRY_DESCRIPTION",             "After storms, women in {1_CityName} bend over on the beach to pick up sea amber washed ashore."),
  ("LOC_HD_RESOURCE_AMBER_MARINE_PRODUCTS_CORPORATION_DESCRIPTION",          "Raw sea amber from {1_CityName}, rich in inclusions, is an information treasure trove for geologists in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_OLIVES_INDUSTRY_TEXT",                             "On the stony hills of {1_CityName}, silver-green olive groves carry millennia of meaning—peace and abundance."),
  ("LOC_HD_BUILD_RESOURCE_OLIVES_CORPORATION_TEXT",                          "An olive oil pressing factory has introduced temperature-controlled cold-pressing lines to ensure the highest quality of {1_CityName} olive oil."),
  ("LOC_HD_RESOURCE_OLIVES_OIL_INDUSTRY_DESCRIPTION",                        "Stone mills in {1_CityName} crush olives into golden, translucent liquid gold; dripping it on bread is an exquisite delight."),
  ("LOC_HD_RESOURCE_OLIVES_OIL_CORPORATION_DESCRIPTION",                     "{1_CityName} extra virgin olive oil, with its health benefits and flavor, has completely conquered our civilization`s culinary world."),
  ("LOC_HD_RESOURCE_OLIVES_SEASONING_INDUSTRY_DESCRIPTION",                  "Pairing salted {1_CityName} olives with meals brings out the natural freshness of ingredients, core to Mediterranean-style cuisine."),
  ("LOC_HD_RESOURCE_OLIVES_SEASONING_CORPORATION_DESCRIPTION",               "Oil-cured {1_CityName} olive jars are the darlings of cold platters and appetizers at family gatherings in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_TURTLES_INDUSTRY_TEXT",                            "On the white sandy beaches of {1_CityName}, under the moonlight, giant sea turtles crawl ashore to lay their eggs."),
  ("LOC_HD_BUILD_RESOURCE_TURTLES_CORPORATION_TEXT",                         "A sea turtle ecology research institute has recorded the complete life cycle of sea turtles in the shallows of {1_CityName}."),
  ("LOC_HD_RESOURCE_TURTLES_DECORATION_INDUSTRY_DESCRIPTION",                "Craftsmen in {1_CityName} polish and finish turtle shells, creating exquisite tortoiseshell combs and eyeglass frames."),
  ("LOC_HD_RESOURCE_TURTLES_DECORATION_CORPORATION_DESCRIPTION",             "The imitation tortoiseshell resin craft of {1_CityName} inherits ancient patterns, becoming a key element of retro fashion in our civilization."),
  ("LOC_HD_RESOURCE_TURTLES_SEAFOOD_INDUSTRY_DESCRIPTION",                   "Within traditional allowances, indigenous people in {1_CityName} eat sea turtle meat; turtle soup is a rare delicacy."),
  ("LOC_HD_RESOURCE_TURTLES_SEAFOOD_CORPORATION_DESCRIPTION",                "Traditional turtle soup from {1_CityName} has been revived in canned form, offering a taste window into the original marine culture of our civilization."),

  ("LOC_HD_BUILD_RESOURCE_C_HEAVENLY_HORSE_INDUSTRY_TEXT",                   "On the grasslands of {1_CityName}, horses that sweat blood race across the land, said to be descendants of celestial horses."),
  ("LOC_HD_BUILD_RESOURCE_C_HEAVENLY_HORSE_CORPORATION_TEXT",                "A selective breeding center in {1_CityName} uses modern genetics to preserve the excellent bloodlines of the Akhal-Teke horse."),
  ("LOC_HD_RESOURCE_C_HEAVENLY_HORSE_BEAST_INDUSTRY_DESCRIPTION",            "The Akhal-Teke horses of {1_CityName} are beautifully built, their coats shining like metal in the sunlight, treasured by kings."),
  ("LOC_HD_RESOURCE_C_HEAVENLY_HORSE_BEAST_CORPORATION_DESCRIPTION",         "The {1_CityName} Akhal-Teke equestrian performance troupe tours our civilization, causing a sensation at every appearance."),
  ("LOC_HD_RESOURCE_C_HEAVENLY_HORSE_TRANSIT_INDUSTRY_DESCRIPTION",          "Riding {1_CityName} Akhal-Teke horses, messengers could cross the desert in two days, delivering the most important military intelligence."),
  ("LOC_HD_RESOURCE_C_HEAVENLY_HORSE_TRANSIT_CORPORATION_DESCRIPTION",       "The descendants of {1_CityName}`s Akhal-Teke horses have improved our civilization`s cavalry and racehorse breeds."),

  ("LOC_HD_BUILD_RESOURCE_C_ZEBU_INDUSTRY_TEXT",                             "The ritual of worshipping humped cattle by the river in {1_CityName} has been passed down for over a dozen generations."),
  ("LOC_HD_BUILD_RESOURCE_C_ZEBU_CORPORATION_TEXT",                          "A humped cattle breeding association in {1_CityName} uses modern ranches to selectively breed zebus for ancient ritual activities in {1_CityName}."),
  ("LOC_HD_RESOURCE_C_ZEBU_BEAST_INDUSTRY_DESCRIPTION",                      "The humped cattle of {1_CityName} are seen as sacred mounts, adorned with splendid brocade and bells to participate in sacrifices."),
  ("LOC_HD_RESOURCE_C_ZEBU_BEAST_CORPORATION_DESCRIPTION",                   "With their unique appearance, {1_CityName} humped cattle become stars at our civilization`s exotic film studios and zoos."),
  ("LOC_HD_RESOURCE_C_ZEBU_TRANSIT_INDUSTRY_DESCRIPTION",                    "Caravans in {1_CityName} rely on humped cattle to traverse the arid wilderness; they are land ships beyond the ships of the desert."),
  ("LOC_HD_RESOURCE_C_ZEBU_TRANSIT_CORPORATION_DESCRIPTION",                 "{1_CityName} humped cattle helped pioneer remote villages in our civilization and remain indispensable draught animals on some farms."),

  ("LOC_HD_BUILD_RESOURCE_MAIZE_INDUSTRY_TEXT",                              "The sun and fertile soil of {1_CityName} make corn stalks grow taller than a man, producing plump ears of grain."),
  ("LOC_HD_BUILD_RESOURCE_MAIZE_CORPORATION_TEXT",                           "A grain processing company has built a plant in {1_CityName}, converting corn into various food and industrial raw materials."),
  ("LOC_HD_RESOURCE_MAIZE_CROPS_INDUSTRY_DESCRIPTION",                       "The markets of {1_CityName} are piled high with golden corn cobs, the staple food of locals."),
  ("LOC_HD_RESOURCE_MAIZE_CROPS_CORPORATION_DESCRIPTION",                    "Corn flakes and puffed snacks flow from the assembly lines of {1_CityName}, becoming the favorite snack of children in our civilization."),
  ("LOC_HD_RESOURCE_MAIZE_SEASONING_INDUSTRY_DESCRIPTION",                   "Elderly women in {1_CityName} use stone mortars to grind dried corn into uniquely flavored powdered seasoning."),
  ("LOC_HD_RESOURCE_MAIZE_SEASONING_CORPORATION_DESCRIPTION",                "Corn seasoning sauce produced in {1_CityName}, with its unique smoky spiciness, holds a place in our civilization`s culinary world."),

  ("LOC_HD_BUILD_RESOURCE_HONEY_INDUSTRY_TEXT",                              "The wildflower-covered meadows of {1_CityName} are a beekeeper`s paradise, with hives on display and bees buzzing."),
  ("LOC_HD_BUILD_RESOURCE_HONEY_CORPORATION_TEXT",                           "Golden liquid honey is filtered, bottled, and shipped from processing plants in {1_CityName}."),
  ("LOC_HD_RESOURCE_HONEY_METALLURGY_INDUSTRY_DESCRIPTION",                  "Foundry craftsmen in {1_CityName} discovered that beeswax burns without smoke, making it excellent for creating molds for precision castings."),
  ("LOC_HD_RESOURCE_HONEY_METALLURGY_CORPORATION_DESCRIPTION",               "The beeswax lost-wax casting method of {1_CityName} provides a perfect replication process for our civilization`s bronze sculptures and jewelry."),
  ("LOC_HD_RESOURCE_HONEY_SEASONING_INDUSTRY_DESCRIPTION",                   "The honey of {1_CityName} is golden with floral notes; using it instead of sugar makes tea and pastries healthier."),
  ("LOC_HD_RESOURCE_HONEY_SEASONING_CORPORATION_DESCRIPTION",                "{1_CityName} wildflower honey is a star seasoning in organic food stores in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_SUK_CHEESE_INDUSTRY_TEXT",                         "The livestock of {1_CityName} produce fragrant milk, and the surplus is processed into various dairy products."),
  ("LOC_HD_BUILD_RESOURCE_SUK_CHEESE_CORPORATION_TEXT",                      "A dairy group has merged {1_CityName}`s traditional artisanal cheese-making with modern hygiene standards, launching it nationwide."),
  ("LOC_HD_RESOURCE_SUK_CHEESE_CUISINE_INDUSTRY_DESCRIPTION",                "People in {1_CityName} grate cheese and sprinkle it over steaming noodles; rich and stringy, it brings pure happiness."),
  ("LOC_HD_RESOURCE_SUK_CHEESE_CUISINE_CORPORATION_DESCRIPTION",             "A wheel of {1_CityName} Parmigiano-Reggiano is treated as a treasure in our civilization`s Italian restaurants."),
  ("LOC_HD_RESOURCE_SUK_CHEESE_SEASONING_INDUSTRY_DESCRIPTION",              "The blue cheese of {1_CityName} is salty and pungent; just a little gives a whole dish soul."),
  ("LOC_HD_RESOURCE_SUK_CHEESE_SEASONING_CORPORATION_DESCRIPTION",           "{1_CityName} cheese powder and cheese sauce are the secret weapons of our civilization`s snack industry and fast food."),

  ("LOC_HD_BUILD_RESOURCE_SUK_CAMEL_INDUSTRY_TEXT",                          "With the tinkling of camel bells, {1_CityName} is a hub on the desert caravan route; camels are the most reliable partners here."),
  ("LOC_HD_BUILD_RESOURCE_SUK_CAMEL_CORPORATION_TEXT",                       "A modern logistics company has purchased camel teams to provide the most flexible transportation solutions for the complex terrain of the {1_CityName} region."),
  ("LOC_HD_RESOURCE_SUK_CAMEL_LEATHER_INDUSTRY_DESCRIPTION",                 "Tanners in {1_CityName} use camel skin to make durable saddles and waterskins, highly popular among herders."),
  ("LOC_HD_RESOURCE_SUK_CAMEL_LEATHER_CORPORATION_DESCRIPTION",              "The camel leather workshop in {1_CityName} develops retro-style bags, becoming a fashion item in our civilization."),
  ("LOC_HD_RESOURCE_SUK_CAMEL_TRANSIT_INDUSTRY_DESCRIPTION",                 "Camel caravans in {1_CityName} are laden with goods, traveling between oases and towns, bringing exotic treasures from afar."),
  ("LOC_HD_RESOURCE_SUK_CAMEL_TRANSIT_CORPORATION_DESCRIPTION",              "Although the “Silk Road Camel Team” transport company in {1_CityName} now uses trucks, the resilient spirit it symbolizes remains a source of pride for our civilization."),

  ("LOC_HD_BUILD_RESOURCE_SUK_OBSIDIAN_INDUSTRY_TEXT",                       "At the foot of the volcanoes in {1_CityName}, shiny black obsidian fragments are scattered, their edges as sharp as a scalpel."),
  ("LOC_HD_BUILD_RESOURCE_SUK_OBSIDIAN_CORPORATION_TEXT",                    "Indigenous communities in {1_CityName} have scaled up obsidian mining, crafting artifacts to convey their native culture."),
  ("LOC_HD_RESOURCE_SUK_OBSIDIAN_ART_INDUSTRY_DESCRIPTION",                  "Craftsmen in {1_CityName} use obsidian to make ritual masks, their black luster full of mystery."),
  ("LOC_HD_RESOURCE_SUK_OBSIDIAN_ART_CORPORATION_DESCRIPTION",               "Modern obsidian sculptures from {1_CityName}, utilizing the material`s properties, shine brightly in our civilization`s art exhibitions."),
  ("LOC_HD_RESOURCE_SUK_OBSIDIAN_DECORATION_INDUSTRY_DESCRIPTION",           "People in {1_CityName} polish obsidian into mirror-like breastplates and pendants, believing it absorbs negative energy."),
  ("LOC_HD_RESOURCE_SUK_OBSIDIAN_DECORATION_CORPORATION_DESCRIPTION",        "{1_CityName} obsidian pendants and ornaments, with their apotropaic meaning, are deeply trusted by feng shui enthusiasts in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_SUK_SHARK_INDUSTRY_TEXT",                          "Various sharks swim in the seas of {1_CityName}; local fishermen revere them as guardians of the ocean and coexist cautiously."),
  ("LOC_HD_BUILD_RESOURCE_SUK_SHARK_CORPORATION_TEXT",                       "A marine biotechnology company has targeted sharks in {1_CityName}, fully extracting their high-value components."),
  ("LOC_HD_RESOURCE_SUK_SHARK_MARINE_PRODUCTS_INDUSTRY_DESCRIPTION",         "Fishermen in {1_CityName} dry shark skin in the sun to polish wood or make tough leather."),
  ("LOC_HD_RESOURCE_SUK_SHARK_MARINE_PRODUCTS_CORPORATION_DESCRIPTION",      "{1_CityName} shark fin was once a symbol of prestige at high-end banquets in our civilization; now it has been replaced by sustainable imitation fin."),
  ("LOC_HD_RESOURCE_SUK_SHARK_MEDICINE_INDUSTRY_DESCRIPTION",                "Folk remedies in {1_CityName} extract liver oil from shark livers to boost immunity."),
  ("LOC_HD_RESOURCE_SUK_SHARK_MEDICINE_CORPORATION_DESCRIPTION",             "{1_CityName} shark chondroitin and squalene products are cutting-edge ingredients for joint care and skincare in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_DLV_BISON_INDUSTRY_TEXT",                          "Herds of bison thunder across the great prairies of {1_CityName}, their hooves like rolling thunder; the indigenous people hunt them with reverence."),
  ("LOC_HD_BUILD_RESOURCE_DLV_BISON_CORPORATION_TEXT",                       "Ranchers in {1_CityName} have fenced and fattened bison, using scientific breeding to make the meat more succulent."),
  ("LOC_HD_RESOURCE_DLV_BISON_CUISINE_INDUSTRY_DESCRIPTION",                 "On the grills of {1_CityName}, thick-cut bison meat sizzles—the taste of the earth."),
  ("LOC_HD_RESOURCE_DLV_BISON_CUISINE_CORPORATION_DESCRIPTION",              "{1_CityName} bison steakhouse, with its bold style, attracts countless meat lovers in our civilization."),
  ("LOC_HD_RESOURCE_DLV_BISON_LEATHER_INDUSTRY_DESCRIPTION",                 "Bison hide is thick and tough; artisans in {1_CityName} turn it into leather tents that can be passed down for generations."),
  ("LOC_HD_RESOURCE_DLV_BISON_LEATHER_CORPORATION_DESCRIPTION",              "Boots and belts made from {1_CityName} bison leather are a hallmark of rugged manliness in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_GOLD_INDUSTRY_TEXT",                               "The streams of {1_CityName} sparkle with specks of gold, attracting countless people on gold rush dreams."),
  ("LOC_HD_BUILD_RESOURCE_GOLD_CORPORATION_TEXT",                            "A gold mining group uses the cyanidation process to massively extract gold deposits from {1_CityName}."),
  ("LOC_HD_RESOURCE_GOLD_METALLURGY_INDUSTRY_DESCRIPTION",                   "Goldsmiths in {1_CityName} draw gold into threads as fine as hair, inlaying them into holy vessels and scripture boxes."),
  ("LOC_HD_RESOURCE_GOLD_METALLURGY_CORPORATION_DESCRIPTION",                "{1_CityName} semiconductor gold bonding wires silently transmit signals in every chip of our civilization."),
  ("LOC_HD_RESOURCE_GOLD_MINTING_INDUSTRY_DESCRIPTION",                      "In the treasury of {1_CityName}, entire gold bricks are stacked, their glow bringing a sense of stability and peace."),
  ("LOC_HD_RESOURCE_GOLD_MINTING_CORPORATION_DESCRIPTION",                   "{1_CityName} gold bullion is the ultimate asset for settlements among central banks worldwide, symbolizing absolute wealth."),

  ("LOC_HD_BUILD_RESOURCE_JNR_PEAT_INDUSTRY_TEXT",                           "In the marshes of {1_CityName}, ancestors dug up black, spongy peat to use as firewood for heating."),
  ("LOC_HD_BUILD_RESOURCE_JNR_PEAT_CORPORATION_TEXT",                        "A peat extraction company has laid light rail in {1_CityName}, supplying peat as a cheap energy source to the market."),
  ("LOC_HD_RESOURCE_JNR_PEAT_AGRICULTURE_INDUSTRY_DESCRIPTION",              "Farmers in {1_CityName} mix dried peat with animal manure to create an efficient base fertilizer for improving fields."),
  ("LOC_HD_RESOURCE_JNR_PEAT_AGRICULTURE_CORPORATION_DESCRIPTION",           "The horticulture company`s peat nutrition pots from {1_CityName} are beloved by family farmers in our civilization."),
  ("LOC_HD_RESOURCE_JNR_PEAT_FUEL_INDUSTRY_DESCRIPTION",                     "In every household in {1_CityName}, peat burns in fireplaces, emitting a unique earthy aroma and warmth."),
  ("LOC_HD_RESOURCE_JNR_PEAT_FUEL_CORPORATION_DESCRIPTION",                  "A thermal power plant in {1_CityName} uses peat as fuel, providing important power during our civilization`s early industrialization."),

  ("LOC_HD_BUILD_RESOURCE_P0K_PENGUINS_INDUSTRY_TEXT",                       "The icy shores of {1_CityName} are a breeding ground for penguins; they are adorable and numerous."),
  ("LOC_HD_BUILD_RESOURCE_P0K_PENGUINS_CORPORATION_TEXT",                    "Travel agencies carefully develop polar science and sightseeing projects at the penguin habitats of {1_CityName}."),
  ("LOC_HD_RESOURCE_P0K_PENGUINS_BEAST_INDUSTRY_DESCRIPTION",                "The sight of penguin colonies waddling across the road in {1_CityName} melts everyone`s heart."),
  ("LOC_HD_RESOURCE_P0K_PENGUINS_BEAST_CORPORATION_DESCRIPTION",             "Live penguin streams and documentaries from {1_CityName} bring polar enlightenment to children in our civilization."),
  ("LOC_HD_RESOURCE_P0K_PENGUINS_SEA_BEAST_INDUSTRY_DESCRIPTION",            "Early explorers hunted penguins in {1_CityName} for their thick subcutaneous fat, used as fuel."),
  ("LOC_HD_RESOURCE_P0K_PENGUINS_SEA_BEAST_CORPORATION_DESCRIPTION",         "The abandoned blubber-boiling cauldrons in {1_CityName} have become memorial landmarks for our civilization`s polar exploration history."),

  ("LOC_HD_BUILD_RESOURCE_CVS_POMEGRANATES_INDUSTRY_TEXT",                   "In the courtyards of {1_CityName}, pomegranate trees burst into fiery red flowers, then bear fruit like gem-filled caskets."),
  ("LOC_HD_BUILD_RESOURCE_CVS_POMEGRANATES_CORPORATION_TEXT",                "A fruit company cultivates ornamental and fruiting pomegranates in {1_CityName} to meet different needs."),
  ("LOC_HD_RESOURCE_CVS_POMEGRANATES_FRUIT_INDUSTRY_DESCRIPTION",            "Cut open a large pomegranate from {1_CityName}, and the glossy, ruby-like seeds are packed densely, sweet and thirst-quenching."),
  ("LOC_HD_RESOURCE_CVS_POMEGRANATES_FRUIT_CORPORATION_DESCRIPTION",         "The {1_CityName} pomegranate juice brand turns this ancient fruit into an antioxidant health drink, popular across our civilization."),
  ("LOC_HD_RESOURCE_CVS_POMEGRANATES_ORNAMENTAL_INDUSTRY_DESCRIPTION",       "{1_CityName} turns old, gnarled pomegranate trees into bonsai, symbolizing fertility and adorning elegant halls."),
  ("LOC_HD_RESOURCE_CVS_POMEGRANATES_ORNAMENTAL_CORPORATION_DESCRIPTION",    "{1_CityName} pomegranate bonsai is exported overseas, becoming a treasured collector`s item for gardening enthusiasts in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_P0K_PAPYRUS_INDUSTRY_TEXT",                        "In the shallow marshes along the river in {1_CityName}, papyrus stands tall, its tips like rays of sunlight."),
  ("LOC_HD_BUILD_RESOURCE_P0K_PAPYRUS_CORPORATION_TEXT",                     "A cultural and creative enterprise has revived the production of this legendary writing material using papyrus from {1_CityName}."),
  ("LOC_HD_RESOURCE_P0K_PAPYRUS_HOUSEHOLD_INDUSTRY_DESCRIPTION",             "People in {1_CityName} weave papyrus into sandals, baskets, and boats; this light material is deeply integrated into daily life."),
  ("LOC_HD_RESOURCE_P0K_PAPYRUS_HOUSEHOLD_CORPORATION_DESCRIPTION",          "Eco-friendly wallpaper and mats made from {1_CityName} papyrus fiber lead the green home furnishing trend in our civilization."),
  ("LOC_HD_RESOURCE_P0K_PAPYRUS_STATIONERY_INDUSTRY_DESCRIPTION",            "Craftsmen in {1_CityName} split, beat, and press papyrus stalks into smooth scrolls for scribes to copy onto."),
  ("LOC_HD_RESOURCE_P0K_PAPYRUS_STATIONERY_CORPORATION_DESCRIPTION",         "{1_CityName} papyrus paper has become the first choice for artists creating antique-style works and for issuing important certificates in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_P0K_MAPLE_INDUSTRY_TEXT",                          "In late winter and early spring, the maple forests of {1_CityName} begin to flow with sweet sap, a gift from the forest."),
  ("LOC_HD_BUILD_RESOURCE_P0K_MAPLE_CORPORATION_TEXT",                       "A maple syrup processing plant has been established in the forests of {1_CityName}, using pipeline networks to collect and concentrate the sap."),
  ("LOC_HD_RESOURCE_P0K_MAPLE_ORNAMENTAL_INDUSTRY_DESCRIPTION",              "In autumn, the maple leaves of {1_CityName} burst into a brilliant red glow, attracting countless people to admire the scenery."),
  ("LOC_HD_RESOURCE_P0K_MAPLE_ORNAMENTAL_CORPORATION_DESCRIPTION",           "The {1_CityName} maple park and autumn leaf festival have become one of our civilization`s most famous nature tourism identities."),
  ("LOC_HD_RESOURCE_P0K_MAPLE_SEASONING_INDUSTRY_DESCRIPTION",               "People in {1_CityName} drizzle maple syrup over pancakes and bacon, creating a wonderfully sweet and savory flavor."),
  ("LOC_HD_RESOURCE_P0K_MAPLE_SEASONING_CORPORATION_DESCRIPTION",            "Pure {1_CityName} maple syrup is the preferred natural sweetener for healthy eaters in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_P0K_OPAL_INDUSTRY_TEXT",                           "In the cracks of sedimentary rocks in {1_CityName}, opals with shimmering rainbow colors lie hidden, like solidified rainbows."),
  ("LOC_HD_BUILD_RESOURCE_P0K_OPAL_CORPORATION_TEXT",                        "Gemstones prone to cracking in the {1_CityName} region are carefully mined; sometimes ancient fossils are also discovered."),
  ("LOC_HD_RESOURCE_P0K_OPAL_ART_INDUSTRY_DESCRIPTION",                      "Painters in {1_CityName} grind opal fragments to create unique pigments that change with the light."),
  ("LOC_HD_RESOURCE_P0K_OPAL_ART_CORPORATION_DESCRIPTION",                   "Opal mosaics from {1_CityName}, with their dreamlike effect, adorn our civilization`s most luxurious hotels and cruise ships."),
  ("LOC_HD_RESOURCE_P0K_OPAL_DECORATION_INDUSTRY_DESCRIPTION",               "People in {1_CityName} believe opals combine the luck of all gems, using them to inlay amulets."),
  ("LOC_HD_RESOURCE_P0K_OPAL_DECORATION_CORPORATION_DESCRIPTION",            "Black opal rings from {1_CityName}, with their mysterious play of color, have become the darling of personalized jewelry in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_P0K_PLUMS_INDUSTRY_TEXT",                          "In the orchards of {1_CityName}, after the plum blossoms like snow, purple-red plums weigh down the branches."),
  ("LOC_HD_BUILD_RESOURCE_P0K_PLUMS_CORPORATION_TEXT",                       "Fruit processing plants turn the perishable plums of {1_CityName} into dried fruit and wine, reducing waste."),
  ("LOC_HD_RESOURCE_P0K_PLUMS_BREWING_INDUSTRY_DESCRIPTION",                 "People in {1_CityName} distill juicy plums into a clear spirit, called “Plum Brandy.”"),
  ("LOC_HD_RESOURCE_P0K_PLUMS_BREWING_CORPORATION_DESCRIPTION",              "{1_CityName} plum liqueur is used by mixologists in our civilization to create stunning specialty cocktails."),
  ("LOC_HD_RESOURCE_P0K_PLUMS_FRUIT_INDUSTRY_DESCRIPTION",                   "Biting into a ripe, soft plum from {1_CityName}, its sweet juice instantly fills your mouth."),
  ("LOC_HD_RESOURCE_P0K_PLUMS_FRUIT_CORPORATION_DESCRIPTION",                "{1_CityName} dried plums retain the essence of the fresh fruit, becoming a desk drawer snack for office workers in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_LEU_P0K_POTATOES_INDUSTRY_TEXT",                   "In the high-altitude cold zone of {1_CityName}, plump tubers grow silently under the soil, sustaining the people here."),
  ("LOC_HD_BUILD_RESOURCE_LEU_P0K_POTATOES_CORPORATION_TEXT",                "A food group has promoted mechanized potato cultivation in {1_CityName} and processes the harvested potatoes into various convenient foods."),
  ("LOC_HD_RESOURCE_LEU_P0K_POTATOES_BREWING_INDUSTRY_DESCRIPTION",          "People in {1_CityName} know how to use sprouted potatoes to brew spirits, driving away the harsh cold of the highlands."),
  ("LOC_HD_RESOURCE_LEU_P0K_POTATOES_BREWING_CORPORATION_DESCRIPTION",       "The “Fire Tuber” liquor from the {1_CityName} vodka distillery is famous in our civilization for its purity and heat."),
  ("LOC_HD_RESOURCE_LEU_P0K_POTATOES_CROPS_INDUSTRY_DESCRIPTION",            "The farm cellars of {1_CityName} are piled high with potatoes—their confidence for surviving the winter."),
  ("LOC_HD_RESOURCE_LEU_P0K_POTATOES_CROPS_CORPORATION_DESCRIPTION",         "Frozen french fries and mashed potato powder from factories in {1_CityName} have changed the fast-paced eating habits of our civilization."),

  ("LOC_HD_BUILD_RESOURCE_LEU_P0K_CAPYBARAS_INDUSTRY_TEXT",                  "In the swamps and along the rivers of {1_CityName} lives the world`s largest rodent—the gentle capybara."),
  ("LOC_HD_BUILD_RESOURCE_LEU_P0K_CAPYBARAS_CORPORATION_TEXT",               "A capybara farm has been established in {1_CityName} to exploit the value of their fur and docile nature."),
  ("LOC_HD_RESOURCE_LEU_P0K_CAPYBARAS_BEAST_INDUSTRY_DESCRIPTION",           "In the hot springs of {1_CityName}, the sight of capybaras soaking with half-closed eyes has become a symbol of healing."),
  ("LOC_HD_RESOURCE_LEU_P0K_CAPYBARAS_BEAST_CORPORATION_DESCRIPTION",        "{1_CityName} capybara cafes are all the rage in our civilization; interacting with these calm animals greatly relieves anxiety."),
  ("LOC_HD_RESOURCE_LEU_P0K_CAPYBARAS_LEATHER_INDUSTRY_DESCRIPTION",         "People in {1_CityName} use durable capybara leather to make saddles and high-end gloves, with excellent feel."),
  ("LOC_HD_RESOURCE_LEU_P0K_CAPYBARAS_LEATHER_CORPORATION_DESCRIPTION",      "The {1_CityName} capybara leather brand, with its fine texture, has become a new choice for luxury leather goods in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_LEU_P0K_COCA_INDUSTRY_TEXT",                       "Coca leaves have been chewed by locals in {1_CityName} for generations to overcome fatigue and hunger."),
  ("LOC_HD_BUILD_RESOURCE_LEU_P0K_COCA_CORPORATION_TEXT",                    "A pharmaceutical company, under police supervision, has established designated coca plantations in {1_CityName} to extract its special alkaloids."),
  ("LOC_HD_RESOURCE_LEU_P0K_COCA_CELEBRATION_INDUSTRY_DESCRIPTION",          "In religious ceremonies in {1_CityName}, coca leaves are offered as a sacrifice to holy fire, communicating with the gods."),
  ("LOC_HD_RESOURCE_LEU_P0K_COCA_CELEBRATION_CORPORATION_DESCRIPTION",       "In the cultural revival celebrations of indigenous people in {1_CityName}, coca leaves are given significant ethnic identity meaning."),
  ("LOC_HD_RESOURCE_LEU_P0K_COCA_MEDICINE_INDUSTRY_DESCRIPTION",             "Folk healers in {1_CityName} steep coca leaves in tea as a natural herbal painkiller for surgery and dentistry."),
  ("LOC_HD_RESOURCE_LEU_P0K_COCA_MEDICINE_CORPORATION_DESCRIPTION",          "{1_CityName} coca extract has been made into a local anesthetic, becoming an important drug in modern surgery in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_LEU_P0K_LLAMAS_INDUSTRY_TEXT",                     "On the high plateaus of {1_CityName}, herds of llamas carry loads, examining passersby with clear eyes."),
  ("LOC_HD_BUILD_RESOURCE_LEU_P0K_LLAMAS_CORPORATION_TEXT",                  "The llama`s cute image holds an important cultural place in our civilization; cultural groups in {1_CityName} have launched characters based on llamas."),
  ("LOC_HD_RESOURCE_LEU_P0K_LLAMAS_CLOTH_INDUSTRY_DESCRIPTION",              "Women in {1_CityName} spin highly insulating yarn from llama wool, weaving it into fluffy, thick cloaks."),
  ("LOC_HD_RESOURCE_LEU_P0K_LLAMAS_CLOTH_CORPORATION_DESCRIPTION",           "{1_CityName} alpaca wool coats, with their light warmth and smoothness, have become the fabric source for top-tier luxury coats in our civilization."),
  ("LOC_HD_RESOURCE_LEU_P0K_LLAMAS_TRANSIT_INDUSTRY_DESCRIPTION",            "Caravans in {1_CityName} skillfully handle llamas, navigating steep mountain paths as if on level ground."),
  ("LOC_HD_RESOURCE_LEU_P0K_LLAMAS_TRANSIT_CORPORATION_DESCRIPTION",         "{1_CityName} llamas, as eco-friendly pack animals, are widely used by mountain scientific expedition teams and nature reserves in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_LEU_P0K_QUINOA_INDUSTRY_TEXT",                     "Quinoa sways in the wind on the high plateaus of {1_CityName}; legend says it is the food of the gods."),
  ("LOC_HD_BUILD_RESOURCE_LEU_P0K_QUINOA_CORPORATION_TEXT",                  "A high-end food supermarket has signed contract farming agreements in {1_CityName}, packaging quinoa as a healthy grain for the world."),
  ("LOC_HD_RESOURCE_LEU_P0K_QUINOA_CROPS_INDUSTRY_DESCRIPTION",              "Farmers in {1_CityName} cook quinoa into porridge and bread; this complete protein grain sustains life on the plateau."),
  ("LOC_HD_RESOURCE_LEU_P0K_QUINOA_CROPS_CORPORATION_DESCRIPTION",           "{1_CityName} quinoa salads and grain bowls are viewed as energy staples by fitness enthusiasts and vegetarians in our civilization."),
  ("LOC_HD_RESOURCE_LEU_P0K_QUINOA_SEASONING_INDUSTRY_DESCRIPTION",          "Chefs in {1_CityName} grind quinoa into flour and mix it with spices to make a special seasoning sauce, perfect for meat."),
  ("LOC_HD_RESOURCE_LEU_P0K_QUINOA_SEASONING_CORPORATION_DESCRIPTION",       "{1_CityName} quinoa soy sauce and puffed quinoa grains, with their unique texture, enrich our civilization`s snack seasoning market."),

  ("LOC_HD_BUILD_RESOURCE_LEU_P0K_YERBAMATE_INDUSTRY_TEXT",                  "People in {1_CityName} pass down the legend of a goddess gifting yerba mate; this verdant leaf is a bond of friendship."),
  ("LOC_HD_BUILD_RESOURCE_LEU_P0K_YERBAMATE_CORPORATION_TEXT",               "An yerba mate company has packaged the shredded leaves into bags, bringing this traditional beverage out of {1_CityName}."),
  ("LOC_HD_RESOURCE_LEU_P0K_YERBAMATE_BEVERAGE_INDUSTRY_DESCRIPTION",        "In public places in {1_CityName}, people sit in a circle, sharing a single straw to drink yerba mate from a gourd."),
  ("LOC_HD_RESOURCE_LEU_P0K_YERBAMATE_BEVERAGE_CORPORATION_DESCRIPTION",     "{1_CityName} yerba mate energy drinks, with their natural caffeine and antioxidant properties, are sweeping gyms in our civilization."),
  ("LOC_HD_RESOURCE_LEU_P0K_YERBAMATE_CELEBRATION_INDUSTRY_DESCRIPTION",     "Sharing yerba mate is the most important hospitality ritual in {1_CityName}; when friends come from afar, a cup of hot tea is always offered first."),
  ("LOC_HD_RESOURCE_LEU_P0K_YERBAMATE_CELEBRATION_CORPORATION_DESCRIPTION",  "The gilt yerba mate tea set produced in {1_CityName} is presented as a state gift to honored guests of our civilization."),

  ("LOC_HD_BUILD_RESOURCE_SUK_SQUID_INDUSTRY_TEXT",                          "Fishermen in {1_CityName} use lights to lure squid that surface at night; the sea surface looks like a starry sky."),
  ("LOC_HD_BUILD_RESOURCE_SUK_SQUID_CORPORATION_TEXT",                       "A seafood company has equipped the fleets of {1_CityName} with deep-sea trawls, greatly increasing squid catches."),
  ("LOC_HD_RESOURCE_SUK_SQUID_CUISINE_INDUSTRY_DESCRIPTION",                 "Chefs in {1_CityName} can cut squid into delicate wheat-ear patterns; stir-fried, it becomes wonderfully crispy and tender."),
  ("LOC_HD_RESOURCE_SUK_SQUID_CUISINE_CORPORATION_DESCRIPTION",              "The {1_CityName} seafood theme restaurant`s signature is its secret-recipe calamari rings; reservations must be made a week in advance."),
  ("LOC_HD_RESOURCE_SUK_SQUID_SEAFOOD_INDUSTRY_DESCRIPTION",                 "At the stalls by the {1_CityName} docks, strings of drying squid are always on display, savory and delicious."),
  ("LOC_HD_RESOURCE_SUK_SQUID_SEAFOOD_CORPORATION_DESCRIPTION",              "Frozen squid from {1_CityName} is exported to all parts of our civilization, becoming a popular ingredient for street teppanyaki."),

  ("LOC_HD_BUILD_RESOURCE_SUK_SEALS_INDUSTRY_TEXT",                          "The icy shores of {1_CityName} are a paradise for seals; local indigenous people depend on them for food and fur."),
  ("LOC_HD_BUILD_RESOURCE_SUK_SEALS_CORPORATION_TEXT",                       "A marine biology institute in {1_CityName} protects seal populations and plans for the rational development of biological resources."),
  ("LOC_HD_RESOURCE_SUK_SEALS_MARINE_PRODUCTS_INDUSTRY_DESCRIPTION",         "Hunting parties in {1_CityName} paddle canoes to catch seals; no part is wasted—this is the law of polar survival."),
  ("LOC_HD_RESOURCE_SUK_SEALS_MARINE_PRODUCTS_CORPORATION_DESCRIPTION",      "High-quality seal oil produced in {1_CityName}, rich in Omega-3, is a hot commodity in our civilization`s health market."),
  ("LOC_HD_RESOURCE_SUK_SEALS_SEA_BEAST_INDUSTRY_DESCRIPTION",               "In the bays of {1_CityName}, trained seals balance balls and wave their flippers, bringing endless joy to tourists onshore."),
  ("LOC_HD_RESOURCE_SUK_SEALS_SEA_BEAST_CORPORATION_DESCRIPTION",            "The seal stars of the {1_CityName} marine reserve have entered thousands of homes in our civilization via television signals."),

  ("LOC_HD_BUILD_RESOURCE_SUK_CORAL_INDUSTRY_TEXT",                          "On the clear, shallow seabed of {1_CityName}, branching coral reefs form a bustling underwater city."),
  ("LOC_HD_BUILD_RESOURCE_SUK_CORAL_CORPORATION_TEXT",                       "our civilization`s institute of marine sciences is continuously documenting the survival status of coral reefs in {1_CityName}."),
  ("LOC_HD_RESOURCE_SUK_CORAL_CONSTRUCTION_INDUSTRY_DESCRIPTION",            "Ancestors in {1_CityName} used coral reef stone to burn white lime, building unique pure white castles."),
  ("LOC_HD_RESOURCE_SUK_CORAL_CONSTRUCTION_CORPORATION_DESCRIPTION",         "{1_CityName} coral limestone has excellent soundproofing and insulation properties, making it an ideal choice for eco-architects in our civilization."),
  ("LOC_HD_RESOURCE_SUK_CORAL_MARINE_PRODUCTS_INDUSTRY_DESCRIPTION",         "Ships in {1_CityName} haul snowy white coral reef stone ashore as a precious soil conditioner and craft material."),
  ("LOC_HD_RESOURCE_SUK_CORAL_MARINE_PRODUCTS_CORPORATION_DESCRIPTION",      "{1_CityName} protects living coral reefs, while fossilized ancient coral reefs serve as landscape cornerstones for aquariums in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_SUK_LOBSTER_INDUSTRY_TEXT",                        "Under the reefs off the coast of {1_CityName} hide majestic lobsters with large, powerful claws."),
  ("LOC_HD_BUILD_RESOURCE_SUK_LOBSTER_CORPORATION_TEXT",                     "Sailing boats for lobster fishing in {1_CityName} are a constant sight, providing jobs for tens of thousands of fishermen."),
  ("LOC_HD_RESOURCE_SUK_LOBSTER_CUISINE_INDUSTRY_DESCRIPTION",               "Famous chefs in {1_CityName} pan-fry lobster in butter and drizzle it with special sauce—a famous showstopper dish."),
  ("LOC_HD_RESOURCE_SUK_LOBSTER_CUISINE_CORPORATION_DESCRIPTION",            "The “Red Dragon” themed lobster burger from {1_CityName}, with its luxurious ingredients, has lines forming at influencer shops in our civilization."),
  ("LOC_HD_RESOURCE_SUK_LOBSTER_SEAFOOD_INDUSTRY_DESCRIPTION",               "Lobsters fresh out of the water in the early morning in {1_CityName} are thrown directly into a pot and steamed, the meat firm and springy."),
  ("LOC_HD_RESOURCE_SUK_LOBSTER_SEAFOOD_CORPORATION_DESCRIPTION",            "Frozen lobster tails from {1_CityName} bring affordable seafood feasts to inland supermarkets in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_SUK_RAYS_INDUSTRY_TEXT",                           "Stingrays glide like invisible carpets over the flat sandy seabed off the coast of {1_CityName}, only their protruding eyes visible."),
  ("LOC_HD_BUILD_RESOURCE_SUK_RAYS_CORPORATION_TEXT",                        "Dried stingray fins and skin from {1_CityName} have long been an inseparable part of our civilization`s famous and expensive dishes."),
  ("LOC_HD_RESOURCE_SUK_RAYS_CUISINE_INDUSTRY_DESCRIPTION",                  "On the street teppanyaki griddles of {1_CityName}, stingray meat sizzles in sauce, perfect with beer."),
  ("LOC_HD_RESOURCE_SUK_RAYS_CUISINE_CORPORATION_DESCRIPTION",               "{1_CityName} stingray meat patties, with their unique flavor, have become a novelty snack for air travelers in our civilization."),
  ("LOC_HD_RESOURCE_SUK_RAYS_SEAFOOD_INDUSTRY_DESCRIPTION",                  "Fishermen in {1_CityName} dry the skirts of stingrays; when rehydrated, they are very gelatinous and smooth in texture."),
  ("LOC_HD_RESOURCE_SUK_RAYS_SEAFOOD_CORPORATION_DESCRIPTION",               "Dried stingray fin from {1_CityName} is an important ingredient in dishes like “Buddha Jumps Over the Wall,” soft and fragrant."),

  ("LOC_HD_BUILD_RESOURCE_SUK_ABALONE_INDUSTRY_TEXT",                        "The reefs of {1_CityName}, constantly washed by rushing currents, are home to precious single-shell mollusks—abalone."),
  ("LOC_HD_BUILD_RESOURCE_SUK_ABALONE_CORPORATION_TEXT",                     "Aquatic scientists in our civilization have made bold strides, finally achieving artificial abalone cultivation in the waters of {1_CityName}."),
  ("LOC_HD_RESOURCE_SUK_ABALONE_MARINE_PRODUCTS_INDUSTRY_DESCRIPTION",       "Abalone divers in {1_CityName} work underwater, holding their breath against the cliffs; only the most experienced can harvest palm-sized abalone."),
  ("LOC_HD_RESOURCE_SUK_ABALONE_MARINE_PRODUCTS_CORPORATION_DESCRIPTION",    "Dried abalone from {1_CityName} is a hallmark of banquets for honored guests in our civilization; its gelatinous core texture is unforgettable."),
  ("LOC_HD_RESOURCE_SUK_ABALONE_MEDICINE_INDUSTRY_DESCRIPTION",              "Elderly people in {1_CityName} have long ground abalone shells into powder as a traditional Chinese medicine to clear the liver and improve vision, known as “Shi Jue Ming.”"),
  ("LOC_HD_RESOURCE_SUK_ABALONE_MEDICINE_CORPORATION_DESCRIPTION",           "Abalone extract from {1_CityName} has been shown to have excellent immune-boosting effects, attracting attention from the health product industry."),

  ("LOC_HD_BUILD_RESOURCE_SUK_CAVIAR_INDUSTRY_TEXT",                         "The river channels of {1_CityName} are spawning grounds for sturgeon; the black, shiny roe is a natural treasure."),
  ("LOC_HD_BUILD_RESOURCE_SUK_CAVIAR_CORPORATION_TEXT",                      "Farms in {1_CityName} use electrical stimulation to induce ovulation in sturgeon, enabling stable caviar production."),
  ("LOC_HD_RESOURCE_SUK_CAVIAR_SEAFOOD_INDUSTRY_DESCRIPTION",                "{1_CityName} caviar grains are plump; they burst gently on the tongue, releasing the savory taste of the sea."),
  ("LOC_HD_RESOURCE_SUK_CAVIAR_SEAFOOD_CORPORATION_DESCRIPTION",             "Canned {1_CityName} sturgeon caviar is exported, hailed as “black gold” at dining tables in our civilization."),
  ("LOC_HD_RESOURCE_SUK_CAVIAR_SEASONING_INDUSTRY_DESCRIPTION",              "Chefs in {1_CityName} boldly use caviar as a seasoning; even with baked potatoes, it transforms the ordinary into magic."),
  ("LOC_HD_RESOURCE_SUK_CAVIAR_SEASONING_CORPORATION_DESCRIPTION",           "{1_CityName} caviar seasoning sauces and powders allow ordinary families in our civilization to taste luxury."),

  ("LOC_HD_BUILD_RESOURCE_GRANITE_INDUSTRY_TEXT",                            "Beneath the earth of {1_CityName} stretches a bedrock of granite, miles deep and indestructible."),
  ("LOC_HD_BUILD_RESOURCE_GRANITE_CORPORATION_TEXT",                         "Heavy engineering machinery has moved into the quarries of {1_CityName}, cutting entire blocks of granite into perfect building materials."),
  ("LOC_HD_RESOURCE_GRANITE_ART_INDUSTRY_DESCRIPTION",                       "Sculptors, attracted by the fine grain of {1_CityName} granite, have established studios here for meticulous carving."),
  ("LOC_HD_RESOURCE_GRANITE_ART_CORPORATION_DESCRIPTION",                    "Granite sculptures shipped from {1_CityName} have become magnificent artworks adorning our civilization`s city squares."),
  ("LOC_HD_RESOURCE_GRANITE_CONSTRUCTION_INDUSTRY_DESCRIPTION",              "Stonemasons in {1_CityName} know the properties of granite inside out and can use it to build monuments that stand forever."),
  ("LOC_HD_RESOURCE_GRANITE_CONSTRUCTION_CORPORATION_DESCRIPTION",           "{1_CityName} granite lays the foundation for countless skyscrapers and sea-crossing bridges in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_LAPIS_INDUSTRY_TEXT",                              "Lapis lazuli mined from deep in the mountains of {1_CityName} is as deep blue as the night sky, flecked with golden pyrite spots."),
  ("LOC_HD_BUILD_RESOURCE_LAPIS_CORPORATION_TEXT",                           "The lapis lazuli mines of {1_CityName} supply this ancient sacred stone to the pigment and jewelry industries."),
  ("LOC_HD_RESOURCE_LAPIS_ART_INDUSTRY_DESCRIPTION",                         "Art studios in {1_CityName} grind lapis lazuli into extremely precious ultramarine pigment, used only to paint the robes of the Madonna."),
  ("LOC_HD_RESOURCE_LAPIS_ART_CORPORATION_DESCRIPTION",                      "The “Eternal Ultramarine” pigment produced in {1_CityName} is still the designated choice for artists restoring classical oil paintings in our civilization."),
  ("LOC_HD_RESOURCE_LAPIS_DECORATION_INDUSTRY_DESCRIPTION",                  "Nobles in {1_CityName} used lapis lazuli to make seals and necklaces, believing it could ward off evil."),
  ("LOC_HD_RESOURCE_LAPIS_DECORATION_CORPORATION_DESCRIPTION",               "Lapis lazuli earrings from {1_CityName} adorn elegant dinner parties in our civilization with their deep blue hue."),

  ("LOC_HD_BUILD_RESOURCE_LEAD_INDUSTRY_TEXT",                               "Shiny lead-zinc veins discovered in the mountains of {1_CityName} have attracted prospectors to settle."),
  ("LOC_HD_BUILD_RESOURCE_LEAD_CORPORATION_TEXT",                            "A concentration and smelting base has been established in {1_CityName} to separate lead and zinc, supplying industrial raw materials."),
  ("LOC_HD_RESOURCE_LEAD_MEDICINE_INDUSTRY_DESCRIPTION",                     "Pharmacists in {1_CityName} used lead oxide and calamine to concoct ancient ointments that astringe and reduce inflammation."),
  ("LOC_HD_RESOURCE_LEAD_MEDICINE_CORPORATION_DESCRIPTION",                  "A pharmaceutical company uses high-purity zinc oxide produced in {1_CityName} to manufacture nutritional oral liquids for every family in our civilization."),
  ("LOC_HD_RESOURCE_LEAD_METALLURGY_INDUSTRY_DESCRIPTION",                   "Furnaces in {1_CityName} transform lead-zinc ore into silvery zinc blocks and heavy lead ingots."),
  ("LOC_HD_RESOURCE_LEAD_METALLURGY_CORPORATION_DESCRIPTION",                "Galvanized steel sheets produced by the {1_CityName} zinc industry effectively fight steel corrosion in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_PLATINUM_INDUSTRY_TEXT",                           "Alluvial deposits in {1_CityName} contain a heavy, silvery-white metal once discarded as immature gold."),
  ("LOC_HD_BUILD_RESOURCE_PLATINUM_CORPORATION_TEXT",                        "After modern industry recognized the value of platinum group metals, a complex refining plant was built in {1_CityName}."),
  ("LOC_HD_RESOURCE_PLATINUM_CHEMISTRY_INDUSTRY_DESCRIPTION",                "Laboratories in {1_CityName} discovered that platinum is an excellent catalyst, accelerating fascinating chemical reactions."),
  ("LOC_HD_RESOURCE_PLATINUM_CHEMISTRY_CORPORATION_DESCRIPTION",             "Platinum gauze and catalytic converters from {1_CityName} quietly serve in our civilization`s chemical plants and automotive exhaust systems."),
  ("LOC_HD_RESOURCE_PLATINUM_DECORATION_INDUSTRY_DESCRIPTION",               "Craftsmen in {1_CityName} use platinum to create mounts; because it does not tarnish and is strong, it securely holds diamonds."),
  ("LOC_HD_RESOURCE_PLATINUM_DECORATION_CORPORATION_DESCRIPTION",            "Platinum wedding rings and necklaces from {1_CityName}, with their pure white luster, have become symbols of eternal love in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_QUARTZ_INDUSTRY_TEXT",                             "The land of {1_CityName} is covered with crystal-clear quartz clusters, some as large as a person."),
  ("LOC_HD_BUILD_RESOURCE_QUARTZ_CORPORATION_TEXT",                          "Tons of quartz ore ensure the smooth operation of {1_CityName}`s construction and high-tech industries."),
  ("LOC_HD_RESOURCE_QUARTZ_CHEMISTRY_INDUSTRY_DESCRIPTION",                  "Piezoelectric quartz slices from {1_CityName} are used as precision oscillators, stabilizing radio waves."),
  ("LOC_HD_RESOURCE_QUARTZ_CHEMISTRY_CORPORATION_DESCRIPTION",               "High-purity quartz crucibles from {1_CityName} have produced the vast majority of our civilization`s monocrystalline silicon, powering the digital age."),
  ("LOC_HD_RESOURCE_QUARTZ_CONSTRUCTION_INDUSTRY_DESCRIPTION",               "People in {1_CityName} melt quartz sand to make sturdy glass, inlaying it into magnificent windows and greenhouses."),
  ("LOC_HD_RESOURCE_QUARTZ_CONSTRUCTION_CORPORATION_DESCRIPTION",            "High-quality quartz sand from {1_CityName} is the birthplace of glass curtain walls for skyscrapers in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_RUBY_INDUSTRY_TEXT",                               "Red corundum in the streams of {1_CityName} is as striking as blood; the king claimed it for himself."),
  ("LOC_HD_BUILD_RESOURCE_RUBY_CORPORATION_TEXT",                            "A gem mining company uses modern geological methods to find ruby deposits in {1_CityName}."),
  ("LOC_HD_RESOURCE_RUBY_DECORATION_INDUSTRY_DESCRIPTION",                   "Ruby jewelry from {1_CityName} is standard for royal weddings; its intense red is believed to represent love and power."),
  ("LOC_HD_RESOURCE_RUBY_DECORATION_CORPORATION_DESCRIPTION",                "{1_CityName} pigeon blood red rubies frequently break per-carat price records at auctions in our civilization."),
  ("LOC_HD_RESOURCE_RUBY_METALLURGY_INDUSTRY_DESCRIPTION",                   "Rubies produced in {1_CityName}, being extremely hard, are used as wear-resistant bearings in precision timepieces."),
  ("LOC_HD_RESOURCE_RUBY_METALLURGY_CORPORATION_DESCRIPTION",                "Synthetic ruby crystals from {1_CityName} provide core components for our civilization`s lasers and precision machinery."),

  ("LOC_HD_BUILD_RESOURCE_SANDALWOOD_INDUSTRY_TEXT",                         "Around the ancient temples of {1_CityName}, precious sandalwood trees are planted, taking decades to develop their distant fragrance."),
  ("LOC_HD_BUILD_RESOURCE_SANDALWOOD_CORPORATION_TEXT",                      "Sandalwood plantations and essential oil distilleries have become pillars of {1_CityName}`s industry."),
  ("LOC_HD_RESOURCE_SANDALWOOD_CELEBRATION_INDUSTRY_DESCRIPTION",            "At grand ceremonies in {1_CityName}, burning sandalwood chips fills the air with sacredness and solemnity."),
  ("LOC_HD_RESOURCE_SANDALWOOD_CELEBRATION_CORPORATION_DESCRIPTION",         "{1_CityName} specially-made sandalwood incense sticks and cones are the designated incense for meditation, Zen practice, and major ceremonies in our civilization."),
  ("LOC_HD_RESOURCE_SANDALWOOD_HOUSEHOLD_INDUSTRY_DESCRIPTION",              "Carpenters in {1_CityName} use sandalwood to make dressing cases and folding fans; with every opening and closing, a fragrant breeze flows."),
  ("LOC_HD_RESOURCE_SANDALWOOD_HOUSEHOLD_CORPORATION_DESCRIPTION",           "{1_CityName} sandalwood furniture and ornaments, with their mind-calming properties, adorn elegant studies in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_OAK_INDUSTRY_TEXT",                                "The ancient oak forests of {1_CityName} were once considered dwellings of spirits; now, lumberjacks harvest them with reverence."),
  ("LOC_HD_BUILD_RESOURCE_OAK_CORPORATION_TEXT",                             "A large forestry company has taken over the woodlands, ensuring that {1_CityName} oak is both utilized and sustained."),
  ("LOC_HD_RESOURCE_OAK_FUEL_INDUSTRY_DESCRIPTION",                          "Charcoal burners in {1_CityName} pile up oak in kilns, slowly smoldering to produce high-quality, long-burning charcoal."),
  ("LOC_HD_RESOURCE_OAK_FUEL_CORPORATION_DESCRIPTION",                       "“{1_CityName}” brand charcoal brings a rich, forest-like aroma to our civilization`s barbecue gatherings."),
  ("LOC_HD_RESOURCE_OAK_HOUSEHOLD_INDUSTRY_DESCRIPTION",                     "Carpenters in {1_CityName} use oak to create heavy, durable furniture that can last for generations."),
  ("LOC_HD_RESOURCE_OAK_HOUSEHOLD_CORPORATION_DESCRIPTION",                  "{1_CityName} oak flooring, with its rustic grain, covers countless refined homes in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_MAPLE_INDUSTRY_TEXT",                              "At the entrance of the ancient village outside {1_CityName}, a towering beech tree stands, considered an auspicious symbol of academic success and talent."),
  ("LOC_HD_BUILD_RESOURCE_MAPLE_CORPORATION_TEXT",                           "A nursery company promotes beech tree cultivation in {1_CityName}, balancing greening and timber reserves."),
  ("LOC_HD_RESOURCE_MAPLE_CONSTRUCTION_INDUSTRY_DESCRIPTION",                "Shipyards in {1_CityName} discovered that beech wood is water-resistant and tough, making excellent material for keels and oars."),
  ("LOC_HD_RESOURCE_MAPLE_CONSTRUCTION_CORPORATION_DESCRIPTION",             "{1_CityName} beech wood staircases and flooring, with their beautiful grain and hardness, pave countless warm home renovations in our civilization."),
  ("LOC_HD_RESOURCE_MAPLE_ORNAMENTAL_INDUSTRY_DESCRIPTION",                  "Beech trees are planted as street trees in {1_CityName}, turning golden and russet in autumn, breathtakingly beautiful."),
  ("LOC_HD_RESOURCE_MAPLE_ORNAMENTAL_CORPORATION_DESCRIPTION",               "{1_CityName} beech bonsai and landscape trees provide excellent colorful species for urban gardens in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_LIMESTONE_INDUSTRY_TEXT",                          "The white dolomite layers in the outskirts of {1_CityName}, when cut open, reveal a jade-like texture."),
  ("LOC_HD_BUILD_RESOURCE_LIMESTONE_CORPORATION_TEXT",                       "A mining group operates large dolomite quarries in {1_CityName}, providing ample raw materials for the building materials and industries."),
  ("LOC_HD_RESOURCE_LIMESTONE_CONSTRUCTION_INDUSTRY_DESCRIPTION",            "Kilns in {1_CityName} fire dolomite into durable bricks and tiles for building homes."),
  ("LOC_HD_RESOURCE_LIMESTONE_CONSTRUCTION_CORPORATION_DESCRIPTION",         "High-grade fire bricks produced in {1_CityName} protect our civilization`s steelmaking blast furnaces and generator sets."),
  ("LOC_HD_RESOURCE_LIMESTONE_METALLURGY_INDUSTRY_DESCRIPTION",              "Steelworkers in {1_CityName} add dolomite to the furnace; it helps remove impurities from molten iron."),
  ("LOC_HD_RESOURCE_LIMESTONE_METALLURGY_CORPORATION_DESCRIPTION",           "{1_CityName} dolomite dramatically increases efficiency in our civilization`s steel mills, becoming a reliable source of steelmaking flux."),

  ("LOC_HD_BUILD_RESOURCE_ALOE_INDUSTRY_TEXT",                               "On the arid lands of {1_CityName}, fleshy aloe vera grows tenaciously, like a desert oasis."),
  ("LOC_HD_BUILD_RESOURCE_ALOE_CORPORATION_TEXT",                            "A biotech company has established aloe vera plantations and gel extraction bases in {1_CityName}."),
  ("LOC_HD_RESOURCE_ALOE_CUISINE_INDUSTRY_DESCRIPTION",                      "People in {1_CityName} dice the translucent gel of aloe vera and cook it with honey, creating a cooling, refreshing summer dessert."),
  ("LOC_HD_RESOURCE_ALOE_CUISINE_CORPORATION_DESCRIPTION",                   "{1_CityName} aloe vera pulp yogurt is one of the healthiest and most popular snacks among young people in our civilization."),
  ("LOC_HD_RESOURCE_ALOE_MEDICINE_INDUSTRY_DESCRIPTION",                     "When burned or sunburned, every family in {1_CityName} will break off a piece of aloe to apply to the skin, providing instant relief."),
  ("LOC_HD_RESOURCE_ALOE_MEDICINE_CORPORATION_DESCRIPTION",                  "{1_CityName} aloe vera gel masks and burn creams are a must-have in thousands of medicine cabinets in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_BERRIES_INDUSTRY_TEXT",                            "Between summer and autumn, the hillsides of {1_CityName} are dotted with purple, red, and black berries, with birds and people competing for them."),
  ("LOC_HD_BUILD_RESOURCE_BERRIES_CORPORATION_TEXT",                         "A beverage company has set up berry collection points in {1_CityName}, encouraging farmers to scale up cultivation."),
  ("LOC_HD_RESOURCE_BERRIES_BREWING_INDUSTRY_DESCRIPTION",                   "People in {1_CityName} ferment leftover berries into intoxicating fruit wine, staining their cups red."),
  ("LOC_HD_RESOURCE_BERRIES_BREWING_CORPORATION_DESCRIPTION",                "{1_CityName} blackberry wine, sweet and slightly tipsy, is a darling of romantic dinners in our civilization."),
  ("LOC_HD_RESOURCE_BERRIES_FRUIT_INDUSTRY_DESCRIPTION",                     "Berries picked early in the morning are placed in bamboo baskets and delivered to {1_CityName}`s markets the same day, still with dew."),
  ("LOC_HD_RESOURCE_BERRIES_FRUIT_CORPORATION_DESCRIPTION",                  "{1_CityName} berry cooperative`s jams and frozen berries bring sweetness to breakfasts year-round in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_POPPIES_INDUSTRY_TEXT",                            "On the fields of {1_CityName}, whenever the spring breeze blows, crimson poppies sway like raging fire."),
  ("LOC_HD_BUILD_RESOURCE_POPPIES_CORPORATION_TEXT",                         "A horticulture company has cultivated double-petal, multi-colored poppy varieties, making {1_CityName} a famous flower town."),
  ("LOC_HD_RESOURCE_POPPIES_ART_INDUSTRY_DESCRIPTION",                       "Painters set up easels by the poppy fields in {1_CityName}, trying to capture the flowing red."),
  ("LOC_HD_RESOURCE_POPPIES_ART_CORPORATION_DESCRIPTION",                    "Paintings and printed fabrics themed around {1_CityName} poppies bring an impressionistic splash of color to our civilization."),
  ("LOC_HD_RESOURCE_POPPIES_ORNAMENTAL_INDUSTRY_DESCRIPTION",                "Children in {1_CityName} run through the sea of poppies; this dreamlike landscape intoxicates the heart."),
  ("LOC_HD_RESOURCE_POPPIES_ORNAMENTAL_CORPORATION_DESCRIPTION",             "{1_CityName} poppy cut flowers symbolize deep affection and remembrance at weddings and memorial ceremonies in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_CAVIAR_INDUSTRY_TEXT",                             "In the cold mountain spring streams of {1_CityName}, rainbow trout, like underwater rainbows, nimbly evade anglers."),
  ("LOC_HD_BUILD_RESOURCE_CAVIAR_CORPORATION_TEXT",                          "A cold-water fish farm uses the high-quality water source of {1_CityName} to promote net pen and flow-through farming of rainbow trout."),
  ("LOC_HD_RESOURCE_CAVIAR_CUISINE_INDUSTRY_DESCRIPTION",                    "Smoking masters in {1_CityName} smoke rainbow trout over fruitwood until it turns golden red, oily and savory."),
  ("LOC_HD_RESOURCE_CAVIAR_CUISINE_CORPORATION_DESCRIPTION",                 "Ready-to-eat {1_CityName} smoked trout strips are a popular protein-packed snack for outdoor enthusiasts in our civilization."),
  ("LOC_HD_RESOURCE_CAVIAR_SEAFOOD_INDUSTRY_DESCRIPTION",                    "Freshly caught {1_CityName} rainbow trout, grilled directly over fire and sprinkled with coarse salt, is a heavenly delight."),
  ("LOC_HD_RESOURCE_CAVIAR_SEAFOOD_CORPORATION_DESCRIPTION",                 "{1_CityName} rainbow trout sashimi is increasingly popular at inland Japanese restaurants in our civilization as an affordable alternative to salmon."),

  ("LOC_HD_BUILD_RESOURCE_SALMON_INDUSTRY_TEXT",                             "In the swift, cold streams of {1_CityName}, schools of salmon swim upstream to complete their life cycle."),
  ("LOC_HD_BUILD_RESOURCE_SALMON_CORPORATION_TEXT",                          "Salmon farming cages have been laid out in the fjords of {1_CityName}, meticulously managing this delicious fish."),
  ("LOC_HD_RESOURCE_SALMON_CUISINE_INDUSTRY_DESCRIPTION",                    "Smoked salmon workshops in {1_CityName} slowly smoke the fish over pinewood, giving it an oaky flavor."),
  ("LOC_HD_RESOURCE_SALMON_CUISINE_CORPORATION_DESCRIPTION",                 "{1_CityName} smoked salmon sandwiches are all the rage in our civilization`s healthy eating circles and brunch tables."),
  ("LOC_HD_RESOURCE_SALMON_SEAFOOD_INDUSTRY_DESCRIPTION",                    "Sliced {1_CityName} salmon sashimi has perfect marble-like fat marbling, melting in the mouth."),
  ("LOC_HD_RESOURCE_SALMON_SEAFOOD_CORPORATION_DESCRIPTION",                 "Daily air-shipped chilled {1_CityName} salmon is the highest-rated sashimi at Japanese restaurants in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_ALGAE_INDUSTRY_TEXT",                              "The cold waters of {1_CityName} are home to lush giant kelp forests, swaying with the waves like an underwater dragon palace."),
  ("LOC_HD_BUILD_RESOURCE_ALGAE_CORPORATION_TEXT",                           "A shallow area of the sea in {1_CityName} is covered with ropes, making it our civilization`s center for kelp farming."),
  ("LOC_HD_RESOURCE_ALGAE_MARINE_PRODUCTS_INDUSTRY_DESCRIPTION",             "Fishermen in {1_CityName} harvest kelp at low tide, spread it out on the beach to dry, and tie it into bundles for soup."),
  ("LOC_HD_RESOURCE_ALGAE_MARINE_PRODUCTS_CORPORATION_DESCRIPTION",          "{1_CityName} kelp knots and instant kelp shreds are the cheapest sea vegetables in our civilization`s canteens and restaurants."),
  ("LOC_HD_RESOURCE_ALGAE_SEASONING_INDUSTRY_DESCRIPTION",                   "Housewives in {1_CityName} know that the white powder on kelp is natural MSG; just throw a piece into the pot to make the soup delicious."),
  ("LOC_HD_RESOURCE_ALGAE_SEASONING_CORPORATION_DESCRIPTION",                "Monosodium glutamate extracted from {1_CityName} kelp ushered in the era of the MSG industry in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_CORAL_INDUSTRY_TEXT",                              "On the dark seabed cliffs of {1_CityName} grow ruby-like coral trees, precious and fragile."),
  ("LOC_HD_BUILD_RESOURCE_CORAL_CORPORATION_TEXT",                           "Commercial coral farming has been a great success on the beaches of {1_CityName}, protecting the environment while also promoting marine development."),
  ("LOC_HD_RESOURCE_CORAL_DECORATION_INDUSTRY_DESCRIPTION",                  "Artisans in {1_CityName} string red coral beads with turquoise and gold to create magnificent necklaces."),
  ("LOC_HD_RESOURCE_CORAL_DECORATION_CORPORATION_DESCRIPTION",               "{1_CityName} sardinian red coral jewelry is the most traditional blessing received by newborns and brides in our civilization."),
  ("LOC_HD_RESOURCE_CORAL_MARINE_PRODUCTS_INDUSTRY_DESCRIPTION",             "Deep-sea red coral from {1_CityName}, after polishing, exhibits a warm, glassy texture and is considered a sea treasure."),
  ("LOC_HD_RESOURCE_CORAL_MARINE_PRODUCTS_CORPORATION_DESCRIPTION",          "Branched red coral ornaments from {1_CityName}, due to their rarity, symbolize status and protection against evil in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_SEASHELLS_INDUSTRY_TEXT",                          "On the shallows of {1_CityName}, there are countless small shells with delicate patterns; people use them for barter."),
  ("LOC_HD_BUILD_RESOURCE_SEASHELLS_CORPORATION_TEXT",                       "An arts and crafts company has partnered with a bank in {1_CityName} to manage the production of special commemorative coins made from cowrie shells."),
  ("LOC_HD_RESOURCE_SEASHELLS_MARINE_PRODUCTS_INDUSTRY_DESCRIPTION",         "Women in {1_CityName} string cowrie shells into long strands, exchanging them for grain, salt, and cloth."),
  ("LOC_HD_RESOURCE_SEASHELLS_MARINE_PRODUCTS_CORPORATION_DESCRIPTION",      "{1_CityName} cowrie shells, as a cultural symbol, appear on our civilization`s cultural creative ornaments and wind chimes."),
  ("LOC_HD_RESOURCE_SEASHELLS_MINTING_INDUSTRY_DESCRIPTION",                 "In the warehouses of {1_CityName}, piles of cowrie shells represent the tribe`s wealth and cannot be casually consumed."),
  ("LOC_HD_RESOURCE_SEASHELLS_MINTING_CORPORATION_DESCRIPTION",              "Cowrie shells were an inspiration for the early forms of metal currency in our civilization, whose influence can still be seen today."),

  ("LOC_HD_BUILD_RESOURCE_BAMBOO_INDUSTRY_TEXT",                             "On the sunny slopes of {1_CityName}, bamboo forms a sea of green, rustling in the wind, an inexhaustible resource."),
  ("LOC_HD_BUILD_RESOURCE_BAMBOO_CORPORATION_TEXT",                          "A deep-processing base for bamboo has been established in {1_CityName}, making bamboo a green alternative to steel and plastic."),
  ("LOC_HD_RESOURCE_BAMBOO_HOUSEHOLD_INDUSTRY_DESCRIPTION",                  "People in {1_CityName} use bamboo to build houses and make furniture and bamboo mats; the entire city is filled with a fresh bamboo scent."),
  ("LOC_HD_RESOURCE_BAMBOO_HOUSEHOLD_CORPORATION_DESCRIPTION",               "{1_CityName} bamboo integrated flooring and furniture, known for their eco-friendliness and durability, are widely popular in our civilization."),
  ("LOC_HD_RESOURCE_BAMBOO_STATIONERY_INDUSTRY_DESCRIPTION",                 "Scholars in {1_CityName} use bamboo tubes to make writing brushes, and write poetry and paint on bamboo pulp paper—perfect complements."),
  ("LOC_HD_RESOURCE_BAMBOO_STATIONERY_CORPORATION_DESCRIPTION",              "{1_CityName} bamboo fiber notebooks and bamboo U-disk cultural products are favored corporate souvenirs in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_EBONY_INDUSTRY_TEXT",                              "Near the riverbeds of {1_CityName}, sunken ebony, carbonized over thousands of years, lies hard and black, impervious to water."),
  ("LOC_HD_BUILD_RESOURCE_EBONY_CORPORATION_TEXT",                           "A rare wood company salvages ebony at great cost in {1_CityName} for intricate luxury carvings."),
  ("LOC_HD_RESOURCE_EBONY_CELEBRATION_INDUSTRY_DESCRIPTION",                 "The ceremonial scepters of the {1_CityName} royal palace are made from whole ebony logs, symbolizing eternal rule and noble status."),
  ("LOC_HD_RESOURCE_EBONY_CELEBRATION_CORPORATION_DESCRIPTION",              "{1_CityName} ebony desk weights and prayer beads, with their hard yet warm texture, are coveted by collectors in our civilization."),
  ("LOC_HD_RESOURCE_EBONY_CONSTRUCTION_INDUSTRY_DESCRIPTION",                "The pillars of the {1_CityName} temple are supported by precious ebony, standing for centuries without falling, jet black and shiny."),
  ("LOC_HD_RESOURCE_EBONY_CONSTRUCTION_CORPORATION_DESCRIPTION",             "{1_CityName} ebony veneer panels are used in the instrument panels of ultra-luxury cars and the walls of top-tier clubs in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_SAKURA_INDUSTRY_TEXT",                             "The orchards of {1_CityName} not only bring sweet cherries but also, after the fruit is picked, smooth cherry wood."),
  ("LOC_HD_BUILD_RESOURCE_SAKURA_CORPORATION_TEXT",                          "A wood processing plant saws and kiln-dries cherry wood, supplying {1_CityName}`s high-end home furnishing market."),
  ("LOC_HD_RESOURCE_SAKURA_CELEBRATION_INDUSTRY_DESCRIPTION",                "Carpenters in {1_CityName} use cherry wood to make delicate musical instruments, playing cheerful melodies at harvest celebrations."),
  ("LOC_HD_RESOURCE_SAKURA_CELEBRATION_CORPORATION_DESCRIPTION",             "{1_CityName} cherry wood violins and guitars, with their warm tone and beautiful grain, are favored by musicians in our civilization."),
  ("LOC_HD_RESOURCE_SAKURA_ORNAMENTAL_INDUSTRY_DESCRIPTION",                 "In spring, the cherry blossoms of {1_CityName} cover the mountains like pink clouds, attracting countless people to enjoy the scenery."),
  ("LOC_HD_RESOURCE_SAKURA_ORNAMENTAL_CORPORATION_DESCRIPTION",              "The {1_CityName} cherry festival and related cultural products are a popular IP for spring tourism in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_CASHMERE_INDUSTRY_TEXT",                           "On steep cliffs in the harsh winter, goats grow a fine, soft undercoat, carefully combed out in spring by combers in {1_CityName}."),
  ("LOC_HD_BUILD_RESOURCE_CASHMERE_CORPORATION_TEXT",                        "A cashmere brand has established a textile mill in {1_CityName}, turning this diamond fiber into luxurious yarn."),
  ("LOC_HD_RESOURCE_CASHMERE_CLOTH_INDUSTRY_DESCRIPTION",                    "Cashmere scarves woven in {1_CityName} are light as a feather yet can withstand biting cold winds."),
  ("LOC_HD_RESOURCE_CASHMERE_CLOTH_CORPORATION_DESCRIPTION",                 "{1_CityName} “Cloud” cashmere sweaters, with their minimalist design, warm the autumn and winter of our civilization`s elite class."),
  ("LOC_HD_RESOURCE_CASHMERE_DECORATION_INDUSTRY_DESCRIPTION",               "Artisans in {1_CityName} roll cashmere into soft felt hats and brooches, delicate and warm."),
  ("LOC_HD_RESOURCE_CASHMERE_DECORATION_CORPORATION_DESCRIPTION",            "{1_CityName} cashmere felt art and accessories stand out in our civilization`s fashionable boutiques."),

  ("LOC_HD_BUILD_RESOURCE_PINE_INDUSTRY_TEXT",                               "The hills of {1_CityName} are covered with towering pine forests, with the sound of pine waves in the wind."),
  ("LOC_HD_BUILD_RESOURCE_PINE_CORPORATION_TEXT",                            "A timber company has established a modern logging camp and wood processing complex in {1_CityName}."),
  ("LOC_HD_RESOURCE_PINE_FUEL_INDUSTRY_DESCRIPTION",                         "People in {1_CityName} collect pine resin and branches to make torches and kindling."),
  ("LOC_HD_RESOURCE_PINE_FUEL_CORPORATION_DESCRIPTION",                      "Pine oil and pine pellet fuel from {1_CityName} are excellent choices for camping enthusiasts and fireplace users in our civilization."),
  ("LOC_HD_RESOURCE_PINE_STATIONERY_INDUSTRY_DESCRIPTION",                   "Pine wood from {1_CityName} is pulped to make slightly yellowed paper that writes very smoothly."),
  ("LOC_HD_RESOURCE_PINE_STATIONERY_CORPORATION_DESCRIPTION",                "Pine paper notebooks produced by the {1_CityName} paper mill are beloved by writers and students in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_TIN_INDUSTRY_TEXT",                                "The river sediments of {1_CityName} glint with dark tin sand; tin panners toil all day."),
  ("LOC_HD_BUILD_RESOURCE_TIN_CORPORATION_TEXT",                             "After locating deep veins, a tin mining company in {1_CityName} introduced bucket dredges for large-scale extraction."),
  ("LOC_HD_RESOURCE_TIN_CHEMISTRY_INDUSTRY_DESCRIPTION",                     "In laboratories in {1_CityName}, tin is used to synthesize mordants, making fabric colors more vibrant."),
  ("LOC_HD_RESOURCE_TIN_CHEMISTRY_CORPORATION_DESCRIPTION",                  "The {1_CityName} organotin chemical base provides key additives for our civilization`s plastics and coatings industries."),
  ("LOC_HD_RESOURCE_TIN_METALLURGY_INDUSTRY_DESCRIPTION",                    "Craftsmen in {1_CityName} cast tin into beautiful wine pots and candle holders, with a silvery sheen."),
  ("LOC_HD_RESOURCE_TIN_METALLURGY_CORPORATION_DESCRIPTION",                 "{1_CityName} tinware, known for its non-toxic and rust-proof properties, has become synonymous with high-end kitchenware in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_RUBBER_INDUSTRY_TEXT",                             "Workers in the rainforests of {1_CityName} greet the first light of dawn, making slanted cuts into the rubber trees."),
  ("LOC_HD_BUILD_RESOURCE_RUBBER_CORPORATION_TEXT",                          "Large rubber plantations have expanded in {1_CityName} to provide raw materials for the rapidly growing transportation and industrial sectors."),
  ("LOC_HD_RESOURCE_RUBBER_CHEMISTRY_INDUSTRY_DESCRIPTION",                  "Chemists in {1_CityName} vulcanize rubber, making it strong and elastic for miraculous inventions."),
  ("LOC_HD_RESOURCE_RUBBER_CHEMISTRY_CORPORATION_DESCRIPTION",               "The synthetic rubber industry in {1_CityName} provides indispensable materials for our civilization`s tires and seals."),
  ("LOC_HD_RESOURCE_RUBBER_HOUSEHOLD_INDUSTRY_DESCRIPTION",                  "Rubber produced in {1_CityName} is turned into flexible rain boots and mattresses, enhancing daily life."),
  ("LOC_HD_RESOURCE_RUBBER_HOUSEHOLD_CORPORATION_DESCRIPTION",               "{1_CityName} latex household products, known for their comfort and anti-dust mite properties, are the first choice for the new middle class in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_OXEN_INDUSTRY_TEXT",                               "In the rice paddies on the outskirts of {1_CityName}, oxen work unhurriedly, following the farmers` routine of rising and retiring with the sun."),
  ("LOC_HD_BUILD_RESOURCE_OXEN_CORPORATION_TEXT",                            "Traditional farming methods are being replaced by tractors and chemical fertilizers; ranchers in {1_CityName} are seeking new outlets for their oxen."),
  ("LOC_HD_RESOURCE_OXEN_AGRICULTURE_INDUSTRY_DESCRIPTION",                  "The {1_CityName} city government encourages agricultural production by uniformly providing oxen to farmers."),
  ("LOC_HD_RESOURCE_OXEN_AGRICULTURE_CORPORATION_DESCRIPTION",              "Oxen will forever hold a unique place in the idyllic rural memories of {1_CityName}."),
  ("LOC_HD_RESOURCE_OXEN_TRANSIT_INDUSTRY_DESCRIPTION",                      "A bustling transport network has been established between urban and rural areas of {1_CityName} using oxcarts."),
  ("LOC_HD_RESOURCE_OXEN_TRANSIT_CORPORATION_DESCRIPTION",                   "The oxcart is an important carrier of the long-standing farming culture of {1_CityName}."),

  ("LOC_HD_BUILD_RESOURCE_HAM_INDUSTRY_TEXT",                                "The mountain winds of {1_CityName} blow over pig legs hanging from eaves, slowly fermenting into ruby-like raw ham."),
  ("LOC_HD_BUILD_RESOURCE_HAM_CORPORATION_TEXT",                             "A meat processing group has built a temperature- and humidity-controlled ham aging cellar in {1_CityName} to mass-produce this delicacy."),
  ("LOC_HD_RESOURCE_HAM_CUISINE_INDUSTRY_DESCRIPTION",                       "Thin as paper slices of {1_CityName} ham melt in the mouth, carrying a lingering aftertaste of acorns and time."),
  ("LOC_HD_RESOURCE_HAM_CUISINE_CORPORATION_DESCRIPTION",                    "{1_CityName} Iberian-style ham is a perennial champion on our civilization`s list of high-end party foods and gifts."),
  ("LOC_HD_RESOURCE_HAM_OIL_INDUSTRY_DESCRIPTION",                           "People in {1_CityName} are adept at rendering the leftover fat from ham into aromatic ham oil for sautéing vegetables."),
  ("LOC_HD_RESOURCE_HAM_OIL_CORPORATION_DESCRIPTION",                        "{1_CityName} ham oil chili sauce, maximizing the richness of animal fat, is a magical noodle mixer in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_TRAVERTINE_INDUSTRY_TEXT",                         "Hot springs in {1_CityName} flow over cliffs, depositing porous yet tough travertine, like a staircase of time."),
  ("LOC_HD_BUILD_RESOURCE_TRAVERTINE_CORPORATION_TEXT",                      "A building materials company sustainably quarries travertine from {1_CityName}, turning it into a luxury material."),
  ("LOC_HD_RESOURCE_TRAVERTINE_CONSTRUCTION_INDUSTRY_DESCRIPTION",           "The ancient arenas and bathhouses of {1_CityName} made extensive use of local travertine, achieving immortal architectural wonders."),
  ("LOC_HD_RESOURCE_TRAVERTINE_CONSTRUCTION_CORPORATION_DESCRIPTION",        "{1_CityName} travertine panels are the top choice for designers creating naturalist hot spring hotels in our civilization."),
  ("LOC_HD_RESOURCE_TRAVERTINE_MEDICINE_INDUSTRY_DESCRIPTION",               "Hot spring travertine from {1_CityName} is believed to be rich in minerals, ground into powder to regulate the stomach."),
  ("LOC_HD_RESOURCE_TRAVERTINE_MEDICINE_CORPORATION_DESCRIPTION",            "Natural calcium supplements from {1_CityName}, sourced from pure travertine, protect the bone health of our people."),

  ("LOC_HD_BUILD_RESOURCE_ALABASTER_INDUSTRY_TEXT",                          "The mines of {1_CityName} yield slightly translucent alabaster, like translucent honey."),
  ("LOC_HD_BUILD_RESOURCE_ALABASTER_CORPORATION_TEXT",                       "A craft stone factory cuts alabaster from {1_CityName} into thin sheets for building decoration."),
  ("LOC_HD_RESOURCE_ALABASTER_ART_INDUSTRY_DESCRIPTION",                     "The windows of the {1_CityName} cathedral are not glazed with glass but with alabaster panels, emitting a warm, holy light."),
  ("LOC_HD_RESOURCE_ALABASTER_ART_CORPORATION_DESCRIPTION",                  "{1_CityName} alabaster lamps warm the living rooms of thousands of families in our civilization."),
  ("LOC_HD_RESOURCE_ALABASTER_MEDICINE_INDUSTRY_DESCRIPTION",                "Old Chinese medicine practitioners in {1_CityName} use calcined alabaster powder in combination with other herbs to reduce fever and calm convulsions."),
  ("LOC_HD_RESOURCE_ALABASTER_MEDICINE_CORPORATION_DESCRIPTION",             "Refined plaster powder produced in {1_CityName} is the designated material for fracture fixation and dental impressions in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_GOLD2_INDUSTRY_TEXT",                              "Sulfur condenses on the rims of volcanoes in {1_CityName}, with a pungent odor, known as the fire of hell."),
  ("LOC_HD_BUILD_RESOURCE_GOLD2_CORPORATION_TEXT",                           "Chemical companies have laid pipelines in {1_CityName} to safely transport molten sulfur out of the crater."),
  ("LOC_HD_RESOURCE_GOLD2_CHEMISTRY_INDUSTRY_DESCRIPTION",                   "Skin ointments in {1_CityName} use sulfur as the main ingredient, effectively killing scabies mites and fungi."),
  ("LOC_HD_RESOURCE_GOLD2_CHEMISTRY_CORPORATION_DESCRIPTION",                "Pharmaceutical-grade sulfur ointment from {1_CityName} is a common medication for treating acne and seborrheic dermatitis in our civilization."),
  ("LOC_HD_RESOURCE_GOLD2_MEDICINE_INDUSTRY_DESCRIPTION",                    "Sulfur from {1_CityName} is essential for making gunpowder and sulfuric acid; fireworks makers treasure it."),
  ("LOC_HD_RESOURCE_GOLD2_MEDICINE_CORPORATION_DESCRIPTION",                 "The {1_CityName} sulfur chemical combine provides core raw materials for rubber vulcanization and fertilizer industries in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_COD_INDUSTRY_TEXT",                                "The cold, rich fishing grounds of {1_CityName} have provided Atlantic cod for thousands of years of human sustenance."),
  ("LOC_HD_BUILD_RESOURCE_COD_CORPORATION_TEXT",                             "Large trawler processing ships operate in {1_CityName}, processing cod directly into frozen fillets onboard."),
  ("LOC_HD_RESOURCE_COD_MEDICINE_INDUSTRY_DESCRIPTION",                      "Fishermen in {1_CityName} carefully scrape pale yellow oil from cod livers to treat night blindness."),
  ("LOC_HD_RESOURCE_COD_MEDICINE_CORPORATION_DESCRIPTION",                   "{1_CityName} cod liver oil capsules are a memory of growth for a generation in our civilization, protecting bones and vision."),
  ("LOC_HD_RESOURCE_COD_SEAFOOD_INDUSTRY_DESCRIPTION",                       "On the drying racks of {1_CityName}, split cod are hung to dry in the cold wind, becoming durable stockfish."),
  ("LOC_HD_RESOURCE_COD_SEAFOOD_CORPORATION_DESCRIPTION",                    "{1_CityName} Arctic cod burger patties are an important staple in our civilization`s home freezers."),

  ("LOC_HD_BUILD_RESOURCE_MACKEREL_INDUSTRY_TEXT",                           "The coastal waters of {1_CityName} often yield schools of silver-striped mackerel; fishing lights dot the night."),
  ("LOC_HD_BUILD_RESOURCE_MACKEREL_CORPORATION_TEXT",                        "Fish canneries and fishmeal processing plants have designed specialized production lines based on the fatty quality of {1_CityName} mackerel."),
  ("LOC_HD_RESOURCE_MACKEREL_MEDICINE_INDUSTRY_DESCRIPTION",                 "Old fishermen in {1_CityName} often eat fatty mackerel, believing it prevents heart disease in winter."),
  ("LOC_HD_RESOURCE_MACKEREL_MEDICINE_CORPORATION_DESCRIPTION",              "EPA capsules purified from {1_CityName} mackerel oil are star health supplements for regulating blood lipids in our civilization."),
  ("LOC_HD_RESOURCE_MACKEREL_SEAFOOD_INDUSTRY_DESCRIPTION",                  "People in {1_CityName} pickle mackerel with vinegar and salt to make long-lasting vinegar-cured mackerel, unique in flavor."),
  ("LOC_HD_RESOURCE_MACKEREL_SEAFOOD_CORPORATION_DESCRIPTION",               "{1_CityName} mackerel in tomato sauce is a classic taste for emergency supplies and outdoor camping in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_MUSSELS_INDUSTRY_TEXT",                            "On the wave-beaten reefs of {1_CityName}, dark, shiny mussels are densely attached."),
  ("LOC_HD_BUILD_RESOURCE_MUSSELS_CORPORATION_TEXT",                         "A shellfish farming company has used floating raft cultivation to multiply mussel production in {1_CityName} several times over."),
  ("LOC_HD_RESOURCE_MUSSELS_CUISINE_INDUSTRY_DESCRIPTION",                   "Cooking mussels in {1_CityName} is extremely simple; just steam them with white wine, and the meat is sweet and succulent."),
  ("LOC_HD_RESOURCE_MUSSELS_CUISINE_CORPORATION_DESCRIPTION",                "The {1_CityName} “Sea Kiss” mussel-themed restaurant offers diners the most authentic taste of the ocean breeze."),
  ("LOC_HD_RESOURCE_MUSSELS_MARINE_PRODUCTS_INDUSTRY_DESCRIPTION",           "As the tide recedes, beachcombers in {1_CityName} quickly shovel mussels from the rocks into their baskets."),
  ("LOC_HD_RESOURCE_MUSSELS_MARINE_PRODUCTS_CORPORATION_DESCRIPTION",        "Quick-frozen mussel meat from {1_CityName} is a necessary ingredient for seafood pizza and Spanish paella in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_SPONGE_INDUSTRY_TEXT",                             "Divers in {1_CityName} discover soft, porous sponges on the seabed reefs; squeeze them, and water comes out."),
  ("LOC_HD_BUILD_RESOURCE_SPONGE_CORPORATION_TEXT",                          "A sponge processing facility sun-dries and trims natural sponges from {1_CityName} for the bathroom and cleaning markets."),
  ("LOC_HD_RESOURCE_SPONGE_HOUSEHOLD_INDUSTRY_DESCRIPTION",                  "People in {1_CityName} dry sponges and stuff them into cushions and pillows; they are breathable and elastic."),
  ("LOC_HD_RESOURCE_SPONGE_HOUSEHOLD_CORPORATION_DESCRIPTION",               "The {1_CityName} sponge industry turns them into shock-absorbing pads and soundproofing materials, serving our civilization`s precision instruments and home decor."),
  ("LOC_HD_RESOURCE_SPONGE_MARINE_PRODUCTS_INDUSTRY_DESCRIPTION",            "Natural sponges from {1_CityName} are excellent materials for bathing and cleaning wounds, absorbent and soft."),
  ("LOC_HD_RESOURCE_SPONGE_MARINE_PRODUCTS_CORPORATION_DESCRIPTION",         "Natural sponges from {1_CityName} are more durable and environmentally friendly than artificial sponges, highly sought after by sustainability advocates in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_SEA_URCHIN_INDUSTRY_TEXT",                         "The intertidal reefs of {1_CityName} are covered with black, long-spined sea urchins; pry them open carefully, and golden treasure lies within."),
  ("LOC_HD_BUILD_RESOURCE_SEA_URCHIN_CORPORATION_TEXT",                      "A sea urchin processing plant in {1_CityName} shucks fresh urchins and flash-freezes the roe to lock in freshness."),
  ("LOC_HD_RESOURCE_SEA_URCHIN_CUISINE_INDUSTRY_DESCRIPTION",                "Chefs in {1_CityName} mix sea urchin with eggs and cream to steam into sea urchin chawanmushi, incredibly smooth."),
  ("LOC_HD_RESOURCE_SEA_URCHIN_CUISINE_CORPORATION_DESCRIPTION",             "{1_CityName} sea urchin sauce, with its rich creamy brininess, has become a new darling in our civilization`s molecular gastronomy scene."),
  ("LOC_HD_RESOURCE_SEA_URCHIN_SEAFOOD_INDUSTRY_DESCRIPTION",                "The sea urchin roe of {1_CityName} carries a hint of oceanic sweetness; eating it with a spoon is the ultimate treat for the palate."),
  ("LOC_HD_RESOURCE_SEA_URCHIN_SEAFOOD_CORPORATION_DESCRIPTION",             "Canned and frozen sea urchin roe from {1_CityName} is a must-have inventory for high-end sushi restaurants and private chefs in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_ORCA_INDUSTRY_TEXT",                               "In the icy waters off {1_CityName}, pods of black-and-white orcas leap high, the ocean`s top predators."),
  ("LOC_HD_BUILD_RESOURCE_ORCA_CORPORATION_TEXT",                            "A polar yacht company uses {1_CityName} as its home port, organizing eco-friendly whale-watching tours, keeping a strict distance."),
  ("LOC_HD_RESOURCE_ORCA_MARINE_PRODUCTS_INDUSTRY_DESCRIPTION",              "Under traditional whaling quotas, indigenous people in {1_CityName} hunt a small number of orcas; their blubber is a precious source of calories."),
  ("LOC_HD_RESOURCE_ORCA_MARINE_PRODUCTS_CORPORATION_DESCRIPTION",           "The orca-themed {1_CityName} polar culture center sells magnificent ocean-inspired imaginings to people in our civilization."),
  ("LOC_HD_RESOURCE_ORCA_SEA_BEAST_INDUSTRY_DESCRIPTION",                    "Orca performances at {1_CityName} Marine World are breathtaking due to their immense size and intelligence."),
  ("LOC_HD_RESOURCE_ORCA_SEA_BEAST_CORPORATION_DESCRIPTION",                 "Documentaries from the {1_CityName} orca conservation research institute have changed the public`s perception of whales and dolphins in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_WOLF_INDUSTRY_TEXT",                               "In the forests of {1_CityName}, howls echo under the moonlight, symbolizing wildness and unity."),
  ("LOC_HD_BUILD_RESOURCE_WOLF_CORPORATION_TEXT",                            "A wolf research and domestication center has been established in {1_CityName} to explore the ecological and hunting value of wolves."),
  ("LOC_HD_RESOURCE_WOLF_AGRICULTURE_INDUSTRY_DESCRIPTION",                  "Hunters in {1_CityName} tame wolves into loyal hunting companions, collaboratively encircling large prey."),
  ("LOC_HD_RESOURCE_WOLF_AGRICULTURE_CORPORATION_DESCRIPTION",               "Wolf-dog offspring bred in {1_CityName} have become the most effective tools for our civilization`s military police and shepherds."),
  ("LOC_HD_RESOURCE_WOLF_BEAST_INDUSTRY_DESCRIPTION",                        "The reserve in {1_CityName} provides a habitat for wolves, maintaining the balance of the forest ecosystem."),
  ("LOC_HD_RESOURCE_WOLF_BEAST_CORPORATION_DESCRIPTION",                     "The {1_CityName} wolf observation station attracts scientists and photographers from our civilization to document them."),

  ("LOC_HD_BUILD_RESOURCE_TIGER_INDUSTRY_TEXT",                              "In the dense forests of {1_CityName}, tiger stripes loom in the undergrowth, commanding awe."),
  ("LOC_HD_BUILD_RESOURCE_TIGER_CORPORATION_TEXT",                           "A large wildlife conservation fund has been established in {1_CityName} to develop high-end viewing and breeding."),
  ("LOC_HD_RESOURCE_TIGER_BEAST_INDUSTRY_DESCRIPTION",                       "The tiger temple in {1_CityName} is a local religious center; the tiger is seen as the guardian god of the forest."),
  ("LOC_HD_RESOURCE_TIGER_BEAST_CORPORATION_DESCRIPTION",                    "Ecotourism in the {1_CityName} tiger reserve has become a high-end project for nature exploration in our civilization."),
  ("LOC_HD_RESOURCE_TIGER_LEATHER_INDUSTRY_DESCRIPTION",                     "Tiger hunting was once a proof of bravery for warriors in {1_CityName}; tiger skins were made into battle robes and thrones of authority."),
  ("LOC_HD_RESOURCE_TIGER_LEATHER_CORPORATION_DESCRIPTION",                  "Due to the hunting ban, the remaining antique tiger skins from {1_CityName} have become a legend forbidden from trading at auction houses in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_LION_INDUSTRY_TEXT",                               "On the grasslands of {1_CityName}, a lion`s mane catches the setting sun like an emperor`s cloak."),
  ("LOC_HD_BUILD_RESOURCE_LION_CORPORATION_TEXT",                            "A lion conservation and cultural exchange center has been established in {1_CityName} to manage interactions with this king of beasts."),
  ("LOC_HD_RESOURCE_LION_BEAST_INDUSTRY_DESCRIPTION",                        "The ancestors of {1_CityName} used the lion as a totem, emulating its ferocity and carving lion statues to guard their gates."),
  ("LOC_HD_RESOURCE_LION_BEAST_CORPORATION_DESCRIPTION",                     "The {1_CityName} lion-themed hotel and zoo offer visitors in our civilization a taste of true wild thrills."),
  ("LOC_HD_RESOURCE_LION_CELEBRATION_INDUSTRY_DESCRIPTION",                  "At triumphal ceremonies in {1_CityName}, tamed lions were led at the front, showcasing conquest."),
  ("LOC_HD_RESOURCE_LION_CELEBRATION_CORPORATION_DESCRIPTION",               "The {1_CityName} lion taming troupe once presented the splendor of circus arts at major celebrations in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_MUSHROOMS_INDUSTRY_TEXT",                          "On the lush grasslands of {1_CityName}, pure white Tricholoma mushrooms emerge after rain, and herders compete to pick them."),
  ("LOC_HD_BUILD_RESOURCE_MUSHROOMS_CORPORATION_TEXT",                       "An edible fungus company purchases wild Tricholoma from herders on the {1_CityName} grasslands, processing them into canned and dried slices."),
  ("LOC_HD_RESOURCE_MUSHROOMS_CUISINE_INDUSTRY_DESCRIPTION",                 "People in {1_CityName} boil Tricholoma in plain water; the savory broth surpasses chicken soup."),
  ("LOC_HD_RESOURCE_MUSHROOMS_CUISINE_CORPORATION_DESCRIPTION",              "{1_CityName} grassland white Tricholoma sauce, with its extreme umami, has become a premium product in our civilization."),
  ("LOC_HD_RESOURCE_MUSHROOMS_MEDICINE_INDUSTRY_DESCRIPTION",                "Mongolian doctors in {1_CityName} believe Tricholoma can relax muscles, promote blood circulation, and lower blood lipids, often using it in medicinal diets."),
  ("LOC_HD_RESOURCE_MUSHROOMS_MEDICINE_CORPORATION_DESCRIPTION",             "{1_CityName} Tricholoma polysaccharide capsules are in high demand in our civilization`s health product market."),

  ("LOC_HD_BUILD_RESOURCE_MEDIHERBS_INDUSTRY_TEXT",                          "On the misty cliffs of {1_CityName}, herbalists tie ropes to search for precious Dendrobium."),
  ("LOC_HD_BUILD_RESOURCE_MEDIHERBS_CORPORATION_TEXT",                       "A biopharmaceutical group has overcome the challenge of artificial cultivation of Dendrobium and established large-scale planting bases in {1_CityName}."),
  ("LOC_HD_RESOURCE_MEDIHERBS_MEDICINE_INDUSTRY_DESCRIPTION",               "Doctors in {1_CityName} call Dendrobium the “fairy herb,” decocted and drunk to nourish yin, clear heat, and prolong life."),
  ("LOC_HD_RESOURCE_MEDIHERBS_MEDICINE_CORPORATION_DESCRIPTION",            "{1_CityName} Dendrobium capsules and lozenges are top-tier health products for middle-aged and elderly people in our civilization to protect their throats and lungs."),
  ("LOC_HD_RESOURCE_MEDIHERBS_ORNAMENTAL_INDUSTRY_DESCRIPTION",              "In the orchid gardens of {1_CityName}, Dendrobium blooms with elegant yellow flowers, symbolizing refined character."),
  ("LOC_HD_RESOURCE_MEDIHERBS_ORNAMENTAL_CORPORATION_DESCRIPTION",           "{1_CityName} Dendrobium orchid bonsai are the new favorite on the desks and tea tables of the elite class in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_TOXINS_INDUSTRY_TEXT",                             "In the rainforests of {1_CityName}, colorful little poison dart frogs leap among the leaves; indigenous people use them to make poison darts."),
  ("LOC_HD_BUILD_RESOURCE_TOXINS_CORPORATION_TEXT",                          "A biological research institution has simulated the rainforest environment in {1_CityName} to raise poison dart frogs and extract their secretions."),
  ("LOC_HD_RESOURCE_TOXINS_BEAST_INDUSTRY_DESCRIPTION",                      "Poison dart frog exhibits in {1_CityName} are brightly colored, but visitors can only admire their beauty through glass."),
  ("LOC_HD_RESOURCE_TOXINS_BEAST_CORPORATION_DESCRIPTION",                   "The poison dart frog area at the {1_CityName} Amphibian and Reptile Museum is a popular destination for family science trips in our civilization."),
  ("LOC_HD_RESOURCE_TOXINS_MEDICINE_INDUSTRY_DESCRIPTION",                   "Shamans in {1_CityName} dilute poison dart frog venom to treat stubborn nerve pain."),
  ("LOC_HD_RESOURCE_TOXINS_MEDICINE_CORPORATION_DESCRIPTION",                "Ingredients from {1_CityName} poison dart frog venom are being developed into powerful painkillers, providing a new weapon for medical treatment in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_DATES_INDUSTRY_TEXT",                              "By the oases of {1_CityName}, tall date palms hang with clusters of golden, honey-sweet fruit, a gift of the desert."),
  ("LOC_HD_BUILD_RESOURCE_DATES_CORPORATION_TEXT",                           "Date plantations and packing factories have been established in {1_CityName}, selling this sweet product globally."),
  ("LOC_HD_RESOURCE_DATES_BREWING_INDUSTRY_DESCRIPTION",                     "People in {1_CityName} ferment ripe dates to brew palm wine with a caramel flavor."),
  ("LOC_HD_RESOURCE_DATES_BREWING_CORPORATION_DESCRIPTION",                  "{1_CityName} date wine, with its warm sweetness, has become a popular hot drink during winter festivals in our civilization."),
  ("LOC_HD_RESOURCE_DATES_FRUIT_INDUSTRY_DESCRIPTION",                       "Children in {1_CityName} most look forward to the date harvest season; the plump fruits are natural candy."),
  ("LOC_HD_RESOURCE_DATES_FRUIT_CORPORATION_DESCRIPTION",                    "Sun-dried {1_CityName} dates, nutritious and portable, have become a staple energy bar for explorers in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_SAFFRON_INDUSTRY_TEXT",                            "In autumn in {1_CityName}, purple crocuses bloom in the wind; the red stigmas are top-grade medicine."),
  ("LOC_HD_BUILD_RESOURCE_SAFFRON_CORPORATION_TEXT",                         "A spice group meticulously manages the harvesting and drying of saffron from {1_CityName}; each gram is priceless."),
  ("LOC_HD_RESOURCE_SAFFRON_MEDICINE_INDUSTRY_DESCRIPTION",                  "Old physicians in {1_CityName} steep saffron in water for patients to drink, invigorating blood, relieving depression, and warming the body."),
  ("LOC_HD_RESOURCE_SAFFRON_MEDICINE_CORPORATION_DESCRIPTION",               "{1_CityName} crocin has been developed into precious health supplements for anti-depression and eye protection in our civilization."),
  ("LOC_HD_RESOURCE_SAFFRON_ORNAMENTAL_INDUSTRY_DESCRIPTION",                "People in {1_CityName} plant crocus bulbs in stone troughs; when they bloom, the yard is radiant with a faint fragrance."),
  ("LOC_HD_RESOURCE_SAFFRON_ORNAMENTAL_CORPORATION_DESCRIPTION",             "{1_CityName} saffron bulbs are exported, allowing gardening enthusiasts in our civilization to also grow “red gold.”"),

  ("LOC_HD_BUILD_RESOURCE_TOMATO_INDUSTRY_TEXT",                             "In the vegetable gardens of {1_CityName}, bright red tomatoes hang on the vines, initially grown only as ornamentals."),
  ("LOC_HD_BUILD_RESOURCE_TOMATO_CORPORATION_TEXT",                          "A food processing plant has risen in {1_CityName}, turning fresh tomatoes into easily stored sauces and drinks."),
  ("LOC_HD_RESOURCE_TOMATO_BEVERAGE_INDUSTRY_DESCRIPTION",                   "People in {1_CityName} were the first to try juicing juicy tomatoes into a crimson drink, refreshing and appetizing when chilled."),
  ("LOC_HD_RESOURCE_TOMATO_BEVERAGE_CORPORATION_DESCRIPTION",                "The “Red Diamond” tomato juice brand from {1_CityName} is a bestseller on supermarket shelves as a healthy breakfast drink in our civilization."),
  ("LOC_HD_RESOURCE_TOMATO_FRUIT_INDUSTRY_DESCRIPTION",                      "The markets of {1_CityName} have many varieties of tomatoes, some sweet and sour, eaten directly as fruit."),
  ("LOC_HD_RESOURCE_TOMATO_FRUIT_CORPORATION_DESCRIPTION",                   "The cherry tomato greenhouse base in {1_CityName} ensures a fresh garnish on our civilization`s tables year-round."),

  ("LOC_HD_BUILD_RESOURCE_BARLEY_INDUSTRY_TEXT",                             "On the thin, high-altitude air of the {1_CityName} plateau, only resilient highland barley can mature and bear grain."),
  ("LOC_HD_BUILD_RESOURCE_BARLEY_CORPORATION_TEXT",                          "The local government of {1_CityName} strongly promotes the highland barley processing industry, striving to solve the livelihood problems of plateau farmers."),
  ("LOC_HD_RESOURCE_BARLEY_BREWING_INDUSTRY_DESCRIPTION",                    "Breweries in {1_CityName} use highland barley and snowmelt to distill a fierce, clear spirit."),
  ("LOC_HD_RESOURCE_BARLEY_BREWING_CORPORATION_DESCRIPTION",                 "“Snow Mountain Soul” liquor from the {1_CityName} highland barley distillery is a new star in our civilization`s high-strength liquor market."),
  ("LOC_HD_RESOURCE_BARLEY_CROPS_INDUSTRY_DESCRIPTION",                      "Farmers in {1_CityName} roast and grind highland barley into tsampa, their energy source for pilgrimages and work."),
  ("LOC_HD_RESOURCE_BARLEY_CROPS_CORPORATION_DESCRIPTION",                   "{1_CityName} highland barley flakes and biscuits are brought to breakfast tables in our civilization, offering the fragrance of plateau grain."),

  ("LOC_HD_BUILD_RESOURCE_POTATO_INDUSTRY_TEXT",                             "Sweet potato vines grow wildly, forming plump tubers underground on the farms of {1_CityName}, saving many from famine."),
  ("LOC_HD_BUILD_RESOURCE_POTATO_CORPORATION_TEXT",                          "The local government of {1_CityName} vigorously promotes the processing potential of sweet potatoes, producing starch, noodles, and snacks to increase farmers` income."),
  ("LOC_HD_RESOURCE_POTATO_CROPS_INDUSTRY_DESCRIPTION",                      "Children in {1_CityName} look forward most to the street roast sweet potato stall; peel the burnt skin and it`s scalding hot and sweet."),
  ("LOC_HD_RESOURCE_POTATO_CROPS_CORPORATION_DESCRIPTION",                   "Frozen semi-finished roast sweet potatoes from {1_CityName} allow urbanites in our civilization to relive their childhood in the microwave."),
  ("LOC_HD_RESOURCE_POTATO_CUISINE_INDUSTRY_DESCRIPTION",                    "People in {1_CityName} grind sweet potatoes into pulp, then drain into smooth noodles; paired with sour and spicy soup, it`s a divine flavor."),
  ("LOC_HD_RESOURCE_POTATO_CUISINE_CORPORATION_DESCRIPTION",                 "Dried sweet potato strips and purple sweet potato snacks from {1_CityName}, with their natural sweetness and chewiness, have stirred up a whirlwind among white-collar workers in our civilization."),

  ("LOC_HD_BUILD_RESOURCE_SORGHUM_INDUSTRY_TEXT",                            "Red sorghum heads grow tenaciously in the drylands of {1_CityName}, like burning torches."),
  ("LOC_HD_BUILD_RESOURCE_SORGHUM_CORPORATION_TEXT",                         "A distilling group has established a sorghum cultivation base in {1_CityName}, exclusively supplying raw materials for its famous liquor production."),
  ("LOC_HD_RESOURCE_SORGHUM_BREWING_INDUSTRY_DESCRIPTION",                   "Distilleries in {1_CityName} use Daqu to ferment sorghum, distilling a pungent, aromatic Chinese baijiu."),
  ("LOC_HD_RESOURCE_SORGHUM_BREWING_CORPORATION_DESCRIPTION",                "{1_CityName} sorghum baijiu, with its rich cellar aroma and long, complex finish, has won top awards at our civilization`s liquor competitions."),
  ("LOC_HD_RESOURCE_SORGHUM_CROPS_INDUSTRY_DESCRIPTION",                     "People in {1_CityName} grind sorghum and steam it into red cat`s ear noodles, dipped in sour and spicy sauce—a true homestyle taste."),
  ("LOC_HD_RESOURCE_SORGHUM_CROPS_CORPORATION_DESCRIPTION",                  "{1_CityName} sorghum grain and feed processing industry provide a solid backbone for our civilization`s animal husbandry and dining tables."),

  ("LOC_HD_BUILD_RESOURCE_STRAWBERRY_INDUSTRY_TEXT",                         "In the strawberry fields of {1_CityName}, bright red, delicate heart-shaped berries hide under lush green leaves."),
  ("LOC_HD_BUILD_RESOURCE_STRAWBERRY_CORPORATION_TEXT",                      "An agricultural cooperative has popularized elevated substrate cultivation in the villages of {1_CityName}; the yield of pesticide-free strawberries increases year by year."),
  ("LOC_HD_RESOURCE_STRAWBERRY_BREWING_INDUSTRY_DESCRIPTION",                "People in {1_CityName} ferment surplus strawberries to create pink, bubbly sparkling strawberry wine."),
  ("LOC_HD_RESOURCE_STRAWBERRY_BREWING_CORPORATION_DESCRIPTION",             "{1_CityName} strawberry liqueur is a favorite at young women`s parties in our civilization, sweetly intoxicating."),
  ("LOC_HD_RESOURCE_STRAWBERRY_FRUIT_INDUSTRY_DESCRIPTION",                  "In the early morning of {1_CityName}, strawberries with dew are picked and placed in small baskets lined with soft grass for sale."),
  ("LOC_HD_RESOURCE_STRAWBERRY_FRUIT_CORPORATION_DESCRIPTION",               "The {1_CityName} strawberry picking festival and strawberry dessert pop-up shops are romantic springtime landmarks in our civilization.");

insert or replace into LocalizedText (Language, Tag, Text) values
  ("zh_Hans_CN",  "LOC_HD_INDUSTRY_EFFECT_TEXT",                                            "行业效果：[NEWLINE]{1_Effect}"),
  ("zh_Hans_CN",  "LOC_HD_CORPORATION_EFFECT_TEXT",                                         "公司效果：[NEWLINE]{1_Effect}"),
  ("zh_Hans_CN",  "LOC_SELECT_INDUSTRY_CATEGORY_TEXT",                                      "[COLOR:Civ6Red]点击图标选择行业类别。[ENDCOLOR]"),
  ("zh_Hans_CN",  "LOC_SELECT_CORPORATION_CATEGORY_TEXT",                                   "[COLOR:Civ6Red]点击图标选择公司类别。[ENDCOLOR]"),
  ("zh_Hans_CN",  "LOC_NEED_ACTIVATE_SECOND_INDUSTRY_EFFECT_TEXT",                          "[COLOR:Civ6Red]需要建造商业中心三级建筑或港口二级建筑以激活{1_Category}行业的加成效果：[ENDCOLOR][NEWLINE]{2_Effect}"),
  ("zh_Hans_CN",  "LOC_NEED_ACTIVATE_SECOND_CORPORATION_EFFECT_TEXT",                       "[COLOR:Civ6Red]需要建造商业中心四级建筑或港口三级建筑以激活{1_Category}公司的加成效果：[ENDCOLOR][NEWLINE]{2_Effect}"),
  
  ("zh_Hans_CN",  "LOC_HD_CUSTOMEVENT_SELECT_INDUSTRY_CATEGORY_NAME",                       "[ICON_GreatWork_Product] {1_City}建立了 {2_Resource}行业"),
  ("zh_Hans_CN",  "LOC_HD_CUSTOMEVENT_SELECT_INDUSTRY_CATEGORY_DESCRIPTION",                "现在我们需要做出选择：先专注于该资源的哪一种用途，以激活对应的行业加成效果？"),
  ("zh_Hans_CN",  "LOC_HD_CUSTOMEVENT_SELECT_CORPORATION_CATEGORY_NAME",                    "[ICON_GreatWork_Product] {1_City}建立了 {2_Resource}公司"),
  ("zh_Hans_CN",  "LOC_HD_CUSTOMEVENT_SELECT_CORPORATION_CATEGORY_DESCRIPTION",             "现在我们需要做出选择：先专注于该资源的哪一种用途，以激活对应的公司加成效果？"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_BANANAS_INDUSTRY_TEXT",                            "{1_CityName}富有智慧的劳动人民从杂草中选育出了多种香蕉。现在是时候选取良种播种了。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_BANANAS_CORPORATION_TEXT",                         "{1_CityName}产的香蕉味道甘美却保存不便。食品加工厂计划用这些材料制作便于运输和出售的饮料和食品。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_BANANAS_CROPS_INDUSTRY_DESCRIPTION",                     "{1_CityName}林中的居民早已习惯将大蕉作为主食。在此地的林中大规模栽培大蕉可以充分利用土地。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_BANANAS_CROPS_CORPORATION_DESCRIPTION",                  "商业化的大蕉种植园使{1_CityName}的林地得到了深度开发。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_BANANAS_FRUIT_INDUSTRY_DESCRIPTION",                     "{1_CityName}的地方官向您的宫廷进贡香蕉用于制作夏日果盘。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_BANANAS_FRUIT_CORPORATION_DESCRIPTION",                  "随着成熟的运输体系建立，{1_CityName}所产的香甜香蕉将走进我国的千家万户。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_CATTLE_INDUSTRY_TEXT",                             "千百年来，{1_CityName}周边的优质的牧草地都吸引着牧民携带牛群在其间迁徙。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_CATTLE_CORPORATION_TEXT",                          "“{1_CityName}牛”在我国一直是优质牛种的代称。现代畜牧业的建立将进一步推动良种培育，为市民提供丰富的牛肉牛奶产品。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_CATTLE_BEVERAGE_INDUSTRY_DESCRIPTION",                   "引用用牛奶让{1_CityName}的人民茁壮成长。牧场也成为本地产业的支柱。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_CATTLE_BEVERAGE_CORPORATION_DESCRIPTION",                "每年有无数牛奶在{1_CityName}的工厂中灌入玻璃瓶进入全国市场。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_CATTLE_LEATHER_INDUSTRY_DESCRIPTION",                    "{1_CityName}皮革工匠建立了庞大的工会，主导着当地皮革市场。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_CATTLE_LEATHER_CORPORATION_DESCRIPTION",                 "{1_CityName}生产的皮衣、皮鞋装点了我国的国民。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_COPPER_INDUSTRY_TEXT",                             "{1_CityName}丘陵间裸露的翠绿色铜脉吸引了第一批矿工在此聚集。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_COPPER_CORPORATION_TEXT",                          "随着地质勘探的深入，一座现代化的冶金联合体在{1_CityName}拔地而起，将开采、冶炼合为一体。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_COPPER_METALLURGY_INDUSTRY_DESCRIPTION",                 "{1_CityName}的冶铜作坊昼夜不息，将矿石化作泛着红光的铜锭。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_COPPER_METALLURGY_CORPORATION_DESCRIPTION",              "标准化的铜材供给让我国的工业齿轮得以顺畅运转。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_COPPER_MINTING_INDUSTRY_DESCRIPTION",                    "{1_CityName}的铜料被浇铸成带孔的钱币，促进了跨地区的交易。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_COPPER_MINTING_CORPORATION_DESCRIPTION",                 "{1_CityName}皇家铸币局的铜币成色稳定，成为我国人民心目中值得信赖的通货。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_CRABS_INDUSTRY_TEXT",                              "每到退潮，{1_CityName}城外的滩涂上便随处可见横行觅食的螃蟹，村民提桶拾取。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_CRABS_CORPORATION_TEXT",                           "{1_CityName}的捕蟹船队配备了最新的冷藏设备，将鲜美海产送往远方。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_CRABS_CUISINE_INDUSTRY_DESCRIPTION",                     "{1_CityName}的厨师精心研究出多种烹蟹之法，引得四方食客慕名而来。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_CRABS_CUISINE_CORPORATION_DESCRIPTION",                  "以{1_CityName}命名的蟹宴连锁店在我国遍地开花，令人垂涎的香气弥漫街巷。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_CRABS_SEAFOOD_INDUSTRY_DESCRIPTION",                     "{1_CityName}的渔船归来时，船舱里满是肥壮的螃蟹，为港口带来勃勃生机。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_CRABS_SEAFOOD_CORPORATION_DESCRIPTION",                  "蟹肉罐头和冷冻蟹腿从{1_CityName}启程，成为我国餐桌上的海味佳肴。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_DEER_INDUSTRY_TEXT",                               "{1_CityName}外围的苍翠林地中，优雅的鹿群如同森林的精灵，一直被猎户尊崇。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_DEER_CORPORATION_TEXT",                            "为了保护野生鹿群同时满足市场需求，{1_CityName}建立了专门的驯鹿牧场。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_DEER_BEAST_INDUSTRY_DESCRIPTION",                        "在{1_CityName}的皇家猎苑里，来自各地的珍奇鹿种被精心养护，供人观赏。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_DEER_BEAST_CORPORATION_DESCRIPTION",                     "保育良好的鹿苑使得{1_CityName}成为了我国最受欢迎的自然旅游目的地。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_DEER_LEATHER_INDUSTRY_DESCRIPTION",                      "{1_CityName}的皮匠擅长将鹿皮鞣制成极为柔韧的皮革，制作高级手套。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_DEER_LEATHER_CORPORATION_DESCRIPTION",                   "{1_CityName}“仙鹿”牌皮革制品以其细腻的质感，深受我国上流社会的青睐。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_FISH_INDUSTRY_TEXT",                               "每年春季，成群银白的鲅鱼回游至{1_CityName}近海，渔民们早已理好渔网，等待这场一年一度的丰收。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_FISH_CORPORATION_TEXT",                            "远洋捕捞公司与冷链加工厂在{1_CityName}落户，将鲅鱼速冻切片，源源不断送往内陆市场。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_FISH_CUISINE_INDUSTRY_DESCRIPTION",                      "{1_CityName}的厨子将鲅鱼剁成鱼蓉，挤成洁白莹润的鱼面，一碗鱼面鲜掉眉毛。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_FISH_CUISINE_CORPORATION_DESCRIPTION",                   "{1_CityName}马鲛鱼馄饨与鱼饺子，凭借独特的弹嫩口感，在我国速冻食品界脱颖而出。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_FISH_SEAFOOD_INDUSTRY_DESCRIPTION",                      "{1_CityName}港口的早市上，新鲜的鲅鱼在碎冰上闪着银光，懂行的主顾一早就来抢购。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_FISH_SEAFOOD_CORPORATION_DESCRIPTION",                   "{1_CityName}出品的鲅鱼片与鱼丸，弹牙鲜美，成为我国火锅与家常菜的人气食材。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_RICE_INDUSTRY_TEXT",                               "{1_CityName}的先民开凿水渠，将沼泽变为镜子般的稻田，自此饭稻羹鱼成为日常。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_RICE_CORPORATION_TEXT",                            "{1_CityName}的碾米厂和粮食公司引进精磨技术，让米粒变得晶莹剔透。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_RICE_BREWING_INDUSTRY_DESCRIPTION",                      "{1_CityName}的酿酒师发现将大米糖化发酵后，能得到清冽甘醇的米酒。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_RICE_BREWING_CORPORATION_DESCRIPTION",                   "{1_CityName}清酒以其清雅口感成为我国宴请的佳品。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_RICE_CROPS_INDUSTRY_DESCRIPTION",                        "{1_CityName}平原上稻浪翻滚，沉甸甸的稻穗是农人最好的慰藉。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_RICE_CROPS_CORPORATION_DESCRIPTION",                     "{1_CityName}作为我国的粮仓之一，稳定的水稻产量保障了亿万人口的饭碗。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_SHEEP_INDUSTRY_TEXT",                              "{1_CityName}高原上的牧羊人，终年赶着白云般的羊群追逐水草。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_SHEEP_CORPORATION_TEXT",                           "纺织工业家看中了{1_CityName}的优质羊毛，在此设立大规模毛纺厂。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SHEEP_CLOTH_INDUSTRY_DESCRIPTION",                       "{1_CityName}的织布机吱呀作响，将蓬松的羊毛化作保暖的呢绒衣料。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SHEEP_CLOTH_CORPORATION_DESCRIPTION",                    "“暖云”羊毛衫从{1_CityName}起运，温暖了我国无数个寒冷的冬天。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SHEEP_STATIONERY_INDUSTRY_DESCRIPTION",                  "{1_CityName}抄写员使用当地羊皮制作的经卷，千年之后字迹依然清晰。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SHEEP_STATIONERY_CORPORATION_DESCRIPTION",               "{1_CityName}羊皮纸厂为我国的档案馆和重要文书提供经久耐用的书写材料。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_STONE_INDUSTRY_TEXT",                              "{1_CityName}边缘矗立着大片的安山岩矿脉，质地坚硬，是优良的石材。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_STONE_CORPORATION_TEXT",                           "采石公司利用机械切割与轨道运输，令{1_CityName}的石材产量激增。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_STONE_CONSTRUCTION_INDUSTRY_DESCRIPTION",                "{1_CityName}的建筑物大多就地取材，安山岩垒砌的墙体厚重而庄严。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_STONE_CONSTRUCTION_CORPORATION_DESCRIPTION",             "{1_CityName}出产的标准石料被广泛用于我国的各项大型公共工程。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_STONE_STATIONERY_INDUSTRY_DESCRIPTION",                  "{1_CityName}的石匠将安山岩板打磨光滑，供学生们练习书写与计算。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_STONE_STATIONERY_CORPORATION_DESCRIPTION",               "{1_CityName}生产的石板与石笔陪伴了我国一代又一代学童的启蒙时光。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_WHEAT_INDUSTRY_TEXT",                              "{1_CityName}广阔的原野上，金色的麦浪与蓝天相接，丰饶的气息令人陶醉。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_WHEAT_CORPORATION_TEXT",                           "大型面粉集团在{1_CityName}设立了仓储与研磨中心，磨坊的声响日夜不息。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_WHEAT_BREWING_INDUSTRY_DESCRIPTION",                     "{1_CityName}的修道院将多余的小麦精心发酵，酿出解渴提神的麦酒。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_WHEAT_BREWING_CORPORATION_DESCRIPTION",                  "{1_CityName}的“金穗”啤酒厂创新采用啤酒花，酿出的精酿啤酒风靡我国。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_WHEAT_CROPS_INDUSTRY_DESCRIPTION",                       "{1_CityName}的农民每逢收割季节，便全家出动挥镰割麦，颗粒归仓。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_WHEAT_CROPS_CORPORATION_DESCRIPTION",                    "{1_CityName}面包厂的香气弥漫整个街区，松软的面包由此进入千家万户。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_CITRUS_INDUSTRY_TEXT",                             "{1_CityName}温和湿润的山坡上，栽满了一棵棵绿叶金果的柑橘树。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_CITRUS_CORPORATION_TEXT",                          "{1_CityName}成为了冷链物流的枢纽，将容易腐烂的柑橘快速分销。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_CITRUS_CUISINE_INDUSTRY_DESCRIPTION",                    "{1_CityName}主妇善于用柑橘皮制作蜜饯和陈皮，化清鲜为醇厚。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_CITRUS_CUISINE_CORPORATION_DESCRIPTION",                 "{1_CityName}柑橘果酱罐头出口至我国，是早餐吐司的完美伴侣。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_CITRUS_FRUIT_INDUSTRY_DESCRIPTION",                      "压弯枝头的蜜橘是{1_CityName}秋天的味道，剥开薄皮，满手都是香气。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_CITRUS_FRUIT_CORPORATION_DESCRIPTION",                   "{1_CityName}品牌的“甜太阳”柑橘，在我国水果市场上代表着高品质的鲜甜。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_COCOA_INDUSTRY_TEXT",                              "{1_CityName}热带雨林的荫蔽下，可可树结出形如橄榄球的彩色果实。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_COCOA_CORPORATION_TEXT",                           "发酵与干燥基地在{1_CityName}可可种植园的周边建立，掌控可可豆初加工环节。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_COCOA_BEVERAGE_INDUSTRY_DESCRIPTION",                    "{1_CityName}贵族将可可豆磨成粉，加入沸水，加入香料打起泡沫，饮下众神的饮品。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_COCOA_BEVERAGE_CORPORATION_DESCRIPTION",                 "{1_CityName}可可粉公司为我国的孩子们带来了热腾腾的香甜可可。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_COCOA_MINTING_INDUSTRY_DESCRIPTION",                     "在{1_CityName}的市场上，装在小袋里的可可豆可以直接换来玉、盐和布匹。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_COCOA_MINTING_CORPORATION_DESCRIPTION",                  "可可豆曾在{1_CityName}漫长的历史中充当小额货币，至今仍是财富的象征。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_COFFEE_INDUSTRY_TEXT",                             "{1_CityName}的高原上，红宝石般的咖啡果实挂满枝条，成熟后就要立刻采摘。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_COFFEE_CORPORATION_TEXT",                          "咖啡连锁巨头与{1_CityName}农庄签订直购协议，打造单一产地精品咖啡。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_COFFEE_ART_INDUSTRY_DESCRIPTION",                        "{1_CityName}的咖啡馆里，诗人与画家常聚在这里高谈阔论，碰撞灵感。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_COFFEE_ART_CORPORATION_DESCRIPTION",                     "{1_CityName}咖啡文化节每年吸引我国的艺术家前来驻留，诞生了无数伟大作品。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_COFFEE_BEVERAGE_INDUSTRY_DESCRIPTION",                   "{1_CityName}的清晨从一杯浓郁的黑咖啡开始，提神醒脑的香气弥漫大街小巷。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_COFFEE_BEVERAGE_CORPORATION_DESCRIPTION",                "{1_CityName}烘焙咖啡豆以均衡的风味，被我国白领奉为每日必需的口粮。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_COTTON_INDUSTRY_TEXT",                             "{1_CityName}的阳光使棉田炸开一片洁白云朵，采棉人的布袋被塞得满满当当。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_COTTON_CORPORATION_TEXT",                          "{1_CityName}的巨型轧花厂和纺纱车间产出的棉布几乎售卖到了地球每一个角落。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_COTTON_CLOTH_INDUSTRY_DESCRIPTION",                      "{1_CityName}织造的棉布透气舒适，让平民也得以穿上柔软贴身的衣物。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_COTTON_CLOTH_CORPORATION_DESCRIPTION",                   "{1_CityName}纯棉服装以其亲民与舒适，占据了我国基础成衣市场的半壁江山。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_COTTON_OIL_INDUSTRY_DESCRIPTION",                        "{1_CityName}榨油工将轧花剩下的棉籽收集起来，榨出可作灯油和肥皂的棉籽油。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_COTTON_OIL_CORPORATION_DESCRIPTION",                     "{1_CityName}棉籽油精炼厂将副产品变为宝，支援了我国的油脂化工与食用调和油产业。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_DIAMONDS_INDUSTRY_TEXT",                           "{1_CityName}古老的金伯利岩筒中，隐藏着闪耀火彩的宝石级钻石原石。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_DIAMONDS_CORPORATION_TEXT",                        "规范化的钻石开采极大增加了产量，也减少了{1_CityName}地区争夺资源带来的血腥冲突。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_DIAMONDS_ART_INDUSTRY_DESCRIPTION",                      "用钻石刀头雕刻的水晶，以及钻石为灵感的艺术品在{1_CityName}诞生。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_DIAMONDS_ART_CORPORATION_DESCRIPTION",                   "{1_CityName}戴比尔斯风格的艺术钻石博物馆，吸引我国的富豪与艺术家前来交流。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_DIAMONDS_DECORATION_INDUSTRY_DESCRIPTION",               "{1_CityName}珠宝匠将钻石镶嵌于王冠与权杖之上，象征无上的权力和坚贞。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_DIAMONDS_DECORATION_CORPORATION_DESCRIPTION",            "{1_CityName}切割中心出产的钻石订婚戒指，照亮了我国无数恋人的承诺。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_DYES_INDUSTRY_TEXT",                               "{1_CityName}的工匠尝试了从各种物品中提取珍贵的燃料，从海中贝壳到山间花草无所不用其极。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_DYES_CORPORATION_TEXT",                            "从生物中提取染料的传统办法难以满足市场的需求，{1_CityName}的化学家正在着手解决这个难题。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_DYES_CLOTH_INDUSTRY_DESCRIPTION",                        "{1_CityName}的染坊将白布染成彩虹般的绚烂色彩，整个城市都变得鲜活。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_DYES_CLOTH_CORPORATION_DESCRIPTION",                     "时尚中心为我国的服装品牌提供最前沿的色彩定制服务。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_DYES_MARINE_PRODUCTS_INDUSTRY_DESCRIPTION",              "{1_CityName}的潜水员采集骨螺与海草，熬煮出一匹匹价值连城的紫色与靛蓝布匹。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_DYES_MARINE_PRODUCTS_CORPORATION_DESCRIPTION",           "从{1_CityName}海产中提取的天然色素，依然是高级定制与艺术品修复的挚爱。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_FURS_INDUSTRY_TEXT",                               "{1_CityName}的严冬使得貂、狐等动物长出丰厚的皮毛，猎户靠此维生。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_FURS_CORPORATION_TEXT",                            "皮草文化集团在{1_CityName}大规模收购皮毛生产时装。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_FURS_CLOTH_INDUSTRY_DESCRIPTION",                        "{1_CityName}的设计师将优质皮草作为点缀，设计出前卫的皮草时装。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_FURS_CLOTH_CORPORATION_DESCRIPTION",                     "{1_CityName}皮草配饰品牌在我国的秋冬时装周上屡获殊荣。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_FURS_LEATHER_INDUSTRY_DESCRIPTION",                      "{1_CityName}皮匠鞣制出的皮毛柔软华美，是抵御寒冬的极佳衣物面料。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_FURS_LEATHER_CORPORATION_DESCRIPTION",                   "{1_CityName}皮草大衣成为了我国北方都会富人衣橱里的身份象征。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_GYPSUM_INDUSTRY_TEXT",                             "{1_CityName}巨大的盐湖沉积了厚厚的石膏层，如同被压实的雪花。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_GYPSUM_CORPORATION_TEXT",                          "石膏矿场在{1_CityName}进行机械化采掘，支撑起建筑装饰与医疗行业。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_GYPSUM_ART_INDUSTRY_DESCRIPTION",                        "{1_CityName}的雕塑家用石膏翻模，将瞬间的灵感变为永恒的洁白雕像。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_GYPSUM_ART_CORPORATION_DESCRIPTION",                     "{1_CityName}出产的石膏粉细腻粘稠，是我国美术学院的标配教具材料。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_GYPSUM_MEDICINE_INDUSTRY_DESCRIPTION",                   "{1_CityName}的骨科医生使用石膏绷带固定断骨，让伤者在安静中愈合。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_GYPSUM_MEDICINE_CORPORATION_DESCRIPTION",                "{1_CityName}医用石膏公司为我国的医院提供快速固化的高品质骨伤材料。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_INCENSE_INDUSTRY_TEXT",                            "{1_CityName}庙中的祭司采集树脂与香木，缭绕的烟雾承载着人们的祈愿升向天空。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_INCENSE_CORPORATION_TEXT",                         "香料公司接手了{1_CityName}熏香的商业化生产，将信仰的芬芳装进精美的盒子。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_INCENSE_CELEBRATION_INDUSTRY_DESCRIPTION",               "没有熏香的庆典在{1_CityName}是不完整的，从婚礼到凯旋，总需香气相伴。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_INCENSE_CELEBRATION_CORPORATION_DESCRIPTION",            "{1_CityName}特制庆典熏香，是我国国家大典和节日中不可或缺的氛围担当。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_INCENSE_MEDICINE_INDUSTRY_DESCRIPTION",                  "{1_CityName}的医师认为熏香能安神辟秽，点燃一支，病房便不再沉闷。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_INCENSE_MEDICINE_CORPORATION_DESCRIPTION",               "{1_CityName}出品的药香通过呼吸道给药的理念，重新获得我国现代医学的重视。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_IVORY_INDUSTRY_TEXT",                              "{1_CityName}的大草原上，雄伟的象群在漫步，留下珍贵的象牙，被当地人视为圣物。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_IVORY_CORPORATION_TEXT",                           "大象保护{1_CityName}成立，规范象牙的使用。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_IVORY_BEAST_INDUSTRY_DESCRIPTION",                       "{1_CityName}建立了自然保护区，庞大的象群成为该地最壮观的风景线。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_IVORY_BEAST_CORPORATION_DESCRIPTION",                    "{1_CityName}的生态旅游以观赏野生象群为招牌，吸引了我国无数游客。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_IVORY_DECORATION_INDUSTRY_DESCRIPTION",                  "{1_CityName}的牙雕大师能在一根象牙上雕刻出整卷史诗故事，巧夺天工。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_IVORY_DECORATION_CORPORATION_DESCRIPTION",               "古代{1_CityName}的象牙雕刻珍品被我国各大博物馆珍藏，是古代手工艺的巅峰代表。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_JADE_INDUSTRY_TEXT",                               "{1_CityName}河床中的籽料与山中的矿脉，蕴藏着温润细腻的美玉。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_JADE_CORPORATION_TEXT",                            "有一家公司在{1_CityName}整合了传统作坊，建立了现代化的玉石雕刻生产线。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_JADE_ART_INDUSTRY_DESCRIPTION",                          "{1_CityName}的玉雕大师能根据玉料的皮色，巧雕出栩栩如生的山水人物。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_JADE_ART_CORPORATION_DESCRIPTION",                       "{1_CityName}玉雕摆件被我国国家级博物馆和私人藏家竞相收藏。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_JADE_DECORATION_INDUSTRY_DESCRIPTION",                   "{1_CityName}人相信玉能护身，男女老幼佩戴玉佩玉镯蔚然成风。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_JADE_DECORATION_CORPORATION_DESCRIPTION",                "{1_CityName}玉器行打造的平安扣与玉牌，寄托了我国人民的祈福与乡愁。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_MARBLE_INDUSTRY_TEXT",                             "{1_CityName}的采石场切开了山体，露出洁白温润、纹理动人的大理石岩心。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_MARBLE_CORPORATION_TEXT",                          "石材集团投入大量机械，从{1_CityName}开采出世界顶级的建筑与雕像石材。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_MARBLE_ART_INDUSTRY_DESCRIPTION",                        "伟大的艺术天才在{1_CityName}挑选大理石，将禁锢在石中的天使解放出来。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_MARBLE_ART_CORPORATION_DESCRIPTION",                     "{1_CityName}卡拉拉级大理石雕像，装饰了我国最负盛名的歌剧院与广场。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_MARBLE_CONSTRUCTION_INDUSTRY_DESCRIPTION",               "{1_CityName}的大理石板被用来铺作神庙的台阶与宫殿的外墙，光洁而恒久。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_MARBLE_CONSTRUCTION_CORPORATION_DESCRIPTION",            "{1_CityName}大理石幕墙让我国的摩天楼群闪耀着古典与高贵。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_MERCURY_INDUSTRY_TEXT",                            "{1_CityName}的朱砂矿在焙烧后析出神秘的银色液珠——水银，令炼金术士痴迷。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_MERCURY_CORPORATION_TEXT",                         "提炼厂采取了新的密闭工艺，在安全前提下满足{1_CityName}工业对水银的需求。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_MERCURY_ART_INDUSTRY_DESCRIPTION",                       "水银在流体的形态变化中启发了{1_CityName}的动态雕塑家，创作出匪夷所思的作品。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_MERCURY_ART_CORPORATION_DESCRIPTION",                    "{1_CityName}水银开关装置曾是我国前卫艺术与精密仪器的象征。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_MERCURY_CONSTRUCTION_INDUSTRY_DESCRIPTION",              "{1_CityName}工匠将水银与锡箔混合涂在雕像与穹顶，形成金色的汞齐镀层，金碧辉煌。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_MERCURY_CONSTRUCTION_CORPORATION_DESCRIPTION",           "{1_CityName}水银用于大型金矿的混汞提金，是我国黄金产量的幕后功臣。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_PEARLS_INDUSTRY_TEXT",                             "{1_CityName}的潜水人憋一口气下潜，从海底采回孕育着奇迹的珍珠贝。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_PEARLS_CORPORATION_TEXT",                          "海水珍珠养殖场在{1_CityName}海湾普及插核技术，让珍珠变得圆润可控。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_PEARLS_DECORATION_INDUSTRY_DESCRIPTION",                 "{1_CityName}的匠人用丝线串起颗颗珍珠，制成冠冕与项链，衬托贵族气质。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_PEARLS_DECORATION_CORPORATION_DESCRIPTION",              "{1_CityName}南洋金珠与黑珍珠，是我国珠宝匣中的必备收藏。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_PEARLS_MARINE_PRODUCTS_INDUSTRY_DESCRIPTION",            "{1_CityName}出产的海珠带着母贝的光泽，是送给挚爱最珍贵的礼物。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_PEARLS_MARINE_PRODUCTS_CORPORATION_DESCRIPTION",         "{1_CityName}珍珠粉以其养颜功效，在我国的汉方美容品中历史悠远。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_SALT_INDUSTRY_TEXT",                               "{1_CityName}的盐田如一面面天空之镜，蒸发海水留下洁白如雪的盐晶。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_SALT_CORPORATION_TEXT",                            "{1_CityName}工业化的盐井正在向我国持续提供食盐。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SALT_CHEMISTRY_INDUSTRY_DESCRIPTION",                    "{1_CityName}盐场不仅是食物的来源，还是制备纯碱和盐酸的原料。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SALT_CHEMISTRY_CORPORATION_DESCRIPTION",                 "{1_CityName}盐化工基地为我国提供了半数以上的氯碱和塑料原料。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SALT_SEASONING_INDUSTRY_DESCRIPTION",                    "{1_CityName}的厨师遵循“无盐不鲜”的古训，用海盐激发出食材本味。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SALT_SEASONING_CORPORATION_DESCRIPTION",                 "{1_CityName}玫瑰盐和风味盐，在我国美食达人的厨房里占据了一席调料架。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_SILK_INDUSTRY_TEXT",                               "蚕宝宝啃食桑叶沙沙作响，吐出了最娇贵的丝线，这是{1_CityName}的珍宝。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_SILK_CORPORATION_TEXT",                            "{1_CityName}纺织厂改良的缫丝与织造机械，让往日王谢堂前的丝绸也出现在的平民百姓身上。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SILK_CLOTH_INDUSTRY_DESCRIPTION",                        "{1_CityName}的织女用光滑的丝线织出薄如蝉翼的绸缎，流光溢彩。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SILK_CLOTH_CORPORATION_DESCRIPTION",                     "{1_CityName}丝绸晚礼服是我国影星们踏上红毯时的自信之选。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SILK_MINTING_INDUSTRY_DESCRIPTION",                      "一卷卷{1_CityName}素绸在商路上堪比硬通货，可换取远方的马匹和宝石。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SILK_MINTING_CORPORATION_DESCRIPTION",                   "在经济危机中，{1_CityName}生丝甚至一度扮演了外汇储备的角色。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_SILVER_INDUSTRY_TEXT",                             "{1_CityName}山脉中银矿脉在月光下泛着苍白光芒，吸引了最早的殖民者。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_SILVER_CORPORATION_TEXT",                          "虽然白银在现代货币中的地位有所下降，但是{1_CityName}的科学家和工程师发现了白银的多种工业用途。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SILVER_METALLURGY_INDUSTRY_DESCRIPTION",                 "{1_CityName}的工匠发现银具有极佳的延展性和导电性，用于首饰与合金。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SILVER_METALLURGY_CORPORATION_DESCRIPTION",              "{1_CityName}银触点和银焊料，是我国高端电子和精密制造的关键材料。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SILVER_MINTING_INDUSTRY_DESCRIPTION",                    "{1_CityName}铸币厂的锤子不断落下，制作出带有城徽的银币，流通四方。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SILVER_MINTING_CORPORATION_DESCRIPTION",                 "{1_CityName}银条一度是我国国库储备的重中之重，维系着法定货币的信用。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_SPICES_INDUSTRY_TEXT",                             "{1_CityName}温暖潮湿的山谷里，豆蔻开出一串串芳香的花序，藏着辛香的种子。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_SPICES_CORPORATION_TEXT",                          "调味品公司将{1_CityName}的豆蔻制成各类调料粉和精油，风靡市场。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SPICES_CELEBRATION_INDUSTRY_DESCRIPTION",                "{1_CityName}在盛大节日里，家家户户烹煮的肉食中都会大把放入豆蔻提香。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SPICES_CELEBRATION_CORPORATION_DESCRIPTION",             "{1_CityName}小豆蔻被用于我国高端甜品与节庆蛋糕，象征幸福和丰饶。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SPICES_SEASONING_INDUSTRY_DESCRIPTION",                  "{1_CityName}的厨子在咖喱和饮料里只需加一点豆蔻，平凡食材立刻化为神奇。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SPICES_SEASONING_CORPORATION_DESCRIPTION",               "{1_CityName}生产的“绿仙子”豆蔻调味料，成为我国家庭厨房里制造惊喜的秘密武器。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_SUGAR_INDUSTRY_TEXT",                              "{1_CityName}广袤的冲积平原上，如林的甘蔗汇成一片甜蜜的青纱帐。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_SUGAR_CORPORATION_TEXT",                           "制糖厂沿着{1_CityName}的铁轨铺开厂房，将新鲜甘蔗变成白花花的砂糖。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SUGAR_FRUIT_INDUSTRY_DESCRIPTION",                       "{1_CityName}街头小贩娴熟地削去甘蔗紫皮，递给顾客一口清甜的咀嚼享受。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SUGAR_FRUIT_CORPORATION_DESCRIPTION",                    "鲜切甘蔗水果盒为{1_CityName}的影院和商超增添了独特的咀嚼零食。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SUGAR_SEASONING_INDUSTRY_DESCRIPTION",                   "{1_CityName}产的粗糖和糖蜜，是当地炖肉和酱汁醇厚回甘的秘诀。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SUGAR_SEASONING_CORPORATION_DESCRIPTION",                "{1_CityName}高品质红糖以其独特焦香，成为我国养生茶饮的极佳伴侣。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_TEA_INDUSTRY_TEXT",                                "{1_CityName}云雾缭绕的茶山上，采茶姑娘们的指尖轻掐嫩芽，采下整个春天。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_TEA_CORPORATION_TEXT",                             "贸易公司整合{1_CityName}的茶园，以现代工艺稳定茶叶的产量与风味。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_TEA_BEVERAGE_INDUSTRY_DESCRIPTION",                      "{1_CityName}的茶馆里，沸水冲开叶片，清香扑面，一杯清茶诉说人生百味。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_TEA_BEVERAGE_CORPORATION_DESCRIPTION",                   "{1_CityName}袋泡茶品牌让匆忙的我国现代人，随时能享受一杯好茶。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_TEA_OIL_INDUSTRY_DESCRIPTION",                           "{1_CityName}人收集茶籽，用古老的木榨出可用于烹饪与护发的山茶油。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_TEA_OIL_CORPORATION_DESCRIPTION",                        "{1_CityName}茶籽油以其高烟点和淡雅香气，成为我国高档厨房的标配用油。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_TOBACCO_INDUSTRY_TEXT",                            "{1_CityName}红土中生长的烟叶宽阔厚实，被原住民用于祭神和治病的仪式。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_TOBACCO_CORPORATION_TEXT",                         "烟草公司用现代化车间取代了{1_CityName}传统的烟丝作坊，盒装卷烟取代了散装烟丝。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_TOBACCO_CELEBRATION_INDUSTRY_DESCRIPTION",               "{1_CityName}的部落会议上，与会者传递烟斗，分享烟雾，意味着和平与友谊。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_TOBACCO_CELEBRATION_CORPORATION_DESCRIPTION",            "{1_CityName}顶级雪茄，成为我国商界庆祝交易的经典道具。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_TOBACCO_MEDICINE_INDUSTRY_DESCRIPTION",                  "{1_CityName}的巫医把烟叶敷在伤口上，认为它能驱除疼痛和邪恶。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_TOBACCO_MEDICINE_CORPORATION_DESCRIPTION",               "从{1_CityName}烟叶中提取的尼古丁，被制成我国戒烟疗法的辅助药剂。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_TRUFFLES_INDUSTRY_TEXT",                           "{1_CityName}的橡树林下，经过训练的猪和狗能嗅到泥土下松露散发的异香。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_TRUFFLES_CORPORATION_TEXT",                        "贸易集团负责组织{1_CityName}松露的采集，并通过冷链将这娇贵的美味快速运输。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_TRUFFLES_CUISINE_INDUSTRY_DESCRIPTION",                  "{1_CityName}白色松露季吸引了全球的老饕，拍卖会上频频喊出天价。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_TRUFFLES_CUISINE_CORPORATION_DESCRIPTION",               "{1_CityName}松露烩饭风靡我国的高档餐厅，体验一次可称味觉巅峰。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_TRUFFLES_SEASONING_INDUSTRY_DESCRIPTION",                "{1_CityName}的厨师仅削几片松露薄片，就能让普通的炒蛋变得无比奢华。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_TRUFFLES_SEASONING_CORPORATION_DESCRIPTION",             "{1_CityName}松露油和松露盐，让我国的家庭主妇也能轻松做出星级料理。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_WHALES_INDUSTRY_TEXT",                             "{1_CityName}近海的深沟是抹香鲸的猎场，它们与大王乌贼搏斗留下传奇。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_WHALES_CORPORATION_TEXT",                          "远洋捕鲸与加工船队从{1_CityName}出发，提炼珍贵的鲸油。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_WHALES_MARINE_PRODUCTS_INDUSTRY_DESCRIPTION",            "{1_CityName}港口充斥着鲸脂熬油的腥甜味，夜晚的街灯因此异常明亮。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_WHALES_MARINE_PRODUCTS_CORPORATION_DESCRIPTION",         "{1_CityName}抹香鲸油脂曾点亮我国的大都会，成为工业革命时期的动力基础。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_WHALES_SEA_BEAST_INDUSTRY_DESCRIPTION",                  "{1_CityName}人敬畏深海巨兽，博物馆中巨大的抹香鲸骨架震撼着每一位参观者。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_WHALES_SEA_BEAST_CORPORATION_DESCRIPTION",               "{1_CityName}抹香鲸主题的海洋科普展，在我国巡回展出，呼吁认识海洋生态。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_WINE_INDUSTRY_TEXT",                               "{1_CityName}向阳的砾石坡地，是酿酒葡萄的天堂，古老的藤蔓蜿蜒生长。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_WINE_CORPORATION_TEXT",                            "酒庄在{1_CityName}建起恢弘的城堡和地下酒窖，将葡萄酒事业推向极致。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_WINE_BREWING_INDUSTRY_DESCRIPTION",                      "{1_CityName}的酒窖里，橡木桶中的葡萄汁在时光中发酵成深红的美酒。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_WINE_BREWING_CORPORATION_DESCRIPTION",                   "{1_CityName}赤霞珠干红，在我国的品酒大赛上屡获金奖，价格不菲。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_WINE_FRUIT_INDUSTRY_DESCRIPTION",                        "{1_CityName}的葡萄园也出产皮薄多汁的鲜食葡萄，供人们直接品尝夏天的甜美。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_WINE_FRUIT_CORPORATION_DESCRIPTION",                     "{1_CityName}鲜食葡萄品牌“紫月光”，通过冷链快运，在我国超市里保持刚摘的鲜度。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_ALUMINUM_INDUSTRY_TEXT",                           "{1_CityName}的红土之下，富含用于提炼铝的黏土，带来现代金属的曙光。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_ALUMINUM_CORPORATION_TEXT",                        "电解铝冶炼厂在{1_CityName}拔地而起，利用充沛的电力将黏土变为银白的铝材。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_ALUMINUM_CHEMISTRY_INDUSTRY_DESCRIPTION",                "{1_CityName}化学实验室将铝用作还原剂和制造净水絮凝剂的原料。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_ALUMINUM_CHEMISTRY_CORPORATION_DESCRIPTION",             "{1_CityName}的氧化铝与铝盐产品，是我国净水处理和化妆品工业的关键上游。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_ALUMINUM_CONSTRUCTION_INDUSTRY_DESCRIPTION",             "{1_CityName}将轻巧坚固的铝合金用于飞艇骨架和摩天楼的幕墙框架。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_ALUMINUM_CONSTRUCTION_CORPORATION_DESCRIPTION",          "{1_CityName}铝材基地为我国的航空航天与高速列车提供了轻盈的身躯。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_COAL_INDUSTRY_TEXT",                               "{1_CityName}地层中那层黝黑发亮的石炭，是大自然的压缩太阳能。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_COAL_CORPORATION_TEXT",                            "煤炭康采恩在{1_CityName}开凿深井，用巨量的化石燃料驱动电力设备。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_COAL_CHEMISTRY_INDUSTRY_DESCRIPTION",                    "{1_CityName}的煤焦化工厂将煤炼成煤气和焦炭，顺带提炼出煤焦油。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_COAL_CHEMISTRY_CORPORATION_DESCRIPTION",                 "{1_CityName}煤化工综合体向我国供应了从染料、塑料到炸药的万千化工品。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_COAL_FUEL_INDUSTRY_DESCRIPTION",                         "{1_CityName}的机车烧着本地煤，拉着长长的车厢跨过山河，吞云吐雾。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_COAL_FUEL_CORPORATION_DESCRIPTION",                      "{1_CityName}无烟煤是我国冬季集中供暖最可靠的保障，温暖千家万户。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_HORSES_INDUSTRY_TEXT",                             "{1_CityName}的优良草场上，骏马如风一般掠过，是战士与旅人最忠诚的伙伴。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_HORSES_CORPORATION_TEXT",                          "军马场与现代马业公司在{1_CityName}发展良种马。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_HORSES_LEATHER_INDUSTRY_DESCRIPTION",                    "{1_CityName}生产着结实耐磨的马皮，用来制作马靴、缰绳和骑兵甲胄。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_HORSES_LEATHER_CORPORATION_DESCRIPTION",                 "{1_CityName}马臀皮因其致密的纤维，是我国定制顶级皮鞋和皮包的稀有原料。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_HORSES_TRANSIT_INDUSTRY_DESCRIPTION",                    "{1_CityName}的驿站网络中，换马不换人，日夜兼程传递着十万火急的文书。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_HORSES_TRANSIT_CORPORATION_DESCRIPTION",                 "{1_CityName}竞技赛马与马车观光为我国的旅游业注入了古典优雅的灵魂。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_IRON_INDUSTRY_TEXT",                               "{1_CityName}的山岭蕴藏着赤红的铁矿石，古老的炼铁炉火光熊熊。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_IRON_CORPORATION_TEXT",                            "钢铁联合企业在{1_CityName}竖起了巨大的高炉，奔流的铁水映红半边天空。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_IRON_CONSTRUCTION_INDUSTRY_DESCRIPTION",                 "{1_CityName}的铁匠铺叮当不绝，将生铁百锻成钢，造就坚固的工具与钢梁。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_IRON_CONSTRUCTION_CORPORATION_DESCRIPTION",              "{1_CityName}的H型钢与螺纹钢，撑起了我国城市化的钢筋铁骨。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_IRON_METALLURGY_INDUSTRY_DESCRIPTION",                   "{1_CityName}工匠懂得加入不同的石头与炭，使铁变为更锋利的剑或更有弹性的弹簧。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_IRON_METALLURGY_CORPORATION_DESCRIPTION",                "{1_CityName}特种钢厂为我国的精密制造提供了无数牌号的合金钢。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_NITER_INDUSTRY_TEXT",                              "{1_CityName}干旱的土壤表面，析出了一层白色的硝石结晶。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_NITER_CORPORATION_TEXT",                           "硝石资源曾经引发过战争。现在松露的硝石企业正在研究利用合成硝石的方法。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_NITER_AGRICULTURE_INDUSTRY_DESCRIPTION",                 "{1_CityName}的农民发现将硝石粉末撒入土中，庄稼会长得异常青翠茁壮。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_NITER_AGRICULTURE_CORPORATION_DESCRIPTION",              "{1_CityName}氮肥工业以硝石为起点，引爆了我国的第一次绿色革命。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_NITER_HOUSEHOLD_INDUSTRY_DESCRIPTION",                   "{1_CityName}先民用硝石制冰，在没有电的时代里为食物保鲜和制作冷饮。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_NITER_HOUSEHOLD_CORPORATION_DESCRIPTION",                "{1_CityName}的公司利用硝石制冷的原理设计出便携式冰袋，成为人们户外医疗和野营的必要工具。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_OIL_INDUSTRY_TEXT",                                "{1_CityName}荒漠之下是古生物遗骸化作的黑色黄金，油苗渗出地表，遇火即燃。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_OIL_CORPORATION_TEXT",                             "国有石油公司在{1_CityName}树起井架，钻穿岩层，放出狂喷的油龙。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_OIL_CHEMISTRY_INDUSTRY_DESCRIPTION",                     "{1_CityName}的裂解装置从石油中提取出乙烯、丙烯，构建了合成的世界。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_OIL_CHEMISTRY_CORPORATION_DESCRIPTION",                  "{1_CityName}乙烯及塑料基地，为我国提供了从包装袋到人工器官的万物。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_OIL_FUEL_INDUSTRY_DESCRIPTION",                          "{1_CityName}的炼油厂将原油分离为汽油、柴油，驱动着无数汽车与发电机。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_OIL_FUEL_CORPORATION_DESCRIPTION",                       "{1_CityName}生产的各类石油产品一直是我国工业的血液。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_URANIUM_INDUSTRY_TEXT",                            "科学家从{1_CityName}岩层中的沥青石中提取出了铀，是打开微观世界能量的钥匙。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_URANIUM_CORPORATION_TEXT",                         "我国核工业部门在{1_CityName}秘密生产浓缩铀，用于国家战略与清洁能源。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_URANIUM_CONSTRUCTION_INDUSTRY_DESCRIPTION",              "科学家提炼放射性同位素的过程中产生了大量废料，而{1_CityName}的工程师用这些废料生产陶瓷。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_URANIUM_CONSTRUCTION_CORPORATION_DESCRIPTION",           "虽然铀元素听起来很神秘，但是{1_CityName}生产的含铀陶瓷已经成为了我国人民日常生活的一部分。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_URANIUM_FUEL_INDUSTRY_DESCRIPTION",                      "{1_CityName}核电站的燃料棒在堆芯无声释放热能，点亮了千家万户璀璨的灯火。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_URANIUM_FUEL_CORPORATION_DESCRIPTION",                   "{1_CityName}浓缩铀为我国的航母舰队和深空探测器提供了强劲而持久的心脏。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_AMBER_INDUSTRY_TEXT",                              "琥珀在几百年前就为{1_CityName}的人民所熟知，因为从浅滩底到山丘间都可以看见这些晶莹剔透的宝物。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_AMBER_CORPORATION_TEXT",                           "琥珀饰品与艺术品公司系统收集{1_CityName}的琥珀原石，进行打磨设计。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_AMBER_ART_INDUSTRY_DESCRIPTION",                         "{1_CityName}的琥珀屋里，成千上万片琥珀镶嵌成金红色的墙壁，华美无双。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_AMBER_ART_CORPORATION_DESCRIPTION",                      "{1_CityName}琥珀画与珠宝设计师，为我国的收藏界带去了凝固时光的美学。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_AMBER_MARINE_PRODUCTS_INDUSTRY_DESCRIPTION",             "趁风暴过后，{1_CityName}的妇女们在沙滩上弯腰拾取冲上岸的海珀。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_AMBER_MARINE_PRODUCTS_CORPORATION_DESCRIPTION",          "{1_CityName}的海珀原石，因其包裹体丰富，是我国地质学家的信息宝库。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_OLIVES_INDUSTRY_TEXT",                             "{1_CityName}多石的丘陵上，银绿色的橄榄树林承载着千年的和平与丰收寓意。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_OLIVES_CORPORATION_TEXT",                          "橄榄油压榨工厂引进了温控冷榨生产线，确保{1_CityName}橄榄油的最高品质。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_OLIVES_OIL_INDUSTRY_DESCRIPTION",                        "{1_CityName}的石磨将橄榄果碾成金黄透亮的液体黄金，滴在面包上就是无上美味。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_OLIVES_OIL_CORPORATION_DESCRIPTION",                     "{1_CityName}特级初榨橄榄油，以其健康与风味，彻底征服了我国的美食界。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_OLIVES_SEASONING_INDUSTRY_DESCRIPTION",                  "用盐渍{1_CityName}橄榄配餐，能调出食材本身的鲜美，是地中海式饮食的核心。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_OLIVES_SEASONING_CORPORATION_DESCRIPTION",               "{1_CityName}油腌橄榄罐头，是我国家庭聚会冷盘和佐餐小食的宠儿。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_TURTLES_INDUSTRY_TEXT",                            "{1_CityName}洁白的沙滩上，每当月色如水，大海龟便爬上岸产下后代。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_TURTLES_CORPORATION_TEXT",                         "海龟生态研究所在{1_CityName}的浅滩记录了完整的海龟生活史。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_TURTLES_DECORATION_INDUSTRY_DESCRIPTION",                "{1_CityName}匠人将龟甲打磨抛光，制作成精美的玳瑁梳子和眼镜框。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_TURTLES_DECORATION_CORPORATION_DESCRIPTION",             "{1_CityName}仿玳瑁树脂工艺继承了古法纹理，成为我国复古时尚的关键元素。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_TURTLES_SEAFOOD_INDUSTRY_DESCRIPTION",                   "在土著传统允许下，{1_CityName}人以海龟肉为食，龟汤是难得的美味。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_TURTLES_SEAFOOD_CORPORATION_DESCRIPTION",                "{1_CityName}的传统龟汤罐头被复原，成为我国了解原始海洋文化的味觉窗口。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_C_HEAVENLY_HORSE_INDUSTRY_TEXT",                   "{1_CityName}的草原上奔跑着流汗如血的宝马，相传是天马的后代。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_C_HEAVENLY_HORSE_CORPORATION_TEXT",                "良种马繁育中心在{1_CityName}利用现代遗传学，保持汗血马的优秀血统。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_C_HEAVENLY_HORSE_BEAST_INDUSTRY_DESCRIPTION",            "{1_CityName}的汗血马身姿健美，皮毛在阳光下闪耀金属光泽，是国王的珍藏。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_C_HEAVENLY_HORSE_BEAST_CORPORATION_DESCRIPTION",         "{1_CityName}汗血马马术表演团巡演我国，每次亮相都引起轰动。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_C_HEAVENLY_HORSE_TRANSIT_INDUSTRY_DESCRIPTION",          "骑着{1_CityName}汗血马的传令兵，能在两天内横穿沙漠，传递最重要的军情。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_C_HEAVENLY_HORSE_TRANSIT_CORPORATION_DESCRIPTION",       "{1_CityName}汗血马的后代改良了我国的骑兵马和赛马品种。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_C_ZEBU_INDUSTRY_TEXT",                             "{1_CityName}河边崇拜瘤牛的仪式已经传承了十几代人。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_C_ZEBU_CORPORATION_TEXT",                          "瘤牛养殖公会在{1_CityName}利用现代牧场选育瘤牛，供给古老的仪式活动。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_C_ZEBU_BEAST_INDUSTRY_DESCRIPTION",                      "{1_CityName}的瘤牛被看作是神圣的坐骑，装扮着华美的锦缎和铃铛参加祭祀。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_C_ZEBU_BEAST_CORPORATION_DESCRIPTION",                   "{1_CityName}瘤牛因其独特的外形，成为我国异域风情影城和动物园的明星。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_C_ZEBU_TRANSIT_INDUSTRY_DESCRIPTION",                    "{1_CityName}商队依靠瘤牛穿越干涸的荒原，它们是沙漠之舟之外的陆地之舟。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_C_ZEBU_TRANSIT_CORPORATION_DESCRIPTION",                 "{1_CityName}瘤牛帮助开拓了我国的偏远村落，至今仍是部分农场不可或缺的畜力。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_MAIZE_INDUSTRY_TEXT",                              "{1_CityName}的烈日与沃土使玉米秆长得比人还高，结出饱满的苞谷。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_MAIZE_CORPORATION_TEXT",                           "粮食加工企业在{1_CityName}建厂，将玉米转化为各类食品与工业原料。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_MAIZE_CROPS_INDUSTRY_DESCRIPTION",                       "{1_CityName}的集市上堆满了金黄色的玉米棒，是当地人的主食。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_MAIZE_CROPS_CORPORATION_DESCRIPTION",                    "玉米片与膨化食品从{1_CityName}的流水线涌出，成为我国儿童最爱的零食。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_MAIZE_SEASONING_INDUSTRY_DESCRIPTION",                   "{1_CityName}的老妇人用石臼捣碎干玉米，制成独特风味的粉末调料。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_MAIZE_SEASONING_CORPORATION_DESCRIPTION",                "{1_CityName}生产的玉米调味酱凭借其独特的烟熏辣味，在我国烹饪界占据一席之地。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_HONEY_INDUSTRY_TEXT",                              "{1_CityName}野花遍地的草甸，是养蜂人的天堂，蜂箱陈列，蜜蜂嗡鸣。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_HONEY_CORPORATION_TEXT",                           "黄金般的液态蜂蜜在{1_CityName}的加工厂过滤、装瓶，送往各地。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_HONEY_METALLURGY_INDUSTRY_DESCRIPTION",                  "{1_CityName}的铸造工匠发现蜂蜡燃烧无烟，用来制作精密铸件的模具再好不过。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_HONEY_METALLURGY_CORPORATION_DESCRIPTION",               "{1_CityName}蜂蜡失蜡铸造法，为我国的青铜雕塑和珠宝提供了完美复制工艺。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_HONEY_SEASONING_INDUSTRY_DESCRIPTION",                   "{1_CityName}的蜂蜜色泽金黄，带有花香，用它代替糖能让茶饮和糕点更健康。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_HONEY_SEASONING_CORPORATION_DESCRIPTION",                "{1_CityName}百花蜜是我国有机食品店里的明星调味品。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_SUK_CHEESE_INDUSTRY_TEXT",                         "{1_CityName}的牲畜生产香醇的乳汁，富裕的部分被加工为各种奶制品。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_SUK_CHEESE_CORPORATION_TEXT",                      "乳制品集团将{1_CityName}的传统手工奶酪技艺与现代卫生标准融合，推向全国。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SUK_CHEESE_CUISINE_INDUSTRY_DESCRIPTION",                "{1_CityName}人将奶酪擦碎了撒在热气腾腾的面条上，浓郁拉丝，幸福感满满。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SUK_CHEESE_CUISINE_CORPORATION_DESCRIPTION",             "{1_CityName}帕尔马风干酪车轮，在我国的意式餐厅里被当作镇店之宝。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SUK_CHEESE_SEASONING_INDUSTRY_DESCRIPTION",              "{1_CityName}的蓝纹奶酪滋味咸鲜刺激，只需一点，整道菜就有了灵魂。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SUK_CHEESE_SEASONING_CORPORATION_DESCRIPTION",           "{1_CityName}乳酪粉和奶酪酱，是我国零食工业和快餐业美味的秘密武器。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_SUK_CAMEL_INDUSTRY_TEXT",                          "驼铃声声，{1_CityName}是沙漠商路的枢纽，骆驼是这里最可靠的伙伴。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_SUK_CAMEL_CORPORATION_TEXT",                       "现代物流公司购入骆驼队，为地形复杂的{1_CityName}地区提供最灵活的运输方案。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SUK_CAMEL_LEATHER_INDUSTRY_DESCRIPTION",                 "{1_CityName}的皮匠利用骆驼皮制作出耐磨的鞍具与水囊，深受牧民欢迎。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SUK_CAMEL_LEATHER_CORPORATION_DESCRIPTION",              "{1_CityName}的骆驼皮工坊开发出复古风格的皮包，成为我国的时尚单品。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SUK_CAMEL_TRANSIT_INDUSTRY_DESCRIPTION",                 "{1_CityName}的驼队满载货物，往返于绿洲与城镇之间，带来远方珍奇。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SUK_CAMEL_TRANSIT_CORPORATION_DESCRIPTION",              "{1_CityName}的“丝路驼队”运输公司虽已采用卡车，但其象征的坚韧精神始终是我国的骄傲。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_SUK_OBSIDIAN_INDUSTRY_TEXT",                       "{1_CityName}的火山脚下散布着乌黑闪亮的黑曜石块，断口锋利如手术刀。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_SUK_OBSIDIAN_CORPORATION_TEXT",                    "{1_CityName}的原住民社区规模化开采黑曜石，制成工艺品传达民族文化。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SUK_OBSIDIAN_ART_INDUSTRY_DESCRIPTION",                  "{1_CityName}匠人用黑曜石制作出祭祀用的面具，漆黑的光泽里充满了神秘。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SUK_OBSIDIAN_ART_CORPORATION_DESCRIPTION",               "{1_CityName}黑曜石现代雕塑利用其材质特性，在我国的艺术展中大放异彩。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SUK_OBSIDIAN_DECORATION_INDUSTRY_DESCRIPTION",           "{1_CityName}人将黑曜石磨成镜面般的护心镜与挂坠，相信它能吸收负能量。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SUK_OBSIDIAN_DECORATION_CORPORATION_DESCRIPTION",        "{1_CityName}黑曜石吊坠和摆件，以其辟邪的寓意深受我国风水爱好者的信赖。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_SUK_SHARK_INDUSTRY_TEXT",                          "{1_CityName}海域游弋着各色鲨鱼，当地渔民尊其为海洋的守护神，谨慎互处。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_SUK_SHARK_CORPORATION_TEXT",                       "海洋生物科技公司定点捕获{1_CityName}的鲨鱼，充分提取其高价值成分。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SUK_SHARK_MARINE_PRODUCTS_INDUSTRY_DESCRIPTION",         "{1_CityName}渔民把鲨鱼皮晒干，用来打磨木器，或者做成坚韧的皮革。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SUK_SHARK_MARINE_PRODUCTS_CORPORATION_DESCRIPTION",      "{1_CityName}鱼翅曾是我国高级宴席的排面，如今已被可持续的仿翅取代。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SUK_SHARK_MEDICINE_INDUSTRY_DESCRIPTION",                "{1_CityName}的土方从鲨鱼肝脏中提炼鱼肝油，用于增强抵抗力。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_SUK_SHARK_MEDICINE_CORPORATION_DESCRIPTION",             "{1_CityName}鲨鱼软骨素和角鲨烯制品，是我国关节养护和护肤品的尖端原料。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_DLV_BISON_INDUSTRY_TEXT",                          "成群的野牛奔过{1_CityName}的大草原，轰隆声如雷，原住民敬畏地猎取它们。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_DLV_BISON_CORPORATION_TEXT",                       "{1_CityName}的牧场主围栏育肥野牛，通过科学饲养让野牛肉质更为肥美。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_DLV_BISON_CUISINE_INDUSTRY_DESCRIPTION",                 "{1_CityName}的烤肉架上，厚切的野牛肉滋滋作响，这是大地的滋味。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_DLV_BISON_CUISINE_CORPORATION_DESCRIPTION",              "{1_CityName}野牛肉牛排馆，以其豪放的风格吸引了我国无数的肉食爱好者。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_DLV_BISON_LEATHER_INDUSTRY_DESCRIPTION",                 "野牛皮厚重坚韧，{1_CityName}的手艺人将其制成可以传承几代人的皮制帐篷。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_DLV_BISON_LEATHER_CORPORATION_DESCRIPTION",              "{1_CityName}野牛皮革制成的皮靴、皮带，是我国粗犷硬汉的标志。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_GOLD_INDUSTRY_TEXT",                               "{1_CityName}的溪流中闪耀着点点金沙，引得无数人做着淘金梦蜂拥而至。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_GOLD_CORPORATION_TEXT",                            "黄金矿业集团使用氰化法大规模提取{1_CityName}的黄金矿藏。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_GOLD_METALLURGY_INDUSTRY_DESCRIPTION",                   "{1_CityName}金匠拉出细若发丝的金线，镶嵌在圣器和经匣之上。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_GOLD_METALLURGY_CORPORATION_DESCRIPTION",                "{1_CityName}半导体金丝键合线，在我国的每一块芯片中无声地传递信号。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_GOLD_MINTING_INDUSTRY_DESCRIPTION",                      "{1_CityName}的国库中码放着整块金砖，反射出的光芒让人感到稳固和安宁。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_GOLD_MINTING_CORPORATION_DESCRIPTION",                   "{1_CityName}金锭是全球我国央行间结算的最终资产，象征着绝对的财富。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_JNR_PEAT_INDUSTRY_TEXT",                           "在{1_CityName}的沼泽地带，先民掘出黑色松软的泥炭，用作取暖的薪柴。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_JNR_PEAT_CORPORATION_TEXT",                        "泥炭开采公司在{1_CityName}铺设轻轨，将泥炭作为廉价能源批量供应市场。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_JNR_PEAT_AGRICULTURE_INDUSTRY_DESCRIPTION",              "{1_CityName}的农民把干燥的泥炭混合畜粪，制成高效的基肥改良田地。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_JNR_PEAT_AGRICULTURE_CORPORATION_DESCRIPTION",           "{1_CityName}的园艺公司推出的泥炭营养钵，让我国的家庭农场主爱不释手。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_JNR_PEAT_FUEL_INDUSTRY_DESCRIPTION",                     "{1_CityName}家家户户的壁炉中燃烧着泥炭，散发出独特的泥土芳香与暖意。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_JNR_PEAT_FUEL_CORPORATION_DESCRIPTION",                  "{1_CityName}热电厂以泥炭为燃料，为我国的工业化初期提供了重要动力。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_P0K_PENGUINS_INDUSTRY_TEXT",                       "{1_CityName}的冰冻海岸是企鹅的繁殖地，它们憨态可掬，数量庞大。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_P0K_PENGUINS_CORPORATION_TEXT",                    "旅行社小心翼翼地开发{1_CityName}企鹅栖息地的极地科考与观览项目。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_P0K_PENGUINS_BEAST_INDUSTRY_DESCRIPTION",                "{1_CityName}的企鹅群摇摇摆摆过马路的景象，融化了所有人的心。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_P0K_PENGUINS_BEAST_CORPORATION_DESCRIPTION",             "{1_CityName}企鹅直播和纪录片，为我国的孩子们带来了极地启蒙。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_P0K_PENGUINS_SEA_BEAST_INDUSTRY_DESCRIPTION",            "早期探险者猎取{1_CityName}企鹅以获取皮下厚厚的油脂，用作燃料。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_P0K_PENGUINS_SEA_BEAST_CORPORATION_DESCRIPTION",         "{1_CityName}废弃的熬油锅遗迹，成为我国纪念极地开发史的警示地标。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_CVS_POMEGRANATES_INDUSTRY_TEXT",                   "{1_CityName}的庭院里，石榴树绽放火红的花，然后结出犹如装着宝石的果实。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_CVS_POMEGRANATES_CORPORATION_TEXT",                "果品公司在{1_CityName}培育观赏石榴和果树，满足不同的需求。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_CVS_POMEGRANATES_FRUIT_INDUSTRY_DESCRIPTION",            "剖开{1_CityName}产的硕大石榴，晶莹如红玛瑙般的籽粒密密匝匝，甘甜生津。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_CVS_POMEGRANATES_FRUIT_CORPORATION_DESCRIPTION",         "{1_CityName}石榴汁品牌将这一古老水果变成抗氧化的健康饮品，风靡我国。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_CVS_POMEGRANATES_ORNAMENTAL_INDUSTRY_DESCRIPTION",       "{1_CityName}将虬枝苍劲的石榴老桩制成盆景，象征多子多福，点缀着雅致厅堂。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_CVS_POMEGRANATES_ORNAMENTAL_CORPORATION_DESCRIPTION",    "{1_CityName}石榴盆景出口海外，成为我国园艺爱好者竞相收藏的珍品。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_P0K_PAPYRUS_INDUSTRY_TEXT",                        "{1_CityName}河畔的浅沼中，纸莎草高高挺立，顶端如太阳光芒。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_P0K_PAPYRUS_CORPORATION_TEXT",                     "文创企业以{1_CityName}的纸莎草为原料，复兴了这种传奇书写材料的生产。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_P0K_PAPYRUS_HOUSEHOLD_INDUSTRY_DESCRIPTION",             "{1_CityName}人用纸莎草编织凉鞋、篮筐和船，这种轻便的材料深入日常生活。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_P0K_PAPYRUS_HOUSEHOLD_CORPORATION_DESCRIPTION",          "{1_CityName}纸莎草纤维制作的环保墙纸和地垫，引领了我国的绿色家居潮流。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_P0K_PAPYRUS_STATIONERY_INDUSTRY_DESCRIPTION",            "{1_CityName}的匠人将纸莎草茎剖开、捶打、压制成光滑的纸卷，供书记员抄写。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_P0K_PAPYRUS_STATIONERY_CORPORATION_DESCRIPTION",         "{1_CityName}纸莎草纸成为我国艺术家绘制古风作品和颁发重要证书的首选。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_P0K_MAPLE_INDUSTRY_TEXT",                          "冬末春初，{1_CityName}的枫树林开始流淌甘甜的树液，这是森林的馈赠。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_P0K_MAPLE_CORPORATION_TEXT",                       "枫糖浆加工厂在{1_CityName}的林间建立，用管道网络收集枫液并浓缩。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_P0K_MAPLE_ORNAMENTAL_INDUSTRY_DESCRIPTION",              "{1_CityName}的枫叶在秋季燃起一片绚烂的红霞，引得无数人前来赏景。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_P0K_MAPLE_ORNAMENTAL_CORPORATION_DESCRIPTION",           "{1_CityName}枫木公园和秋季红叶节，成为我国最有名的自然旅游名片之一。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_P0K_MAPLE_SEASONING_INDUSTRY_DESCRIPTION",               "{1_CityName}人将枫糖浆淋在松饼和培根上，创造出咸甜交织的绝妙风味。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_P0K_MAPLE_SEASONING_CORPORATION_DESCRIPTION",            "{1_CityName}纯枫糖浆是我国健康轻食主义者的天然甜味剂首选。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_P0K_OPAL_INDUSTRY_TEXT",                           "{1_CityName}沉积岩的裂缝中，藏着流淌着七彩游光的欧泊，如同凝固的彩虹。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_P0K_OPAL_CORPORATION_TEXT",                        "{1_CityName}地区易裂的宝石开采被人们小心翼翼地开采，有时还能发现古生物化石。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_P0K_OPAL_ART_INDUSTRY_DESCRIPTION",                      "{1_CityName}的画家研磨欧泊碎料，制作出能随光线变幻的独特颜料。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_P0K_OPAL_ART_CORPORATION_DESCRIPTION",                   "{1_CityName}欧泊镶嵌画凭借其梦幻效果，装饰了我国最高档的酒店与邮轮。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_P0K_OPAL_DECORATION_INDUSTRY_DESCRIPTION",               "{1_CityName}人相信欧泊集合了所有宝石的幸运，用它镶嵌护身符。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_P0K_OPAL_DECORATION_CORPORATION_DESCRIPTION",            "{1_CityName}黑欧泊戒指以其神秘的变彩效应，成为我国个性珠宝的宠儿。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_P0K_PLUMS_INDUSTRY_TEXT",                          "{1_CityName}的果园中，李花如雪后，紫红色的李子压弯了枝头。"),
  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_P0K_PLUMS_CORPORATION_TEXT",                       "果品工厂将不易保存的{1_CityName}李子制成果干和果酒，减少损耗。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_P0K_PLUMS_BREWING_INDUSTRY_DESCRIPTION",                 "{1_CityName}人把多肉的李子蒸馏成透明烈酒，称为“李香白兰地”。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_P0K_PLUMS_BREWING_CORPORATION_DESCRIPTION",              "{1_CityName}李酒被我国调酒师用于制作特色鸡尾酒，味道惊艳。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_P0K_PLUMS_FRUIT_INDUSTRY_DESCRIPTION",                   "一口咬下{1_CityName}产的熟软李子，甜蜜的汁水瞬间充满整个口腔。"),
  ("zh_Hans_CN",  "LOC_HD_RESOURCE_P0K_PLUMS_FRUIT_CORPORATION_DESCRIPTION",                "{1_CityName}李子果脯保留了鲜果的精华，成了我国上班族的抽屉零食。"),

  ("zh_Hans_CN",  "LOC_HD_BUILD_RESOURCE_LEU_P0K_POTATOES_INDUSTRY_TEXT",                   "{1_CityName}的高寒地带，饱满的块茎在泥土下悄然生长，养育了此地的人民。"),
